INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27190, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "帮别人做事情。", "primary_collocate": null, "pronunciation": "xié zhù", "ipa": "ɕi̯ɛ˧˥ ʈʂu˥˩", "syllable_count": 2, "sentences": [{"text": "他协助朋友处理了搬家的事务。", "target_word": "协助", "complexity_tier": "T3", "furigana": "tā xiézhù péngyou chǔ lǐ le bānjiā de shìwù", "sentence_source": "generated"}, {"text": "学生们协助交警维持路口的秩序。", "target_word": "协助", "complexity_tier": "T3", "furigana": "xuéshengmen xiézhù jiāojǐng wéichí lùkǒu de zhìxù", "sentence_source": "generated"}, {"text": "她协助妈妈准备了一桌好菜。", "target_word": "协助", "complexity_tier": "T3", "furigana": "tā xiézhù māma zhǔnbèi le yì zhuō hǎo cài", "sentence_source": "generated"}, {"text": "志愿者协助医院照顾病人。", "target_word": "协助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "如果你需要，我可以协助你办手续。", "target_word": "协助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥协助爸爸完成了这项维修工作。", "target_word": "协助", "complexity_tier": "T3", "furigana": "gēge xiézhù bàba wánchéng le zhè xiàng wéixiū gōngzuò", "sentence_source": "generated"}, {"text": "邻居协助我寻找走失的小狗。", "target_word": "协助", "complexity_tier": "T3", "furigana": "línjū xiézhù wǒ xúnzhǎo zǒushī de xiǎo gǒu", "sentence_source": "generated"}, {"text": "请你协助我整理一下这批文件。", "target_word": "协助", "complexity_tier": "T3", "furigana": "qǐng nǐ xiézhù wǒ zhěnglǐ yíxià zhè pī wénjiàn", "sentence_source": "generated"}, {"text": "他每天协助老师发作业。", "target_word": "协助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们协助大家打扫了公园。", "target_word": "协助", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "协助了", "label": "体标（完成）"}, {"form": "协助过", "label": "体标（经历）"}], "register": "书面", "sense_fingerprint": "协助：帮别人做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c983003c-8af0-4fb2-b466-92c6a7d210cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27190, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "协助", "is_correct": true, "explanation": "协助（xié zhù）：帮别人做事情。"}, {"text": "截住", "is_correct": false, "explanation": "jié 与 xié 声母不同（j 与 x），“截住”意思是拦住。"}, {"text": "邪术", "is_correct": false, "explanation": "shù 与 zhù 声母不同（sh 与 zh），“邪术”意思是邪门的法术。"}, {"text": "鞋子", "is_correct": false, "explanation": "鞋子（xié zi）：穿在脚上的东西。第二字 zi 与 zhù 的声母与声调都不同（z 与 zh）。"}], "explanations": {"协助": "协助（xié zhù）：帮别人做事情。", "截住": "jié 与 xié 声母不同（j 与 x），“截住”意思是拦住。", "邪术": "shù 与 zhù 声母不同（sh 与 zh），“邪术”意思是邪门的法术。", "鞋子": "鞋子（xié zi）：穿在脚上的东西。第二字 zi 与 zhù 的声母与声调都不同（z 与 zh）。"}, "sentence_index": null, "correct_answer": "协助"}, "level_3": {"options": [{"text": "协助", "is_correct": true, "explanation": "协助：帮朋友处理搬家的事务，正合语境。"}, {"text": "原谅", "is_correct": false, "explanation": "配价：“原谅”的宾语是人或过错，不能带“处理搬家的事务”。"}, {"text": "阻止", "is_correct": false, "explanation": "语义：“阻止”是妨碍，与“帮朋友处理事务”的语境相反。"}, {"text": "参观", "is_correct": false, "explanation": "配价：“参观”的宾语应是场所或展品，不能带“处理搬家的事务”这样的动作。"}], "explanations": {"协助": "协助：帮朋友处理搬家的事务，正合语境。", "原谅": "配价：“原谅”的宾语是人或过错，不能带“处理搬家的事务”。", "阻止": "语义：“阻止”是妨碍，与“帮朋友处理事务”的语境相反。", "参观": "配价：“参观”的宾语应是场所或展品，不能带“处理搬家的事务”这样的动作。"}, "sentence_index": 0, "correct_answer": "协助"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "士兵协助祖国的尊严。", "explanation": "这里应该用〈捍卫〉。协助指帮别人办事，不用于守护尊严这类抽象对象。"}, {"text": "奶奶细心协助我的感冒。", "explanation": "这里应该用〈照顾〉。协助指帮别人做具体的事，感冒是病，不能被协助，应说照顾。"}, {"text": "老板始终协助我的想法。", "explanation": "这里应该用〈支持〉。协助指帮别人做事，不用于对想法表示赞同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dca4975-deba-4c65-8812-2243cb648a20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27190, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "协助", "is_correct": true, "explanation": "协助：邻居帮我找小狗，正合语境。"}, {"text": "煮", "is_correct": false, "explanation": "配价：“煮”的宾语是食物，不能带“我寻找走失的小狗”这样的动作短语。"}, {"text": "缝", "is_correct": false, "explanation": "配价：“缝”的宾语是布料或衣物，不能带动作短语，句意说不通。"}, {"text": "擦", "is_correct": false, "explanation": "配价：“擦”的宾语是有形的表面或物品，不能带“我寻找走失的小狗”这样的动作短语。"}], "explanations": {"协助": "协助：邻居帮我找小狗，正合语境。", "煮": "配价：“煮”的宾语是食物，不能带“我寻找走失的小狗”这样的动作短语。", "缝": "配价：“缝”的宾语是布料或衣物，不能带动作短语，句意说不通。", "擦": "配价：“擦”的宾语是有形的表面或物品，不能带“我寻找走失的小狗”这样的动作短语。"}, "sentence_index": 6, "correct_answer": "协助"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们协助远道而来的朋友喝了一杯茶。", "explanation": "这里应该用〈招待〉。协助是帮别人做事，请客喝茶应说招待，不能说协助。"}, {"text": "他协助了伤心妹妹的心情。", "explanation": "这里应该用〈安慰〉。协助指帮别人完成具体工作，不用于安抚情绪。"}, {"text": "老板协助员工的身体健康。", "explanation": "这里应该用〈关心〉。协助的对象是工作或事务，身体健康不能被协助。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dca4975-deba-4c65-8812-2243cb648a20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27190, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他曾协助了过老师批改试卷。", "corrected_sentence": "他曾协助过老师批改试卷。", "error_description": "错误：“协助”后同时出现了“了”和“过”。正确：“协助过”，只用“过”表示曾经有过这种经历。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dca4975-deba-4c65-8812-2243cb648a20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27190, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她常常协助的我整理文件。", "corrected_sentence": "她常常协助我整理文件。", "error_description": "错误：“协助”与“我”之间多加了“的”，“协助的我”不成立。正确：“协助我整理文件”，“我”直接作“协助”的宾语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dca4975-deba-4c65-8812-2243cb648a20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
