INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27192, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "方法论就是教人怎么做事情的方法和道理。", "primary_collocate": null, "pronunciation": "fāng fǎ lùn", "ipa": "faŋ˥ fa˨˩˦ lwən˥˩", "syllable_count": 3, "sentences": [{"text": "我们要认真学习这套方法论，才能把事情做好。", "target_word": "方法论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "方法论教我们怎么做事情。", "target_word": "方法论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学方法论，可以让我们做事更有办法。", "target_word": "方法论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的方法论很简单，就是多练习。", "target_word": "方法论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，这是一种好的方法论。", "target_word": "方法论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做研究时，我们需要清楚的方法论。", "target_word": "方法论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个人解决问题的方法论都不一样。", "target_word": "方法论", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爸爸的方法论是：先想，再做。", "target_word": "方法论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听了这个故事，我懂了一种方法论。", "target_word": "方法论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们先学方法论，再做练习。", "target_word": "方法论", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种方法论", "label": "量词"}, {"form": "方法論", "label": "繁体"}], "register": "书面", "sense_fingerprint": "教人怎样做事的方法和道理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c983003c-8af0-4fb2-b466-92c6a7d210cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27192, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "方法论", "is_correct": true, "explanation": "正确：方法论是教人怎样做事的方法和道理，“学习这套……”正指这类内容。"}, {"text": "哭声", "is_correct": false, "explanation": "语义：“哭声”是哭的声音，不是可以学习的内容，“学习这套哭声”说不通。"}, {"text": "雨伞", "is_correct": false, "explanation": "搭配：“雨伞”是实物，不能被“学习”，句意说不通。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“脚步”是走路的动作，不是可以学习的内容，句意说不通。"}], "explanations": {"方法论": "正确：方法论是教人怎样做事的方法和道理，“学习这套……”正指这类内容。", "哭声": "语义：“哭声”是哭的声音，不是可以学习的内容，“学习这套哭声”说不通。", "雨伞": "搭配：“雨伞”是实物，不能被“学习”，句意说不通。", "脚步": "搭配：“脚步”是走路的动作，不是可以学习的内容，句意说不通。"}, "sentence_index": 0, "correct_answer": "方法论"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个方法论跑到了火车站。", "explanation": "这里应该用〈人〉作主语。方法论是抽象的道理，不会自己移动，不能跑到火车站。"}, {"text": "他的方法论打破了杯子。", "explanation": "这里应该用〈锤子〉作主语。锤子能打破东西；方法论是抽象的道理，不能去打破杯子。"}, {"text": "这次比赛，他的方法论拿了冠军。", "explanation": "这里应该用〈选手〉。拿冠军的是人或队伍；方法论是抽象的道理，不能参加比赛或获奖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dca4975-deba-4c65-8812-2243cb648a20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27192, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "方法论", "is_correct": true, "explanation": "正确：方法论是做事的方法和道理，“每个人解决问题的方法论都不一样”说得通。"}, {"text": "哭声", "is_correct": false, "explanation": "搭配：“解决问题的哭声”说不通，哭声不是解决问题的方式。"}, {"text": "电线", "is_correct": false, "explanation": "语义：“电线”是导电的物体，不能说“解决问题的电线”，句意不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是自然状况，不是解决问题的方式，句意不通。"}], "explanations": {"方法论": "正确：方法论是做事的方法和道理，“每个人解决问题的方法论都不一样”说得通。", "哭声": "搭配：“解决问题的哭声”说不通，哭声不是解决问题的方式。", "电线": "语义：“电线”是导电的物体，不能说“解决问题的电线”，句意不通。", "天气": "语义：“天气”是自然状况，不是解决问题的方式，句意不通。"}, "sentence_index": 6, "correct_answer": "方法论"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们先给方法论称重，再做练习。", "explanation": "这里应该用〈面粉〉。面粉有重量，可以称；方法论是抽象的道理，没有重量，不能称。"}, {"text": "我们先给方法论剪头发，再做练习。", "explanation": "这里应该用〈树枝〉。树枝可以剪；方法论是抽象的道理，没有实体，不能被剪。"}, {"text": "我们先擦方法论，再做练习。", "explanation": "这里应该用〈学〉。擦是擦拭有形的东西，方法论是抽象的道理，不能被擦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dca4975-deba-4c65-8812-2243cb648a20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27192, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老师讲了一本很实用的方法论。", "corrected_sentence": "这位老师讲了一套很实用的方法论。", "error_description": "错误：量词“本”用错。方法论是一整套道理，应用“套”；“本”用于书籍。正确：这位老师讲了一套很实用的方法论。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dca4975-deba-4c65-8812-2243cb648a20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27192, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把这套方法论学完过。", "corrected_sentence": "我们把这套方法论学完了。", "error_description": "体标错误：结果补语“学完”表示动作已完成，应用完成体“了”，不能用经历体“过”。正确：我们把这套方法论学完了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dca4975-deba-4c65-8812-2243cb648a20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
