INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27194, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "命运就是一个人一生中会发生的事情，有的是能改变的，有的是难以改变的。", "primary_collocate": null, "pronunciation": "mìng yùn", "ipa": "miŋ˥˩ yn˥˩", "syllable_count": 2, "sentences": [{"text": "每个人的命运都不一样。", "target_word": "命运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就不相信命运。", "target_word": "命运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我相信自己的命运由自己决定。", "target_word": "命运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那场大雨改变了他一家人的命运。", "target_word": "命运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的命运很苦，但是她从不放弃。", "target_word": "命运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人说，命运是写在手心里的。", "target_word": "命运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人讲起了自己一生的命运。", "target_word": "命运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对命运，我们要勇敢一点。", "target_word": "命运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只小狗的命运因为他而改变了。", "target_word": "命运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们两个人的命运连在了一起。", "target_word": "命运", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "命运共同体", "label": "复合"}], "register": "中性", "sense_fingerprint": "一个人一生中会发生的事，有的可改变有的难改变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc1e44a9-8db8-4cc7-8878-02df51e2b7e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27194, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "命运", "is_correct": true, "explanation": "正确：「每个人的命运」指每个人一生的遭遇，句意成立。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：「价格」用于商品的标价，不用来说人一生的遭遇。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气指一段时间的大气状况，不是人一生的遭遇。"}, {"text": "版本", "is_correct": false, "explanation": "语义：版本指同一作品的不同形式，不用于人。"}], "explanations": {"命运": "正确：「每个人的命运」指每个人一生的遭遇，句意成立。", "价格": "搭配：「价格」用于商品的标价，不用来说人一生的遭遇。", "天气": "语义：天气指一段时间的大气状况，不是人一生的遭遇。", "版本": "语义：版本指同一作品的不同形式，不用于人。"}, "sentence_index": 0, "correct_answer": "命运"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今天买彩票的命运特别好，一下子中了五十块。", "explanation": "这里应该用〈运气〉。命运指一生的遭遇，不用来说一次买彩票的好坏。"}, {"text": "他把命运借给了朋友，周末再还给他。", "explanation": "这里应该用〈时间〉。命运指一个人一生的遭遇，不能借出或归还，应说“借给朋友时间”。"}, {"text": "他终于等到了出国留学的命运。", "explanation": "这里应该用〈机会〉。命运指人生的走向或遭遇，不用来指可以争取的机遇，应说「等到了出国留学的机会」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e85832-ebc2-48a2-962c-332ed21d6c0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27194, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "命运", "is_correct": true, "explanation": "正确：「讲起了自己一生的命运」符合句意，「一生的」与「命运」搭配自然。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是一生的经历，不能说它是一生的遭遇。"}, {"text": "房间", "is_correct": false, "explanation": "语义：房间是空间，不属于人一生中发生的事情。"}, {"text": "发票", "is_correct": false, "explanation": "配价：「讲起」要求讲述的是经历或事件，「发票」不能被讲起。"}], "explanations": {"命运": "正确：「讲起了自己一生的命运」符合句意，「一生的」与「命运」搭配自然。", "颜色": "语义：颜色不是一生的经历，不能说它是一生的遭遇。", "房间": "语义：房间是空间，不属于人一生中发生的事情。", "发票": "配价：「讲起」要求讲述的是经历或事件，「发票」不能被讲起。"}, "sentence_index": 6, "correct_answer": "命运"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今年我的命运很旺，买什么都能赚钱。", "explanation": "这里应该用〈运势〉。运势指一段时间的运气好坏，命运指一个人一生的遭遇。"}, {"text": "他的命运很开朗，喜欢和朋友聊天。", "explanation": "这里应该用〈性格〉。命运指人生的遭遇或走向，不能用来形容一个人的性格。"}, {"text": "我们把命运装进箱子带走了。", "explanation": "这里应该用〈行李〉。命运是抽象的人生遭遇，不能装进箱子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e85832-ebc2-48a2-962c-332ed21d6c0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27194, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一把无法改变的命运。", "corrected_sentence": "这是一种无法改变的命运。", "error_description": "错误：「一把无法改变的命运」；正确：「一种无法改变的命运」。「把」用于有柄的东西，命运是抽象名词，应该用「种」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e85832-ebc2-48a2-962c-332ed21d6c0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27194, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "面对自己的一颗命运，他从不退缩。", "corrected_sentence": "面对自己的命运，他从不退缩。", "error_description": "错误：「一颗命运」；正确：「自己的命运」。「颗」用于圆形的小颗粒，不能用来计量命运，应去掉数量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e85832-ebc2-48a2-962c-332ed21d6c0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
