INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27196, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "从大量文献或数据中，按关键词或条件查找所需信息的方法。", "primary_collocate": null, "pronunciation": "xìn xī jiǎn suǒ", "ipa": "ɕin˥˩ ɕi˥ tɕjɛn˨˩˦ swɔ˨˩˦", "syllable_count": 4, "sentences": [{"text": "在网上找资料，需要学会信息检索。", "target_word": "信息检索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信息检索就像在字典里查一个字。", "target_word": "信息检索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，信息检索的第一步是想好关键词。", "target_word": "信息检索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用信息检索找到了那篇旧文章。", "target_word": "信息检索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手机软件可以帮你做信息检索。", "target_word": "信息检索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的信息检索做得很快，几分钟就找到了。", "target_word": "信息检索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小学生也要慢慢学习信息检索。", "target_word": "信息检索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆里可以做信息检索，找资料很方便。", "target_word": "信息检索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有好的信息检索，大量文件就像一座迷宫。", "target_word": "信息检索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信息检索不难，先输入词，再看结果。", "target_word": "信息检索", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "按关键词或条件从大量资料中查找所需信息的方法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7108d65a-2525-4e71-b1c7-4278ac931cc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27196, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "信息检索", "is_correct": true, "explanation": "正确：“学会信息检索”指掌握一项技能，与“在网上找资料”的语境相合。"}, {"text": "皮肤", "is_correct": false, "explanation": "语义：“皮肤”是身体器官，不能学会，与“找资料”无关。"}, {"text": "风景", "is_correct": false, "explanation": "搭配：“学会”后不能接“风景”这类可以欣赏的景物。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是自然现象，不是可以学会的技能。"}], "explanations": {"信息检索": "正确：“学会信息检索”指掌握一项技能，与“在网上找资料”的语境相合。", "皮肤": "语义：“皮肤”是身体器官，不能学会，与“找资料”无关。", "风景": "搭配：“学会”后不能接“风景”这类可以欣赏的景物。", "天气": "语义：“天气”是自然现象，不是可以学会的技能。"}, "sentence_index": 0, "correct_answer": "信息检索"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我用一把信息检索找到了那篇旧文章。", "explanation": "这里应该用〈一种〉。“把”用于有柄的器具，“信息检索”是方法，不能用“把”来计量。"}, {"text": "我用信息检索做了一顿饭。", "explanation": "“信息检索”是查找资料的方法，不能用来做饭；“做饭”需要食材和厨具。"}, {"text": "我用信息检索养大了一只小狗。", "explanation": "“信息检索”是方法，不能用来养狗；“养大”的对象应是生物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12292ff-a327-4564-a216-88e6b661bfb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27196, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "信息检索", "is_correct": true, "explanation": "正确：“学习信息检索”指学习查找资料的方法，与“小学生也要慢慢学”的语境相合。"}, {"text": "海浪", "is_correct": false, "explanation": "语义：“海浪”是自然现象，不是可以学习的内容。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语说法，与这段书面化的教育语境不合。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：“咳嗽”是身体反应，不能作为学习的对象，句子不通。"}], "explanations": {"信息检索": "正确：“学习信息检索”指学习查找资料的方法，与“小学生也要慢慢学”的语境相合。", "海浪": "语义：“海浪”是自然现象，不是可以学习的内容。", "玩意儿": "语域：“玩意儿”是口语说法，与这段书面化的教育语境不合。", "咳嗽": "语义：“咳嗽”是身体反应，不能作为学习的对象，句子不通。"}, "sentence_index": 6, "correct_answer": "信息检索"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "信息检索很柔软，可以用来铺床。", "explanation": "“信息检索”是方法，没有柔软与否，也不能用来铺床。"}, {"text": "他把信息检索放进了洗衣机。", "explanation": "“信息检索”是抽象的方法，不能放进洗衣机；“放进”只用于具体的东西。"}, {"text": "我的信息检索昨天感冒了，今天在家休息。", "explanation": "“信息检索”是方法，不会感冒；“感冒”只用于人或动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12292ff-a327-4564-a216-88e6b661bfb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27196, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一把实用的信息检索。", "corrected_sentence": "这是一种实用的信息检索。", "error_description": "错误在“信息检索”前的量词。它是方法，应用“种”计量；“把”用于有柄的器具，不能用在这里。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12292ff-a327-4564-a216-88e6b661bfb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27196, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他地信息检索方法很简单，先输入词，再看结果。", "corrected_sentence": "他的信息检索方法很简单，先输入词，再看结果。", "error_description": "错误在“的”。修饰名词“方法”时要用“的”，“地”用于修饰动词或形容词，应改为“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12292ff-a327-4564-a216-88e6b661bfb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
