INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27198, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "协作者就是一起做事情的人。", "primary_collocate": null, "pronunciation": "xié zuò zhě", "ipa": "ɕje˧˥ tsuo˥˩ ʈʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "我的协作者很聪明。", "target_word": "协作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做这个游戏时，我有两个协作者。", "target_word": "协作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "协作者和我每天都开会。", "target_word": "协作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是我的朋友，是工作上的协作者。", "target_word": "协作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的协作者住在上海。", "target_word": "协作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁是你做这个项目的协作者？", "target_word": "协作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想给协作者打个电话。", "target_word": "协作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛，我的协作者帮了我很多。", "target_word": "协作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的协作者会认真听别人说话。", "target_word": "协作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的协作者是一位年轻的女士。", "target_word": "协作者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "协作者们", "label": "复数"}], "register": "中性", "sense_fingerprint": "一起做事情的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c16dde-b3e4-4ca0-a198-05848c7b5269') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27198, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "协作者", "is_correct": true, "explanation": "正确：指和我一起做事的人，能用“聪明”来形容。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“很聪明”只用于人或有智能的事物，不能用于石头。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：桌子没有智力，“很聪明”与它搭配不当。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是能动脑的主体，与“聪明”的主语不相容。"}], "explanations": {"协作者": "正确：指和我一起做事的人，能用“聪明”来形容。", "石头": "搭配：“很聪明”只用于人或有智能的事物，不能用于石头。", "桌子": "搭配：桌子没有智力，“很聪明”与它搭配不当。", "天气": "语义：天气不是能动脑的主体，与“聪明”的主语不相容。"}, "sentence_index": 0, "correct_answer": "协作者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把这本协作者放在了书架上。", "explanation": "这里应该用〈书〉。协作者指一起做事的人，不能放在书架上。"}, {"text": "一块协作者突然从天上掉了下来。", "explanation": "这里应该用〈陨石〉。协作者指一起做事的人，不指从天上掉下的东西。"}, {"text": "我一口气喝完了那杯协作者。", "explanation": "这里应该用〈饮料〉。协作者指人，不能被喝下去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f31dd33-5180-44a2-a897-57cd7e9ac8c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27198, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "协作者", "is_correct": true, "explanation": "正确：指和我一起做事的人，可以给他打电话。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：打电话的对象须是人，桌子不能接电话。"}, {"text": "工具", "is_correct": false, "explanation": "语义：工具不能接电话，与“给……打电话”的对象冲突。"}, {"text": "空气", "is_correct": false, "explanation": "语义：“给空气打电话”不成立，与句意冲突。"}], "explanations": {"协作者": "正确：指和我一起做事的人，可以给他打电话。", "桌子": "搭配：打电话的对象须是人，桌子不能接电话。", "工具": "语义：工具不能接电话，与“给……打电话”的对象冲突。", "空气": "语义：“给空气打电话”不成立，与句意冲突。"}, "sentence_index": 6, "correct_answer": "协作者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这杯协作者太烫了，没法喝。", "explanation": "这里应该用〈咖啡〉。协作者指一起做事的人，不能用来形容饮品的温度。"}, {"text": "这场演出的协作者都坐在台下看表演。", "explanation": "这里应该用〈观众〉。协作者要共同做事，坐在台下看表演的是观众。"}, {"text": "这场比赛的协作者一直在抢分。", "explanation": "这里应该用〈对手〉。协作者是一起做事的人，抢分的是比赛中的对手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f31dd33-5180-44a2-a897-57cd7e9ac8c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27198, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次比赛，我请了一只协作者帮忙。", "corrected_sentence": "这次比赛，我请了一位协作者帮忙。", "error_description": "量词错误：“只”用于动物，指人的“协作者”应用“位”。应为“请了一位协作者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f31dd33-5180-44a2-a897-57cd7e9ac8c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27198, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "上周新来了一位很认真协作者，工作顺利多了。", "corrected_sentence": "上周新来了一位很认真的协作者，工作顺利多了。", "error_description": "缺少“的”：形容词“很认真”修饰名词“协作者”时中间要加“的”，应为“很认真的协作者”；“很认真协作者”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f31dd33-5180-44a2-a897-57cd7e9ac8c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27200, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dca4975-deba-4c65-8812-2243cb648a20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27200, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dca4975-deba-4c65-8812-2243cb648a20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27200, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手或工具把东西弄顺，比如梳头发。", "primary_collocate": null, "pronunciation": "shū lǐ", "ipa": "ʂu˥ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "她每天早上梳理头发。", "target_word": "梳理", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爸爸帮小女儿梳理头发。", "target_word": "梳理", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小狗的毛乱了，我用刷子梳理它。", "target_word": "梳理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鸭子站在水边，用嘴梳理羽毛。", "target_word": "梳理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他给马梳理长长的鬃毛。", "target_word": "梳理", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "出门以前，她对着镜子梳理好头发。", "target_word": "梳理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人把羊毛梳理得又软又顺。", "target_word": "梳理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人坐着，慢慢梳理白胡子。", "target_word": "梳理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡醒以后，头发很乱，得先梳理一下。", "target_word": "梳理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子的头发很软，妈妈用小梳子轻轻梳理。", "target_word": "梳理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "梳理了", "label": "完成体"}, {"form": "梳理着", "label": "持续体"}, {"form": "梳理过", "label": "经历体"}, {"form": "梳理梳理", "label": "重叠"}], "register": "中性", "sense_fingerprint": "用手或梳子把头发、毛等弄顺", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c983003c-8af0-4fb2-b466-92c6a7d210cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27200, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "梳理", "is_correct": true, "explanation": "正确：梳理（shū lǐ），用手或梳子把头发、毛理顺。"}, {"text": "树立", "is_correct": false, "explanation": "shù（第四声）与 shū（第一声）声调不同，树立意思是建立，与头发无关。"}, {"text": "数理", "is_correct": false, "explanation": "shù 与 shū 声调不同，数理指数学和物理，与梳头发无关。"}, {"text": "疏离", "is_correct": false, "explanation": "lí（第二声）与 lǐ（第三声）声调不同，疏离意思是关系疏远，与头发无关。"}], "explanations": {"梳理": "正确：梳理（shū lǐ），用手或梳子把头发、毛理顺。", "树立": "shù（第四声）与 shū（第一声）声调不同，树立意思是建立，与头发无关。", "数理": "shù 与 shū 声调不同，数理指数学和物理，与梳头发无关。", "疏离": "lí（第二声）与 lǐ（第三声）声调不同，疏离意思是关系疏远，与头发无关。"}, "sentence_index": null, "correct_answer": "梳理"}, "level_3": {"options": [{"text": "梳理", "is_correct": true, "explanation": "梳理指用梳子把头发理顺，与“每天早上”的日常动作相符。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”是烹饪动作，头发不能被煮。"}, {"text": "搬", "is_correct": false, "explanation": "语义：“搬”指移动物体，不能用来整理头发。"}, {"text": "缝", "is_correct": false, "explanation": "搭配：“缝”的对象通常是衣物，不说缝头发。"}], "explanations": {"梳理": "梳理指用梳子把头发理顺，与“每天早上”的日常动作相符。", "煮": "语义：“煮”是烹饪动作，头发不能被煮。", "搬": "语义：“搬”指移动物体，不能用来整理头发。", "缝": "搭配：“缝”的对象通常是衣物，不说缝头发。"}, "sentence_index": 0, "correct_answer": "梳理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把石头梳理得很整齐。", "explanation": "这里应该用〈摆放〉。梳理用于头发、毛发、羽毛等柔软的丝状物，不能用于石头。"}, {"text": "他用毛巾梳理干了孩子的脸。", "explanation": "这里应该用〈擦〉。毛巾用于擦干脸，梳理不用于吸干水分。"}, {"text": "妈妈用熨斗梳理了皱巴巴的裙子。", "explanation": "这里应该用〈抚平〉。抚平指把衣服上的皱褶弄平，梳理只表示理顺头发、羽毛等，不表示弄平衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dca4975-deba-4c65-8812-2243cb648a20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27200, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "梳理", "is_correct": true, "explanation": "梳理指把毛发等理顺，与“又软又顺”的结果相符。"}, {"text": "撕", "is_correct": false, "explanation": "语义：“撕”是扯裂，羊毛不会因被撕而变得又软又顺，句意不通。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是抛掷，与羊毛变得“又软又顺”的结果不符。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切”指切断，不说把羊毛切得又软又顺。"}], "explanations": {"梳理": "梳理指把毛发等理顺，与“又软又顺”的结果相符。", "撕": "语义：“撕”是扯裂，羊毛不会因被撕而变得又软又顺，句意不通。", "扔": "语义：“扔”是抛掷，与羊毛变得“又软又顺”的结果不符。", "切": "搭配：“切”指切断，不说把羊毛切得又软又顺。"}, "sentence_index": 6, "correct_answer": "梳理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "理发师用剪刀梳理掉了多余的头发。", "explanation": "这里应该用〈剪掉〉。剪掉指用剪刀去掉多余的部分，梳理只表示理顺，不表示去掉。"}, {"text": "他用刀把面包梳理成了片。", "explanation": "这里应该用〈切〉。切指把东西分开成块或片，梳理只表示理顺，不表示切割。"}, {"text": "妈妈在孩子脸上梳理了一点油。", "explanation": "这里应该用〈抹〉。梳理是理顺，不用于涂抹油脂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dca4975-deba-4c65-8812-2243cb648a20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27200, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸把儿子的头发梳理很整齐。", "corrected_sentence": "爸爸把儿子的头发梳理得很整齐。", "error_description": "补语标记错误：结果补语“很整齐”前需要用“得”，应说“梳理得很整齐”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dca4975-deba-4c65-8812-2243cb648a20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27200, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子的头发很乱，妈妈轻轻梳理过一下。", "corrected_sentence": "孩子的头发很乱，妈妈轻轻梳理了一下。", "error_description": "体标错误：动量补语“一下”前应用完成体“了”，不应用经历体“过”。应说“梳理了一下”，不说“梳理过一下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dca4975-deba-4c65-8812-2243cb648a20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
