INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27208, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "先做一点看看别人怎么反应。", "primary_collocate": null, "pronunciation": "shì tàn xìng", "ipa": "ʂɻ̩˥˩ tʰan˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "他试探性地笑了笑，看妈妈生不生气。", "target_word": "试探性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我先发了一条试探性的消息，等朋友回复。", "target_word": "试探性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题只是试探性的，你可以不回答。", "target_word": "试探性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明试探性地走向那只猫，怕它跑掉。", "target_word": "试探性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理试探性地提了一个价格，看客人满不满意。", "target_word": "试探性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她试探性地敲了敲门，不知道里面有没有人。", "target_word": "试探性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟试探性地问爸爸能不能买玩具。", "target_word": "试探性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一次试探性的见面，双方都很小心。", "target_word": "试探性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他先说了几句试探性的话，想知道我的想法。", "target_word": "试探性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司先在网上推出新手机，做了一些试探性的推广。", "target_word": "试探性", "complexity_tier": "T3", "furigana": "gōng sī xiān zài wǎng shàng tuī chū xīn shǒu jī, zuò le yì xiē shì tàn xìng de tuī guǎng.", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "先做一点、看别人反应的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7108d65a-2525-4e71-b1c7-4278ac931cc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27208, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "试探性", "is_correct": true, "explanation": "正确：“试探性地”修饰“笑”，表示小心地试一下、观察妈妈的反应，与后句“看妈妈生不生气”相合。"}, {"text": "胖乎乎", "is_correct": false, "explanation": "体貌：“胖乎乎”描述人的体形，不能用来修饰笑的方式。"}, {"text": "锐利", "is_correct": false, "explanation": "搭配：“锐利”多用于目光、刀锋，不用来修饰“笑”。"}, {"text": "坚决", "is_correct": false, "explanation": "语义：“坚决”表示态度立场，与“看妈妈生不生气”的犹豫语境冲突。"}], "explanations": {"试探性": "正确：“试探性地”修饰“笑”，表示小心地试一下、观察妈妈的反应，与后句“看妈妈生不生气”相合。", "胖乎乎": "体貌：“胖乎乎”描述人的体形，不能用来修饰笑的方式。", "锐利": "搭配：“锐利”多用于目光、刀锋，不用来修饰“笑”。", "坚决": "语义：“坚决”表示态度立场，与“看妈妈生不生气”的犹豫语境冲突。"}, "sentence_index": 0, "correct_answer": "试探性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他试探性地跳下了悬崖，再也没有上来。", "explanation": "这里应该用〈冒险〉。跳下悬崖是一去不回的危险行动，应说“冒险”；“试探性”只指先做一点看反应。"}, {"text": "我试探性地读完了整本书，又写了一篇长论文。", "explanation": "这里应该用〈通读〉。“试探性”只指先做一点看反应，读完整本书又写长论文是通读和完成，不是试探。"}, {"text": "他试探性地一口气吃完了整锅饭，撑得不行。", "explanation": "这里应该用〈尽兴〉。“试探性”只指先尝一尝，吃完整锅饭是尽兴地吃，应说“尽兴”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12292ff-a327-4564-a216-88e6b661bfb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27208, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "试探性", "is_correct": true, "explanation": "正确：“试探性地”修饰“问”，表示小心地试探父亲的态度，与“能不能买”的语气相合。"}, {"text": "威严", "is_correct": false, "explanation": "语义：“威严”表示有权威的神态，与孩子向爸爸小心提问的语境不合。"}, {"text": "瘦巴巴", "is_correct": false, "explanation": "体貌：“瘦巴巴”描述人的体形，不能用来修饰“问”的方式。"}, {"text": "湿漉漉", "is_correct": false, "explanation": "搭配：“湿漉漉”用于描写潮湿的东西，不能用来修饰“问”。"}], "explanations": {"试探性": "正确：“试探性地”修饰“问”，表示小心地试探父亲的态度，与“能不能买”的语气相合。", "威严": "语义：“威严”表示有权威的神态，与孩子向爸爸小心提问的语境不合。", "瘦巴巴": "体貌：“瘦巴巴”描述人的体形，不能用来修饰“问”的方式。", "湿漉漉": "搭配：“湿漉漉”用于描写潮湿的东西，不能用来修饰“问”。"}, "sentence_index": 6, "correct_answer": "试探性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他试探性地把整本字典背完了，一个字也没有漏。", "explanation": "这里应该用〈完全〉。“试探性”只指先试一试，背完整本字典是完全记住，不是试探。"}, {"text": "他试探性地解开了全部谜题，给出了标准答案。", "explanation": "解开全部谜题并给出标准答案是确定的结果，“试探性”强调的是先试一试。"}, {"text": "这场比赛的冠军是试探性的，大家都已经认定了。", "explanation": "冠军是确定的结果，不能用“试探性”形容；“试探性”只用于尚在尝试的做法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12292ff-a327-4564-a216-88e6b661bfb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27208, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她试探性的朝门口走了两步。", "corrected_sentence": "她试探性地朝门口走了两步。", "error_description": "错误在“试探性”后的“的”。“试探性”修饰动词“走”时要用“地”，“的”用于修饰名词，应改为“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12292ff-a327-4564-a216-88e6b661bfb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27208, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次试探性地谈话很顺利。", "corrected_sentence": "这次试探性的谈话很顺利。", "error_description": "错误在“试探性”后的“地”。“试探性”修饰名词“谈话”时要用“的”，“地”用于修饰动词，应改为“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12292ff-a327-4564-a216-88e6b661bfb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
