INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27210, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "悖论是一个说法，听起来很对，但想下去却和自己打架。", "primary_collocate": null, "pronunciation": "bèi lùn", "ipa": "pei˥˩ luən˥˩", "syllable_count": 2, "sentences": [{"text": "这个悖论很难懂。", "target_word": "悖论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说了一个悖论，我想了半天。", "target_word": "悖论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这句话是悖论，听起来对，想下去却不对。", "target_word": "悖论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上写了一个悖论。", "target_word": "悖论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他最爱和朋友聊各种悖论。", "target_word": "悖论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个悖论让全班同学都笑了。", "target_word": "悖论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能说说这个悖论错在哪里吗？", "target_word": "悖论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友拿一个悖论考我，我一时答不上来。", "target_word": "悖论", "complexity_tier": "T3", "furigana": "péng yǒu ná yí gè bèilùn kǎo wǒ, wǒ yìshí dá bu shànglái.", "sentence_source": "generated"}, {"text": "这本书里有十个悖论。", "target_word": "悖论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我怎么也想不通这个悖论。", "target_word": "悖论", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "种", "label": "量词"}, {"form": "逻辑悖论", "label": "复合词"}], "register": "书面", "sense_fingerprint": "听起来对、细想却自相矛盾的说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c16dde-b3e4-4ca0-a198-05848c7b5269') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27210, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "悖论", "is_correct": true, "explanation": "正确：“悖论”是抽象的命题，可以“难懂”，符合句子语境。"}, {"text": "西瓜", "is_correct": false, "explanation": "语义：“西瓜”是水果，不能被“很难懂”形容。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：“窗帘”是家具，不能被“很难懂”形容。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是人的外形特征，不能被“难懂”描述。"}], "explanations": {"悖论": "正确：“悖论”是抽象的命题，可以“难懂”，符合句子语境。", "西瓜": "语义：“西瓜”是水果，不能被“很难懂”形容。", "窗帘": "语义：“窗帘”是家具，不能被“很难懂”形容。", "身高": "体貌：“身高”是人的外形特征，不能被“难懂”描述。"}, "sentence_index": 0, "correct_answer": "悖论"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师在黑板上挂了一个悖论。", "explanation": "这里应该用〈照片〉。“挂”的对象是照片或画，悖论是抽象的命题，不能挂。"}, {"text": "老师在课上唱了一个悖论。", "explanation": "这里应该用〈歌〉。“唱”的对象是歌，悖论是抽象的命题，不能唱。"}, {"text": "他把那个悖论装进了纸箱。", "explanation": "这里应该用〈包裹〉。“装进纸箱”的对象是实物，悖论是抽象的命题，不能装箱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f31dd33-5180-44a2-a897-57cd7e9ac8c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27210, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "悖论", "is_correct": true, "explanation": "正确：“悖论”是一种说法，可以判断对错、说出错在哪里，符合语境。"}, {"text": "手套", "is_correct": false, "explanation": "语义：“手套”是穿戴用品，不是可以判断对错的说法，不能“错在哪里”。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：“钢琴”是乐器，不是可以判断对错的内容。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”是数值，“错在哪里”一般用于说法或做法，不搭配。"}], "explanations": {"悖论": "正确：“悖论”是一种说法，可以判断对错、说出错在哪里，符合语境。", "手套": "语义：“手套”是穿戴用品，不是可以判断对错的说法，不能“错在哪里”。", "钢琴": "语义：“钢琴”是乐器，不是可以判断对错的内容。", "体重": "搭配：“体重”是数值，“错在哪里”一般用于说法或做法，不搭配。"}, "sentence_index": 6, "correct_answer": "悖论"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我怎么也吃不完这个悖论。", "explanation": "这里应该用〈苹果〉。“吃”的对象是食物，悖论是抽象的命题，不能吃。"}, {"text": "他把这个悖论种在花园里。", "explanation": "这里应该用〈种子〉。“种”的对象是种子或植物，悖论是命题，不能种。"}, {"text": "他去树下摘了一个悖论。", "explanation": "这里应该用〈苹果〉。“摘”的对象是果实、花等植物，悖论是抽象的命题，不能摘。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f31dd33-5180-44a2-a897-57cd7e9ac8c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27210, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把这条悖论讲了三遍。", "corrected_sentence": "他把这个悖论讲了三遍。", "error_description": "“条”用于细长的东西，“悖论”是抽象的命题，量词应用“个”。应改为：他把这个悖论讲了三遍。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f31dd33-5180-44a2-a897-57cd7e9ac8c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27210, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想了一整天，还是理不清这份悖论。", "corrected_sentence": "我想了一整天，还是理不清这个悖论。", "error_description": "“份”用于文件、礼物等，“悖论”是抽象的命题，量词应用“个”。应改为：我想了一整天，还是理不清这个悖论。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f31dd33-5180-44a2-a897-57cd7e9ac8c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
