INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27212, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "两个东西的样子或结构一样。", "primary_collocate": null, "pronunciation": "tóng tài", "ipa": "tʰʊŋ˧˥ tʰaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "老师说这两个结构之间有同态。", "target_word": "同态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两幅画的构图同态，只是颜色不同。", "target_word": "同态", "complexity_tier": "T3", "furigana": "tóngtài", "sentence_source": "generated"}, {"text": "这两款手机的内部结构同态，外形也几乎一样。", "target_word": "同态", "complexity_tier": "T3", "furigana": "tóngtài", "sentence_source": "generated"}, {"text": "同态的意思是结构一样。", "target_word": "同态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他画了两个图，说明它们之间有同态。", "target_word": "同态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的第一章讲同态。", "target_word": "同态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要找出这两个东西的同态。", "target_word": "同态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个网络结构一样，它们有同态关系。", "target_word": "同态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用一个例子给我们解释同态。", "target_word": "同态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两张表的结构同态，只是数据不同。", "target_word": "同态", "complexity_tier": "T3", "furigana": "tóngtài", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "两个东西在样子或结构上一样的关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7108d65a-2525-4e71-b1c7-4278ac931cc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27212, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "友谊", "is_correct": false, "explanation": "搭配：“友谊”用于人与人之间，不能说“结构之间有友谊”。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：老虎是动物，不是结构之间的关系，句子不通。"}, {"text": "同态", "is_correct": true, "explanation": "正确。“同态”指两者样子或结构一样的关系，用在“有”之后作宾语。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不能作为“结构之间”的关系，句子无法理解。"}], "explanations": {"友谊": "搭配：“友谊”用于人与人之间，不能说“结构之间有友谊”。", "老虎": "语义：老虎是动物，不是结构之间的关系，句子不通。", "同态": "正确。“同态”指两者样子或结构一样的关系，用在“有”之后作宾语。", "冰箱": "语义：冰箱是家电，不能作为“结构之间”的关系，句子无法理解。"}, "sentence_index": 0, "correct_answer": "同态"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两只碗的价格同态。", "explanation": "此处应用〈相同〉。“同态”指样子或结构相同，不用于说价格。"}, {"text": "这两张照片的拍摄地点同态，都在公园里。", "explanation": "此处应用〈同一〉。“同态”指样子或结构相同，不用于说地点。"}, {"text": "我和朋友的感情很同态。", "explanation": "此处应用〈融洽〉。“同态”指事物的结构或样子相同，不用于形容人与人之间的感情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12292ff-a327-4564-a216-88e6b661bfb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27212, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "愿望", "is_correct": false, "explanation": "语义：“愿望”是人的心愿，不能被找出来作为两个东西的属性。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”属于人或动物，不是东西的结构属性，句子不通。"}, {"text": "同态", "is_correct": true, "explanation": "正确。“找出这两个东西的同态”指找出两者样子或结构一样的地方，“同态”作宾语。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”只用于说人或动物的体形，不能用于描述物品。"}], "explanations": {"愿望": "语义：“愿望”是人的心愿，不能被找出来作为两个东西的属性。", "脾气": "语义：“脾气”属于人或动物，不是东西的结构属性，句子不通。", "同态": "正确。“找出这两个东西的同态”指找出两者样子或结构一样的地方，“同态”作宾语。", "身材": "体貌：“身材”只用于说人或动物的体形，不能用于描述物品。"}, "sentence_index": 6, "correct_answer": "同态"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们两个班的人数同态。", "explanation": "此处应用〈相同〉。“同态”只说结构或样子一样，不用于说数量。"}, {"text": "这两个人的脾气很同态。", "explanation": "此处应用〈相似〉。“同态”指事物的样子或结构相同，不用于形容人的性情。"}, {"text": "两家公司的利润很同态。", "explanation": "此处应用〈相近〉。“同态”指结构或样子一样，不用于比较利润的多少。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12292ff-a327-4564-a216-88e6b661bfb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27212, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两个模型的结构了同态。", "corrected_sentence": "这两个模型的结构同态。", "error_description": "“了”位置错：“了”不能插在“结构”和“同态”之间。“结构同态”是对状态的静态描述，不带“了”，正确句为“这两个模型的结构同态”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12292ff-a327-4564-a216-88e6b661bfb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27212, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两个结构有一根同态。", "corrected_sentence": "这两个结构有一种同态。", "error_description": "量词错误：“同态”是抽象关系，应用“一种”。“根”用于细长的东西，不能修饰“同态”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12292ff-a327-4564-a216-88e6b661bfb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27214, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不同", "is_correct": true, "explanation": "“不同”与“相似”相对，指看起来差别大，是反义关系。"}, {"text": "复杂", "is_correct": false, "explanation": "“复杂”形容事物构成繁多，与“相似”没有反义关系。"}, {"text": "狭窄", "is_correct": false, "explanation": "“狭窄”形容空间小，与“相似”无关。"}, {"text": "冰冷", "is_correct": false, "explanation": "“冰冷”形容温度低，与“相似”没有反义关系。"}], "correct_answer": "不同", "explanations": {"不同": "“不同”与“相似”相对，指看起来差别大，是反义关系。", "复杂": "“复杂”形容事物构成繁多，与“相似”没有反义关系。", "狭窄": "“狭窄”形容空间小，与“相似”无关。", "冰冷": "“冰冷”形容温度低，与“相似”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f31dd33-5180-44a2-a897-57cd7e9ac8c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27214, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不同", "is_correct": true, "explanation": "“不同”与“相似”相对，指看起来差别大，是反义关系。"}, {"text": "温暖", "is_correct": false, "explanation": "“温暖”形容温度或感受，与“相似”没有反义关系。"}, {"text": "辽阔", "is_correct": false, "explanation": "“辽阔”形容面积大，与“相似”无关。"}, {"text": "清脆", "is_correct": false, "explanation": "“清脆”形容声音清亮利落，与“相似”没有反义关系。"}], "correct_answer": "不同", "explanations": {"不同": "“不同”与“相似”相对，指看起来差别大，是反义关系。", "温暖": "“温暖”形容温度或感受，与“相似”没有反义关系。", "辽阔": "“辽阔”形容面积大，与“相似”无关。", "清脆": "“清脆”形容声音清亮利落，与“相似”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f31dd33-5180-44a2-a897-57cd7e9ac8c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27214, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "两个东西很像，比如两个苹果看起来一样。", "primary_collocate": null, "pronunciation": "xiāng sì", "ipa": "ɕjɑŋ˥ sɹ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这两个苹果很相似。", "target_word": "相似", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "双胞胎长得非常相似。", "target_word": "相似", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两只小狗看起来很相似。", "target_word": "相似", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的包和你的包很相似。", "target_word": "相似", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两件衣服的颜色相似。", "target_word": "相似", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个杯子大小相似，我分不清。", "target_word": "相似", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们两个人的声音很相似。", "target_word": "相似", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两张照片太相似了。", "target_word": "相似", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟和我的帽子很相似。", "target_word": "相似", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个房间相似，都很小。", "target_word": "相似", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "相似度", "label": "复合词"}, {"form": "相似性", "label": "复合词"}], "register": "中性", "sense_fingerprint": "两个东西看起来很像", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c16dde-b3e4-4ca0-a198-05848c7b5269') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27214, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "相似", "is_correct": true, "explanation": "正确：“相似”形容两个东西看起来很像，符合句子语境。"}, {"text": "寂寞", "is_correct": false, "explanation": "语义：“寂寞”形容人的心情，苹果不能“寂寞”，与句意冲突。"}, {"text": "严肃", "is_correct": false, "explanation": "语义：“严肃”形容人的态度或场合，不能用来形容水果。"}, {"text": "粗壮", "is_correct": false, "explanation": "搭配：“粗壮”多用于树干或身躯，不说苹果很粗壮。"}], "explanations": {"相似": "正确：“相似”形容两个东西看起来很像，符合句子语境。", "寂寞": "语义：“寂寞”形容人的心情，苹果不能“寂寞”，与句意冲突。", "严肃": "语义：“严肃”形容人的态度或场合，不能用来形容水果。", "粗壮": "搭配：“粗壮”多用于树干或身躯，不说苹果很粗壮。"}, "sentence_index": 0, "correct_answer": "相似"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他和我相似十年了，是同班同学。", "explanation": "这里应该用〈相识〉。“相识”指彼此认识，“相似”指看起来很像，说认识多年要用“相识”。"}, {"text": "这两件外套相似，连颜色和扣子都一模一样。", "explanation": "这里应该用〈相同〉。“相似”指看起来像但有差别，完全一样要用“相同”。"}, {"text": "多年后我们终于相似了。", "explanation": "这里应该用〈相见〉。“相似”指事物有共同点，不指再次见面；分别多年后见到对方要用“相见”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f31dd33-5180-44a2-a897-57cd7e9ac8c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27214, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相似", "is_correct": true, "explanation": "正确：“相似”形容两个人的声音接近，符合句意。"}, {"text": "高大", "is_correct": false, "explanation": "语义：“高大”形容体积或身材，不能形容声音。"}, {"text": "宽敞", "is_correct": false, "explanation": "语义：“宽敞”形容空间大，不能形容声音。"}, {"text": "修长", "is_correct": false, "explanation": "体貌：“修长”形容身材或外形，声音不能修长。"}], "explanations": {"相似": "正确：“相似”形容两个人的声音接近，符合句意。", "高大": "语义：“高大”形容体积或身材，不能形容声音。", "宽敞": "语义：“宽敞”形容空间大，不能形容声音。", "修长": "体貌：“修长”形容身材或外形，声音不能修长。"}, "sentence_index": 6, "correct_answer": "相似"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两个室友相似得很好，每天一起吃饭。", "explanation": "这里应该用〈相处〉。“相似”指事物有共同点，不能用来说人与人之间的相处。"}, {"text": "这两个房间相似很远，走过去要五分钟。", "explanation": "这里应该用〈相隔〉。“相似”指事物的共同点，不能表示空间距离。"}, {"text": "他们俩相似地看了看对方，谁也没说话。", "explanation": "这里应该用〈相视〉。“相视”指互相看，“相似”不能表示互看的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f31dd33-5180-44a2-a897-57cd7e9ac8c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27214, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两件瓷器相似得。", "corrected_sentence": "这两件瓷器相似得很。", "error_description": "“相似”后用“得”引出补语时，补语不能缺少。“得”后面缺少补语“很”。应改为：这两件瓷器相似得很。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f31dd33-5180-44a2-a897-57cd7e9ac8c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27214, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两条裙子看起来没相似。", "corrected_sentence": "这两条裙子看起来不相似。", "error_description": "“相似”是形容词，否定要用“不”，不用“没”。应改为：这两条裙子看起来不相似。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f31dd33-5180-44a2-a897-57cd7e9ac8c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
