INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27216, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "你想做什么事，那个想法就是意图。", "primary_collocate": null, "pronunciation": "yì tú", "ipa": "i˥˩ tʰu˧˥", "syllable_count": 2, "sentences": [{"text": "我了解你的意图，可是现在不行。", "target_word": "意图", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他来这儿的意图是什么？", "target_word": "意图", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理没有说明自己的意图。", "target_word": "意图", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的意图很简单，就是想帮你。", "target_word": "意图", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都看懂了他的意图。", "target_word": "意图", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他召集这次会议的意图是选出新班长。", "target_word": "意图", "complexity_tier": "T3", "furigana": "tā zhào jí zhè cì huì yì de yì tú shì xuǎn chū xīn bān zhǎng", "sentence_source": "generated"}, {"text": "她笑着问我：“你有什么意图？”", "target_word": "意图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的意图不好，我们要小心。", "target_word": "意图", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请告诉我你们的意图。", "target_word": "意图", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一开始就没有这个意图。", "target_word": "意图", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "意图：心里想做某事的想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aaf44948-3a19-4076-a2d4-5078f32199aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27216, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "意图", "is_correct": true, "explanation": "意图 yìtú：正确答案，指心里想做某事的想法。"}, {"text": "地图", "is_correct": false, "explanation": "地图 dìtú（第四声）与 yìtú 声母不同（d 与零声母），意思是地图。"}, {"text": "议题", "is_correct": false, "explanation": "议题 yìtí 与 yìtú 第二音节韵母不同（í 与 ú），意思是讨论的问题。"}, {"text": "异读", "is_correct": false, "explanation": "异读 yìdú 第二音节声母为 d，yìtú 为 t，意思是同一个字的不同读音。"}], "explanations": {"意图": "意图 yìtú：正确答案，指心里想做某事的想法。", "地图": "地图 dìtú（第四声）与 yìtú 声母不同（d 与零声母），意思是地图。", "议题": "议题 yìtí 与 yìtú 第二音节韵母不同（í 与 ú），意思是讨论的问题。", "异读": "异读 yìdú 第二音节声母为 d，yìtú 为 t，意思是同一个字的不同读音。"}, "sentence_index": null, "correct_answer": "意图"}, "level_3": {"options": [{"text": "身高", "is_correct": false, "explanation": "体貌：“身高”属于外形特征，不是能被“了解”的想法或打算，与句意不合。"}, {"text": "意图", "is_correct": true, "explanation": "意图：指对方心里想做某事的想法，与“了解”搭配，并与后句“现在不行”呼应。"}, {"text": "嗓音", "is_correct": false, "explanation": "语义：“嗓音”指声音的特点，不是想法或打算，与句中“意图”的所指不合。"}, {"text": "体型", "is_correct": false, "explanation": "体貌：“体型”指身材外形，与“可是现在不行”所指的打算无关。"}], "explanations": {"身高": "体貌：“身高”属于外形特征，不是能被“了解”的想法或打算，与句意不合。", "意图": "意图：指对方心里想做某事的想法，与“了解”搭配，并与后句“现在不行”呼应。", "嗓音": "语义：“嗓音”指声音的特点，不是想法或打算，与句中“意图”的所指不合。", "体型": "体貌：“体型”指身材外形，与“可是现在不行”所指的打算无关。"}, "sentence_index": 0, "correct_answer": "意图"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的意图很重，我搬不动。", "explanation": "这里应该用〈行李〉。意图是抽象的想法，不能用“很重、搬不动”来形容；这里说的是有形的物品。"}, {"text": "他把意图放进了冰箱里。", "explanation": "这里应该用〈饭菜〉。意图是抽象的想法，不能放进冰箱；“放进冰箱”说的是食物。"}, {"text": "她制定了一个意图，要在学期末完成。", "explanation": "这里应该用〈计划〉。“制定”搭配计划、方案；意图指心里的想法，不说“制定意图”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc3610e4-7664-41da-9a0a-efa7ca591793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27216, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "意图", "is_correct": true, "explanation": "意图 yìtú：正确答案，指心里想做某事的想法。"}, {"text": "试图", "is_correct": false, "explanation": "试图 shìtú 与 yìtú 声母不同（sh 与零声母），意思是尝试做某事。"}, {"text": "力图", "is_correct": false, "explanation": "力图 lìtú 与 yìtú 声母不同（l 与零声母），意思是努力想要做到。"}, {"text": "一途", "is_correct": false, "explanation": "一途 yītú（第一声）与 yìtú 声调不同，意思是一条道路。"}], "explanations": {"意图": "意图 yìtú：正确答案，指心里想做某事的想法。", "试图": "试图 shìtú 与 yìtú 声母不同（sh 与零声母），意思是尝试做某事。", "力图": "力图 lìtú 与 yìtú 声母不同（l 与零声母），意思是努力想要做到。", "一途": "一途 yītú（第一声）与 yìtú 声调不同，意思是一条道路。"}, "sentence_index": null, "correct_answer": "意图"}, "level_3": {"options": [{"text": "体重", "is_correct": false, "explanation": "搭配：“你有什么体重”不成话，体重是身体属性，不能用“有什么”来提问。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“你有什么身高”不成话，身高不能用“有什么”询问。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“体温”是身体的温度，“你有什么体温”不成话。"}, {"text": "意图", "is_correct": true, "explanation": "意图：指对方心里想做什么的打算，是笑着追问时最自然的宾语。"}], "explanations": {"体重": "搭配：“你有什么体重”不成话，体重是身体属性，不能用“有什么”来提问。", "身高": "搭配：“你有什么身高”不成话，身高不能用“有什么”询问。", "体温": "搭配：“体温”是身体的温度，“你有什么体温”不成话。", "意图": "意图：指对方心里想做什么的打算，是笑着追问时最自然的宾语。"}, "sentence_index": 6, "correct_answer": "意图"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他那只意图我猜不透。", "explanation": "这里应该用〈个〉或〈种〉。“只”多用于动物或成对的东西，抽象的意图不能用“只”。"}, {"text": "他一直把意图挂在墙上，准备随时用。", "explanation": "这里应该用〈计划〉。意图是抽象的想法，不能挂在墙上；句中说的是打算，应用计划。"}, {"text": "他心里装着一根意图，不肯说出来。", "explanation": "这里应该用〈个〉或〈种〉。“根”用于细长的物体，抽象的意图不能用“根”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc3610e4-7664-41da-9a0a-efa7ca591793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27216, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我早就看透了他那只意图。", "corrected_sentence": "我早就看透了他那个意图。", "error_description": "量词错误：“意图”应搭配“个”或“种”，“只”不适用于抽象事物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc3610e4-7664-41da-9a0a-efa7ca591793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27216, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次我终于摸了清他的意图。", "corrected_sentence": "这次我终于摸清了他的意图。", "error_description": "补语位置错误：“摸清”是动补结构，“了”应紧跟补语，说“摸清了”，不能说“摸了清”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc3610e4-7664-41da-9a0a-efa7ca591793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
