INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27224, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "由很多人一起参与的。", "primary_collocate": null, "pronunciation": "qún tǐ xìng", "ipa": "tɕʰyn˧˥ tʰi˨˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "广场舞是一种群体性的活动。", "target_word": "群体性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行是群体性的，我们全班都去。", "target_word": "群体性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大扫除是群体性劳动，每个人都要参加。", "target_word": "群体性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们组织了一次群体性的志愿服务。", "target_word": "群体性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "群体性运动让整个城市热闹起来。", "target_word": "群体性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拔河是群体性的比赛，一个人玩不了。", "target_word": "群体性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司组织的群体性活动，很多人都参加。", "target_word": "群体性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的群体性庆祝从早上一直到晚上。", "target_word": "群体性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校开展了群体性的读书活动。", "target_word": "群体性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年时大家一起包饺子，这是一种群体性活动。", "target_word": "群体性", "complexity_tier": "T3", "furigana": "guò nián shí dà jiā yì qǐ bāo jiǎo zi, zhè shì yì zhǒng qún tǐ xìng huó dòng.", "sentence_source": "generated"}], "morphological_forms": [{"form": "群體性", "label": "繁体"}, {"form": "群体性活动", "label": "复合"}], "register": "书面语", "sense_fingerprint": "群体性|形容词|很多人一起参加的活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '075e48bb-16bc-4c85-a794-089c95f7240f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27224, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "群体性", "is_correct": true, "explanation": "正确：“群体性”说明活动由多人一起参与，与“广场舞”的特点相符。"}, {"text": "个体性", "is_correct": false, "explanation": "语义：“个体性”强调单个个体的特征，与“广场舞”这种多人一起跳的活动不符。"}, {"text": "私人性", "is_correct": false, "explanation": "搭配：“私人性”多修饰物品或空间，不能修饰“活动”。"}, {"text": "独立性", "is_correct": false, "explanation": "语义：“独立性”指自主、不依附他人，与多人一起跳的广场舞相矛盾。"}], "explanations": {"群体性": "正确：“群体性”说明活动由多人一起参与，与“广场舞”的特点相符。", "个体性": "语义：“个体性”强调单个个体的特征，与“广场舞”这种多人一起跳的活动不符。", "私人性": "搭配：“私人性”多修饰物品或空间，不能修饰“活动”。", "独立性": "语义：“独立性”指自主、不依附他人，与多人一起跳的广场舞相矛盾。"}, "sentence_index": 0, "correct_answer": "群体性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这支笔很群体性，我每天都用它写字。", "explanation": "这里应该用〈好用〉。群体性指多人一起做的事，笔的使用感要说“好用”，不能用群体性形容物品。"}, {"text": "他的性格很群体性，喜欢一个人安静地待着。", "explanation": "这里应该用〈合群〉。群体性描述多人一起做的事，不能直接形容一个人的性格。"}, {"text": "我一个人在房间里画画，这是一种群体性的爱好。", "explanation": "这里不能用〈群体性〉，它要求多人一起做；一个人画画应说“个人的爱好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b533e9e5-d566-4853-ac6c-d6663c12298b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27224, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "群体性", "is_correct": true, "explanation": "正确：“群体性”说明活动由很多人一起参加，与“很多人都参加”相符。"}, {"text": "个人的", "is_correct": false, "explanation": "语义：“个人的”强调单独一人，与“很多人都参加”相矛盾。"}, {"text": "单人的", "is_correct": false, "explanation": "语义：“单人的”指只有一个人参加，与“很多人都参加”相矛盾。"}, {"text": "私人的", "is_correct": false, "explanation": "语义：“私人的”指不公开的个人事务，与公司组织、很多人参加相矛盾。"}], "explanations": {"群体性": "正确：“群体性”说明活动由很多人一起参加，与“很多人都参加”相符。", "个人的": "语义：“个人的”强调单独一人，与“很多人都参加”相矛盾。", "单人的": "语义：“单人的”指只有一个人参加，与“很多人都参加”相矛盾。", "私人的": "语义：“私人的”指不公开的个人事务，与公司组织、很多人参加相矛盾。"}, "sentence_index": 6, "correct_answer": "群体性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他今天的心情很群体性，一直不说话。", "explanation": "这里应该用〈低落〉。群体性指多人一起做的事，不能形容个人的心情；表示心情不好要说“低落”。"}, {"text": "这篇文章的群体性很强，写得很清楚。", "explanation": "这里应该用〈逻辑性〉。群体性指多人一起做的事，文章条理清楚要说“逻辑性”，不能用群体性。"}, {"text": "我独自在屋里做饭，这是一次群体性的活动。", "explanation": "这里不能用〈群体性〉，它要求多人一起参与；一个人做饭应说“个人的活动”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b533e9e5-d566-4853-ac6c-d6663c12298b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27224, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末社区组织了一次很群体性的活动，很多人都来了。", "corrected_sentence": "周末社区组织了一次群体性的活动，很多人都来了。", "error_description": "多余成分：“群体性”前不能加“很”，应直接说“一次群体性的活动”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b533e9e5-d566-4853-ac6c-d6663c12298b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27224, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次活动地群体性很强，很多人都参加了。", "corrected_sentence": "这次活动的群体性很强，很多人都参加了。", "error_description": "结构助词用错：“活动”后修饰“群体性”应用“的”，不能用“地”，应说“这次活动的群体性很强”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b533e9e5-d566-4853-ac6c-d6663c12298b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
