INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27226, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "由一种事物变化出新的东西。", "primary_collocate": null, "pronunciation": "yǎn shēng", "ipa": "jɛn˨˩˦ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "牛奶可以衍生出奶酪、酸奶等产品。", "target_word": "衍生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个品牌衍生出了不少新产品。", "target_word": "衍生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个动画衍生出了很多小玩具。", "target_word": "衍生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个旧观点衍生出了新的理论。", "target_word": "衍生", "complexity_tier": "T3", "furigana": "yī gè jiù guāndiǎn yǎnshēng chū le xīn de lǐlùn.", "sentence_source": "generated"}, {"text": "旧词常常衍生出新的意思。", "target_word": "衍生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小店衍生出了好几家分店。", "target_word": "衍生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那本小说衍生出一部电视剧。", "target_word": "衍生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这款旧式相机衍生出了许多新型号。", "target_word": "衍生", "complexity_tier": "T3", "furigana": "zhè kuǎn jiùshì xiàngjī yǎnshēng chū le xǔduō xīn xínghào.", "sentence_source": "generated"}, {"text": "一个简单的问题衍生出新的问题。", "target_word": "衍生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老故事衍生出了新的传说。", "target_word": "衍生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "衍生了", "label": "体标"}, {"form": "衍生过", "label": "体标"}, {"form": "衍生物", "label": "复合"}, {"form": "衍生品", "label": "复合"}], "register": "书面", "sense_fingerprint": "由一种事物变化出新的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aaf44948-3a19-4076-a2d4-5078f32199aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27226, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "购买", "is_correct": false, "explanation": "语义：“购买”是买来现成的商品，不会由牛奶变出新产品"}, {"text": "衍生", "is_correct": true, "explanation": "正确：“衍生出”表示由牛奶发展出奶酪、酸奶等新产品"}, {"text": "浪费", "is_correct": false, "explanation": "语义：“浪费”指白白耗费，与“变出奶酪、酸奶”的意思不符"}, {"text": "运输", "is_correct": false, "explanation": "搭配：“运输”的对象是货物，不能说运输出新的产品"}], "explanations": {"购买": "语义：“购买”是买来现成的商品，不会由牛奶变出新产品", "衍生": "正确：“衍生出”表示由牛奶发展出奶酪、酸奶等新产品", "浪费": "语义：“浪费”指白白耗费，与“变出奶酪、酸奶”的意思不符", "运输": "搭配：“运输”的对象是货物，不能说运输出新的产品"}, "sentence_index": 0, "correct_answer": "衍生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈衍生了这只银勺。", "explanation": "这里应该用〈擦亮〉。衍生指由已有事物变化出新的东西，不表示把已有的东西擦亮。"}, {"text": "工程师衍生了这台坏掉的机器。", "explanation": "这里应该用〈修理〉。衍生指由已有事物变化出新的东西，不表示把坏掉的机器修好。"}, {"text": "农民衍生了一片小麦。", "explanation": "这里应该用〈收割〉。衍生指事物发展出新事物，不表示收获庄稼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc3610e4-7664-41da-9a0a-efa7ca591793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27226, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”是把文字换成另一种语言，不会由小说产生新作品"}, {"text": "衍生", "is_correct": true, "explanation": "正确：“衍生出”表示由小说发展出一部电视剧"}, {"text": "阅读", "is_correct": false, "explanation": "搭配：“阅读”的对象是文字，不说阅读出一部电视剧"}, {"text": "删减", "is_correct": false, "explanation": "语义：“删减”指删去部分内容，与“产生一部电视剧”相反"}], "explanations": {"翻译": "语义：“翻译”是把文字换成另一种语言，不会由小说产生新作品", "衍生": "正确：“衍生出”表示由小说发展出一部电视剧", "阅读": "搭配：“阅读”的对象是文字，不说阅读出一部电视剧", "删减": "语义：“删减”指删去部分内容，与“产生一部电视剧”相反"}, "sentence_index": 6, "correct_answer": "衍生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "台风衍生了这间房屋。", "explanation": "这里应该用〈破坏〉。衍生指由简单事物发展出新事物，不表示损坏已有的房屋。"}, {"text": "她衍生了客厅。", "explanation": "这里应该用〈装饰〉。衍生指产生新事物，不用于美化已有的空间。"}, {"text": "学生衍生了这篇课文。", "explanation": "这里应该用〈背诵〉。衍生指事物发展出新事物，不表示记住并念出已有的文章。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc3610e4-7664-41da-9a0a-efa7ca591793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27226, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司衍生了出几款新软件。", "corrected_sentence": "这家公司衍生出了几款新软件。", "error_description": "补语“出”应紧跟在“衍生”之后，应说“衍生出了”，不说“衍生了出”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc3610e4-7664-41da-9a0a-efa7ca591793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27226, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个品牌衍生出着几款新产品。", "corrected_sentence": "这个品牌衍生出了几款新产品。", "error_description": "“衍生出”表示动作已经完成，应用“了”，不用“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc3610e4-7664-41da-9a0a-efa7ca591793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27230, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冷静", "is_correct": false, "explanation": "冷静形容情绪镇定，与“相关”没有反义关系。"}, {"text": "宽大", "is_correct": false, "explanation": "宽大形容面积或心胸，与“相关”没有反义关系。"}, {"text": "粗糙", "is_correct": false, "explanation": "粗糙形容表面质地，与“相关”没有反义关系。"}, {"text": "无关", "is_correct": true, "explanation": "无关指彼此没有联系，与“相关”意义相反。"}], "correct_answer": "无关", "explanations": {"冷静": "冷静形容情绪镇定，与“相关”没有反义关系。", "宽大": "宽大形容面积或心胸，与“相关”没有反义关系。", "粗糙": "粗糙形容表面质地，与“相关”没有反义关系。", "无关": "无关指彼此没有联系，与“相关”意义相反。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc3610e4-7664-41da-9a0a-efa7ca591793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27230, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "清晰", "is_correct": false, "explanation": "清晰形容清楚明白，与“相关”没有反义关系。"}, {"text": "狭窄", "is_correct": false, "explanation": "狭窄形容空间小，与“相关”没有反义关系。"}, {"text": "无关", "is_correct": true, "explanation": "无关指彼此没有联系，与“相关”意义相反。"}, {"text": "柔软", "is_correct": false, "explanation": "柔软形容质地，与“相关”没有反义关系。"}], "correct_answer": "无关", "explanations": {"清晰": "清晰形容清楚明白，与“相关”没有反义关系。", "狭窄": "狭窄形容空间小，与“相关”没有反义关系。", "无关": "无关指彼此没有联系，与“相关”意义相反。", "柔软": "柔软形容质地，与“相关”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc3610e4-7664-41da-9a0a-efa7ca591793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27230, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "两个东西有关系。", "primary_collocate": null, "pronunciation": "xiāng guān", "ipa": "ɕiɑŋ˥ kuan˥", "syllable_count": 2, "sentences": [{"text": "这两本书的内容相关。", "target_word": "相关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气和心情有时相关。", "target_word": "相关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个词的意思相关吗？", "target_word": "相关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的话和这件事相关。", "target_word": "相关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的专业相关，所以常常聊天。", "target_word": "相关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两张图相关，你要一起看。", "target_word": "相关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃饭和睡觉的时间相关。", "target_word": "相关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个问题紧密相关。", "target_word": "相关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请找出和这个词相关的词。", "target_word": "相关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的工作和我的工作相关，我们可以合作。", "target_word": "相关", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不相关", "label": "否定"}, {"form": "相关性", "label": "复合"}, {"form": "相關", "label": "繁体"}], "register": "中性", "sense_fingerprint": "两个事物之间有关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aaf44948-3a19-4076-a2d4-5078f32199aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27230, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "辣", "is_correct": false, "explanation": "语义：“辣”说味道，内容不能是辣的。"}, {"text": "笨重", "is_correct": false, "explanation": "语义：“笨重”说体积或分量，与书的内容无关。"}, {"text": "相关", "is_correct": true, "explanation": "相关表示两者有关系，此处说两本书的内容彼此有关联。"}, {"text": "瘦", "is_correct": false, "explanation": "搭配：“瘦”说体形或细长的东西，不说书的内容。"}], "explanations": {"辣": "语义：“辣”说味道，内容不能是辣的。", "笨重": "语义：“笨重”说体积或分量，与书的内容无关。", "相关": "相关表示两者有关系，此处说两本书的内容彼此有关联。", "瘦": "搭配：“瘦”说体形或细长的东西，不说书的内容。"}, "sentence_index": 0, "correct_answer": "相关"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这双鞋和我的脚很相关。", "explanation": "这里应该用〈相称〉。“相关”只说有关系，鞋子与脚的大小搭配得好要用相称。"}, {"text": "我和他相关得很好。", "explanation": "这里应该用〈相处〉。“相关”说事物有关系，人与人一起生活要用相处。"}, {"text": "我们早已相关。", "explanation": "这里应该用〈相识〉。“相关”说事物有关系，早就认识的人要用相识。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc3610e4-7664-41da-9a0a-efa7ca591793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27230, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "胖", "is_correct": false, "explanation": "体貌：“胖”说人或动物的体形，时间不能说胖。"}, {"text": "溜", "is_correct": false, "explanation": "语义：“溜”指光滑、滑溜，不能用来形容时间。"}, {"text": "圆", "is_correct": false, "explanation": "体貌：“圆”说形状，时间不是圆的。"}, {"text": "相关", "is_correct": true, "explanation": "相关表示两者有关系，此处说吃饭和睡觉的时间彼此有联系。"}], "explanations": {"胖": "体貌：“胖”说人或动物的体形，时间不能说胖。", "溜": "语义：“溜”指光滑、滑溜，不能用来形容时间。", "圆": "体貌：“圆”说形状，时间不是圆的。", "相关": "相关表示两者有关系，此处说吃饭和睡觉的时间彼此有联系。"}, "sentence_index": 6, "correct_answer": "相关"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两件衣服很相关。", "explanation": "这里应该用〈相配〉。“相关”说有联系，衣服搭配得好要用相配。"}, {"text": "两个班的人数相关。", "explanation": "这里应该用〈相同〉。“相关”说有联系，数目一样要用相同。"}, {"text": "两条路相关。", "explanation": "这里应该用〈相连〉。“相关”说有联系，两地接在一起要用相连。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc3610e4-7664-41da-9a0a-efa7ca591793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27230, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两张表格没相关。", "corrected_sentence": "这两张表格不相关。", "error_description": "否定形容词“相关”要用“不”，说“不相关”。错误形式：没相关；正确形式：不相关。“没”一般用于动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc3610e4-7664-41da-9a0a-efa7ca591793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27230, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两个方案的内容紧密的相关。", "corrected_sentence": "这两个方案的内容紧密相关。", "error_description": "“紧密”与“相关”之间不加“的”，应说“紧密相关”。错误形式：紧密的相关；正确形式：紧密相关。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc3610e4-7664-41da-9a0a-efa7ca591793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
