INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27236, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "盖住东西，不让它露出来。", "primary_collocate": null, "pronunciation": "fù gài", "ipa": "fu˥˩ kai˥˩", "syllable_count": 2, "sentences": [{"text": "他用报纸覆盖住桌上的东西。", "target_word": "覆盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用布覆盖锅里的菜，免得有苍蝇。", "target_word": "覆盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件旧家具要用布覆盖起来。", "target_word": "覆盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈轻轻把小毯子覆盖在睡着的孩子身上。", "target_word": "覆盖", "complexity_tier": "T3", "furigana": "mā ma qīng qīng bǎ xiǎo tǎn zi fùgài zài shuì zhe de hái zi shēn shàng。", "sentence_source": "generated"}, {"text": "工人用布覆盖汽车，不让雨淋到。", "target_word": "覆盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想用纱布覆盖头上的伤口。", "target_word": "覆盖", "complexity_tier": "T3", "furigana": "tā xiǎng yòng shā bù fùgài tóu shàng de shāng kǒu。", "sentence_source": "generated"}, {"text": "地上的坑要用木板覆盖住。", "target_word": "覆盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用围巾覆盖半张脸，没人认出她。", "target_word": "覆盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把种子放进土里，再用土覆盖。", "target_word": "覆盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画展前，画都用白布覆盖着。", "target_word": "覆盖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "覆盖了", "label": "体标"}, {"form": "覆盖着", "label": "体标"}, {"form": "覆盖过", "label": "体标"}, {"form": "覆盖面", "label": "复合"}, {"form": "覆蓋", "label": "繁体"}], "register": "中性", "sense_fingerprint": "有意用东西把某物盖住，不让它露出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7b9a3fd-5ea1-4373-b394-1f2d643d1e41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27236, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "覆盖", "is_correct": true, "explanation": "正确：“覆盖”表示用报纸盖住东西，符合“覆盖住”的句意。"}, {"text": "撕碎", "is_correct": false, "explanation": "语义：“撕碎”指把东西撕成碎片，与用报纸遮住桌上东西的意思不符。"}, {"text": "搬走", "is_correct": false, "explanation": "语义：“搬走”指把东西移开，不是用报纸遮盖。"}, {"text": "摔碎", "is_correct": false, "explanation": "搭配：“摔碎”不能与“用报纸”搭配，报纸不能作为摔碎东西的工具。"}], "explanations": {"覆盖": "正确：“覆盖”表示用报纸盖住东西，符合“覆盖住”的句意。", "撕碎": "语义：“撕碎”指把东西撕成碎片，与用报纸遮住桌上东西的意思不符。", "搬走": "语义：“搬走”指把东西移开，不是用报纸遮盖。", "摔碎": "搭配：“摔碎”不能与“用报纸”搭配，报纸不能作为摔碎东西的工具。"}, "sentence_index": 0, "correct_answer": "覆盖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她覆盖上了厚外套，出门去了。", "explanation": "这里应该用〈穿〉。穿衣服是把衣物套在身上，覆盖指盖在某物表面，衣服套在身上要说穿。"}, {"text": "他把门覆盖上了，屋里很安静。", "explanation": "这里应该用〈关〉。关门是把门合上，覆盖指盖在表面，不能说把门覆盖上。"}, {"text": "她用湿布覆盖干净了桌子。", "explanation": "这里应该用〈擦〉。擦桌子是把灰尘去掉，覆盖表示盖住，不表示清除，要说擦干净。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1204569f-18de-4586-b2cd-e36c96a9ec29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27236, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "覆盖", "is_correct": true, "explanation": "正确：“覆盖住”表示用木板盖住坑口，符合句意。"}, {"text": "挖开", "is_correct": false, "explanation": "语义：“挖开”指挖掘使其打开，木板不能把坑挖开。"}, {"text": "掀开", "is_correct": false, "explanation": "语义：“掀开”指把盖着的东西揭起，与“覆盖住”的意思相反，且不能与“住”搭配。"}, {"text": "踩碎", "is_correct": false, "explanation": "搭配：“踩碎”不能与“住”搭配，木板被踩碎后无法盖住坑。"}], "explanations": {"覆盖": "正确：“覆盖住”表示用木板盖住坑口，符合句意。", "挖开": "语义：“挖开”指挖掘使其打开，木板不能把坑挖开。", "掀开": "语义：“掀开”指把盖着的东西揭起，与“覆盖住”的意思相反，且不能与“住”搭配。", "踩碎": "搭配：“踩碎”不能与“住”搭配，木板被踩碎后无法盖住坑。"}, "sentence_index": 6, "correct_answer": "覆盖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他覆盖好了伞，就出门了。", "explanation": "这里应该用〈撑〉。撑伞是把伞张开拿在手里遮雨，覆盖指盖在表面，不能说覆盖好了伞。"}, {"text": "她覆盖好了鞋带，就出门了。", "explanation": "这里应该用〈系〉。系鞋带是把带子打结固定，覆盖只表示盖在表面，不能用来表示系好。"}, {"text": "这把伞覆盖了雨。", "explanation": "这里应该用〈挡住〉。伞挡住的是雨，雨不能被覆盖；用伞挡雨要说挡住。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1204569f-18de-4586-b2cd-e36c96a9ec29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27236, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用布覆盖箱子上，不让灰尘进去。", "corrected_sentence": "他用布覆盖在箱子上，不让灰尘进去。", "error_description": "错误：“覆盖”后缺少介词“在”。“覆盖在……上”是固定结构，表示东西盖在某物表面。正确形式为“覆盖在箱子上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1204569f-18de-4586-b2cd-e36c96a9ec29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27236, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她用湿毛巾覆盖了在额头上。", "corrected_sentence": "她用湿毛巾覆盖在额头上。", "error_description": "错误：“覆盖”后多加了“了”。“覆盖在……上”中不能插入“了”，正确形式为“覆盖在额头上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1204569f-18de-4586-b2cd-e36c96a9ec29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
