INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27238, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "把大东西分成小块，每块可以单独做。", "primary_collocate": null, "pronunciation": "mó kuài huà", "ipa": "mo˧˥ kʰuai˥˩ xua˥˩", "syllable_count": 3, "sentences": [{"text": "做大项目要先模块化，再分给不同的人。", "target_word": "模块化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了模块化，每个小组只做一块。", "target_word": "模块化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套书架用模块化的方式制造。", "target_word": "模块化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "模块化让大工作分成很多小块。", "target_word": "模块化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们靠模块化完成了大工程。", "target_word": "模块化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "模块化的玩具，每一块都能单独拼。", "target_word": "模块化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "模块化的好处是大任务变小了。", "target_word": "模块化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搭房子时，模块化能节省很多时间。", "target_word": "模块化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做网站时，模块化让每个人负责一部分。", "target_word": "模块化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "模块化的课程可以一块一块地学。", "target_word": "模块化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "模块化设计", "label": "复合"}, {"form": "模块化生产", "label": "复合"}], "register": "中性", "sense_fingerprint": "把大的东西分成小块，每一块可以单独去做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7b9a3fd-5ea1-4373-b394-1f2d643d1e41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27238, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "模块化", "is_correct": true, "explanation": "正确。“先模块化，再分给不同的人”指先把大项目分成小块，符合句意。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：先忘记项目，再分给别人，与“做大项目”的意思不符。"}, {"text": "鼓掌", "is_correct": false, "explanation": "搭配：“鼓掌”不能作为“做大项目”的处理步骤，两者不搭配。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌与“做大项目”无关，句子不表示任何合理的做事步骤。"}], "explanations": {"模块化": "正确。“先模块化，再分给不同的人”指先把大项目分成小块，符合句意。", "忘记": "语义：先忘记项目，再分给别人，与“做大项目”的意思不符。", "鼓掌": "搭配：“鼓掌”不能作为“做大项目”的处理步骤，两者不搭配。", "唱歌": "语义：唱歌与“做大项目”无关，句子不表示任何合理的做事步骤。"}, "sentence_index": 0, "correct_answer": "模块化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "模块化让大工作变成一整块。", "explanation": "这里应该用〈合并〉。模块化是把大东西分成可单独做的小块，不能表示合成一整块。"}, {"text": "这几块零件要模块化在一起，拼成整机。", "explanation": "这里应该用〈整合〉。模块化是把大东西分成可单独做的小块，不能表示把几部分合在一起。"}, {"text": "模块化的天气很热。", "explanation": "这里把〈模块化〉误当成形容天气的性质词，它实际只表示“把大东西分成小块、分别做”的做法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1204569f-18de-4586-b2cd-e36c96a9ec29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27238, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "模块化", "is_correct": true, "explanation": "正确。“模块化的好处是大任务变小了”指分块做事带来的好处，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "体貌：颜色属于外观特征，不能作为“大任务变小”的好处。"}, {"text": "游戏", "is_correct": false, "explanation": "语义：游戏与“大任务变小”没有因果关系，句子不通。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料不能带来“大任务变小”的效果，句子语义不通。"}], "explanations": {"模块化": "正确。“模块化的好处是大任务变小了”指分块做事带来的好处，符合句意。", "颜色": "体貌：颜色属于外观特征，不能作为“大任务变小”的好处。", "游戏": "语义：游戏与“大任务变小”没有因果关系，句子不通。", "饮料": "语义：饮料不能带来“大任务变小”的效果，句子语义不通。"}, "sentence_index": 6, "correct_answer": "模块化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌的模块化很好听。", "explanation": "这里把〈模块化〉误当成形容音乐好坏的形容词，它实际只表示“把大东西分成小块、分别做”的做法。"}, {"text": "这门课程要模块化地讲完，不能分开学。", "explanation": "这里应该用〈连贯〉。模块化指分成可单独学的小块，与“不能分开学”正好相反。"}, {"text": "这块蛋糕的模块化很甜。", "explanation": "这里把〈模块化〉误当成形容味道的形容词，它实际只表示“把大东西分成小块、分别做”的做法，不能形容蛋糕的甜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1204569f-18de-4586-b2cd-e36c96a9ec29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27238, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个软件已经模块化得，每块都能单独开发。", "corrected_sentence": "这个软件已经模块化了，每块都能单独开发。", "error_description": "错误：“模块化”后表示动作完成应用助词“了”，写成“得”则句子不完整、不合语法。正确说法是“已经模块化了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1204569f-18de-4586-b2cd-e36c96a9ec29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27238, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这门模块化地课程可以一块一块地学。", "corrected_sentence": "这门模块化的课程可以一块一块地学。", "error_description": "错误：“模块化”修饰名词“课程”时应用“的”，不能用“地”。“地”用于修饰动词，应写作“模块化的课程”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1204569f-18de-4586-b2cd-e36c96a9ec29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
