INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27252, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "生意兴旺，市面热闹。", "primary_collocate": null, "pronunciation": "fán róng", "ipa": "fan˧˥ ʐʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这条街的生意很繁荣。", "target_word": "繁荣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "节日里，市场特别繁荣。", "target_word": "繁荣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座小城以前很繁荣，现在人少了。", "target_word": "繁荣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店的生意越来越繁荣。", "target_word": "繁荣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜市很繁荣，到处都是人。", "target_word": "繁荣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的旅游业非常繁荣。", "target_word": "繁荣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老城区的商店一家挨着一家，十分繁荣。", "target_word": "繁荣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为有了新地铁，这个地方变得繁荣了。", "target_word": "繁荣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的家乡是一个繁荣的小镇。", "target_word": "繁荣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座港口城市一直很繁荣。", "target_word": "繁荣", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "繁荣昌盛", "label": "复合词"}, {"form": "繁榮", "label": "繁体"}], "register": "书面", "sense_fingerprint": "生意兴旺、市面热闹发达", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7b9a3fd-5ea1-4373-b394-1f2d643d1e41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27252, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "繁荣", "is_correct": true, "explanation": "“繁荣”形容生意兴旺，与“生意很”搭配，符合语境。"}, {"text": "美丽", "is_correct": false, "explanation": "搭配：“美丽”形容外貌，不能说生意很美丽。"}, {"text": "高大", "is_correct": false, "explanation": "语义：生意不是有形的实体，不能用“高大”形容。"}, {"text": "坚硬", "is_correct": false, "explanation": "搭配：“坚硬”形容物体质地，不能用来形容生意。"}], "explanations": {"繁荣": "“繁荣”形容生意兴旺，与“生意很”搭配，符合语境。", "美丽": "搭配：“美丽”形容外貌，不能说生意很美丽。", "高大": "语义：生意不是有形的实体，不能用“高大”形容。", "坚硬": "搭配：“坚硬”形容物体质地，不能用来形容生意。"}, "sentence_index": 0, "correct_answer": "繁荣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很繁荣，经常捐钱帮助别人。", "explanation": "这里应该用〈富裕〉。“繁荣”形容生意兴旺、市面热闹，不用于形容人有钱，人有钱要用“富裕”。"}, {"text": "这个孩子很繁荣，上课时总是举手。", "explanation": "这里应该用〈活跃〉。“繁荣”形容生意或市面兴旺，形容孩子爱动、爱发言要用“活跃”。"}, {"text": "她的精力很繁荣，每天都去跑步。", "explanation": "这里应该用〈旺盛〉。“繁荣”形容生意或市面兴旺，形容精力充沛要用“旺盛”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1204569f-18de-4586-b2cd-e36c96a9ec29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27252, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "繁荣", "is_correct": true, "explanation": "“繁荣”形容商店林立、市面热闹，与前句“一家挨着一家”相符，符合语境。"}, {"text": "透明", "is_correct": false, "explanation": "搭配：“透明”形容物体能透光，不能用来形容街市。"}, {"text": "寂静", "is_correct": false, "explanation": "语义：“一家挨着一家”说明热闹，与“寂静”矛盾。"}, {"text": "清澈", "is_correct": false, "explanation": "搭配：“清澈”形容水或眼神，不能用来形容街市。"}], "explanations": {"繁荣": "“繁荣”形容商店林立、市面热闹，与前句“一家挨着一家”相符，符合语境。", "透明": "搭配：“透明”形容物体能透光，不能用来形容街市。", "寂静": "语义：“一家挨着一家”说明热闹，与“寂静”矛盾。", "清澈": "搭配：“清澈”形容水或眼神，不能用来形容街市。"}, "sentence_index": 6, "correct_answer": "繁荣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的手臂很繁荣，经常举重。", "explanation": "这里应该用〈发达〉。“繁荣”形容生意或市面兴旺，形容人体肌肉、手臂发达要用“发达”。"}, {"text": "这个老板很繁荣，但从不炫耀。", "explanation": "这里应该用〈富有〉。“繁荣”形容生意兴旺、市面热闹，形容人有钱要用“富有”。"}, {"text": "我最近工作很繁荣，每天都加班。", "explanation": "这里应该用〈繁忙〉。“繁荣”形容生意或市面兴旺，形容工作多、忙碌要用“繁忙”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1204569f-18de-4586-b2cd-e36c96a9ec29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27252, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "开了新地铁以后，这一带的生意繁荣下来了。", "corrected_sentence": "开了新地铁以后，这一带的生意繁荣起来了。", "error_description": "补语错误。“生意繁荣”由弱到强，要说“繁荣起来”；“繁荣下来”不符合表示变化的用法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1204569f-18de-4586-b2cd-e36c96a9ec29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27252, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个城市的夜市一到晚上就很繁荣地。", "corrected_sentence": "这个城市的夜市一到晚上就很繁荣。", "error_description": "错误：句末多出“地”。“地”用在动词前作状语，句末不能只留“很繁荣地”，句子不完整。正确形式为“就很繁荣”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1204569f-18de-4586-b2cd-e36c96a9ec29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
