INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27254, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很大的公司或很重要的人。", "primary_collocate": null, "pronunciation": "jù tóu", "ipa": "tɕy˥˩ tʰou˧˥", "syllable_count": 2, "sentences": [{"text": "他是电影界的巨头，认识很多明星。", "target_word": "巨头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家巨头的产品卖到了全世界。", "target_word": "巨头", "complexity_tier": "T3", "furigana": "nà jiā jù tóu de chǎn pǐn mài dào le quán shì jiè", "sentence_source": "generated"}, {"text": "小店很难和几家巨头比价格。", "target_word": "巨头", "complexity_tier": "T3", "furigana": "xiǎo diàn hěn nán hé jǐ jiā jù tóu bǐ jià gé", "sentence_source": "generated"}, {"text": "几个巨头坐在一起谈合作。", "target_word": "巨头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想成为互联网行业的巨头。", "target_word": "巨头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几家巨头准备在这里建新工厂。", "target_word": "巨头", "complexity_tier": "T3", "furigana": "jǐ jiā jù tóu zhǔn bèi zài zhè lǐ jiàn xīn gōng chǎng", "sentence_source": "generated"}, {"text": "这位巨头常常帮助穷学生。", "target_word": "巨头", "complexity_tier": "T3", "furigana": "zhè wèi jù tóu cháng cháng bāng zhù qióng xué shēng", "sentence_source": "generated"}, {"text": "这家巨头发布了一款新手机。", "target_word": "巨头", "complexity_tier": "T3", "furigana": "zhè jiā jù tóu fā bù le yī kuǎn xīn shǒu jī", "sentence_source": "generated"}, {"text": "老板说我们公司不是巨头，只是小公司。", "target_word": "巨头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "巨头也会犯错误，不一定都对。", "target_word": "巨头", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "科技巨头", "label": "复合"}, {"form": "商界巨头", "label": "复合"}], "register": "中性", "sense_fingerprint": "很大的公司或很重要的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53f15428-b18b-410e-8301-878efd0cd378') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27254, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "路人", "is_correct": false, "explanation": "语义：路人没有影响力，与句中“认识很多明星”矛盾。"}, {"text": "乞丐", "is_correct": false, "explanation": "语义：乞丐的身份与“认识很多明星”的处境不符，句意不通。"}, {"text": "农民", "is_correct": false, "explanation": "搭配：“某界的”后接的是行业或身份，“农民”不能这样搭配“电影界”。"}, {"text": "巨头", "is_correct": true, "explanation": "正确：“电影界的巨头”指在电影行业有很大影响力的人，与“认识很多明星”相符。"}], "explanations": {"路人": "语义：路人没有影响力，与句中“认识很多明星”矛盾。", "乞丐": "语义：乞丐的身份与“认识很多明星”的处境不符，句意不通。", "农民": "搭配：“某界的”后接的是行业或身份，“农民”不能这样搭配“电影界”。", "巨头": "正确：“电影界的巨头”指在电影行业有很大影响力的人，与“认识很多明星”相符。"}, "sentence_index": 0, "correct_answer": "巨头"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的巨头被石头砸了一下。", "explanation": "这里应该用〈脑袋〉。“巨头”指企业或人物，不能用来指人的头部。"}, {"text": "这只猫的巨头上有一块伤疤。", "explanation": "这里应该用〈头部〉。“巨头”指企业或人物，不能用来指动物的头部。"}, {"text": "他的巨头很圆，大家都叫他圆脑袋。", "explanation": "这里应该用〈脑袋〉。“巨头”指企业或人物，不能用来指人的头部，此处是字面的头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a845b51-b13e-483c-bfd9-dd14a4b661fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27254, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "懒汉", "is_correct": false, "explanation": "语义：“懒汉”与“常常帮助穷学生”的行为相反，句意不通。"}, {"text": "小气鬼", "is_correct": false, "explanation": "语域：“小气鬼”是口语贬称，与“帮助穷学生”的语义相反，语域也不合。"}, {"text": "恶霸", "is_correct": false, "explanation": "语义：“恶霸”是欺压他人的人，与“常常帮助穷学生”矛盾。"}, {"text": "巨头", "is_correct": true, "explanation": "正确：“这位巨头”指有实力、有影响力的人，能够常常帮助穷学生。"}], "explanations": {"懒汉": "语义：“懒汉”与“常常帮助穷学生”的行为相反，句意不通。", "小气鬼": "语域：“小气鬼”是口语贬称，与“帮助穷学生”的语义相反，语域也不合。", "恶霸": "语义：“恶霸”是欺压他人的人，与“常常帮助穷学生”矛盾。", "巨头": "正确：“这位巨头”指有实力、有影响力的人，能够常常帮助穷学生。"}, "sentence_index": 6, "correct_answer": "巨头"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条鱼的巨头很大，嘴也很宽。", "explanation": "这里应该用〈鱼头〉。“巨头”指企业或人物，不能用来指鱼的头部。"}, {"text": "他的巨头被门框撞了一下。", "explanation": "这里应该用〈额头〉。“巨头”指企业或人物，不能用来指人的额头。"}, {"text": "他的巨头上戴着一顶帽子。", "explanation": "这里应该用〈头〉。“巨头”指企业或人物，不能用来指人的头部。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a845b51-b13e-483c-bfd9-dd14a4b661fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27254, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两只巨头都出席了颁奖礼。", "corrected_sentence": "两位巨头都出席了颁奖礼。", "error_description": "量词错误：“巨头”指人或企业，应用“位”或“个”，“只”不能用于此处；正确为“两位巨头”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a845b51-b13e-483c-bfd9-dd14a4b661fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27254, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几家巨头们每年都会捐款给学校。", "corrected_sentence": "几家巨头每年都会捐款给学校。", "error_description": "多余后缀：“几家”已表示数量，后面不能再加复数后缀“们”；正确为“几家巨头”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a845b51-b13e-483c-bfd9-dd14a4b661fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
