INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27258, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "能拿到自己该有的那一份。", "primary_collocate": null, "pronunciation": "fēn dé", "ipa": "fən˥ tɤ˧˥", "syllable_count": 2, "sentences": [{"text": "妈妈切好蛋糕，每个人都分得一块。", "target_word": "分得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟分得的糖比我多。", "target_word": "分得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "活干完了，大家都分得了自己的钱。", "target_word": "分得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们三个人一起做生意，我分得了三分之一。", "target_word": "分得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老大分得了爸爸留下的那块地。", "target_word": "分得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人都分得一份，没有人少拿。", "target_word": "分得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想知道自己能分得多少钱。", "target_word": "分得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛的奖金，我只分得一点点。", "target_word": "分得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐分得了一间朝南的房间。", "target_word": "分得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明分得两张电影票，高兴极了。", "target_word": "分得", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分得了", "label": "体标"}], "register": "中性", "sense_fingerprint": "拿到自己该有的那一份", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '734ba1be-1b8e-436a-b024-5fdfa984a06b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27258, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分得", "is_correct": true, "explanation": "分得：在分配中每人拿到一块，与句中“切好”的分配语境一致。"}, {"text": "踢掉", "is_correct": false, "explanation": "语义：“踢掉”是用脚踢开，与分蛋糕、每人各得一块的语境不符。"}, {"text": "烧掉", "is_correct": false, "explanation": "语义：“烧掉”是烧毁，与切蛋糕、每人一块的分食语境不符。"}, {"text": "抛弃", "is_correct": false, "explanation": "语义：“抛弃”是丢弃不要，与每人都拿到一块的语境相反。"}], "explanations": {"分得": "分得：在分配中每人拿到一块，与句中“切好”的分配语境一致。", "踢掉": "语义：“踢掉”是用脚踢开，与分蛋糕、每人各得一块的语境不符。", "烧掉": "语义：“烧掉”是烧毁，与切蛋糕、每人一块的分食语境不符。", "抛弃": "语义：“抛弃”是丢弃不要，与每人都拿到一块的语境相反。"}, "sentence_index": 0, "correct_answer": "分得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他靠努力分得了优异的成绩。", "explanation": "这里应该用〈取得〉。分得指在分配中拿到自己那一份，成绩要靠努力取得，不能说分得。"}, {"text": "他在会上分得了一个建议。", "explanation": "这里应该用〈提出〉。分得只用于分配所得，建议是提出来的，不能说分得。"}, {"text": "他通过努力分得了经理的信任。", "explanation": "这里应该用〈得到〉。分得指在分配中拿到份额，信任是得到的，不能说分得。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acb0be78-9a99-43af-b1b3-cb80d28a5a5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27258, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分得", "is_correct": true, "explanation": "分得：拿到自己该有的那一份，与“能……多少钱”的分配语境一致。"}, {"text": "咬碎", "is_correct": false, "explanation": "搭配：“咬碎”多用于食物或硬物，不能与“钱”搭配。"}, {"text": "踩扁", "is_correct": false, "explanation": "语义：“踩扁”是用脚压平，与想知道能得到多少钱的意思不符。"}, {"text": "摔碎", "is_correct": false, "explanation": "语义：“摔碎”是摔成碎片，与想知道能得到多少钱的意思不相合。"}], "explanations": {"分得": "分得：拿到自己该有的那一份，与“能……多少钱”的分配语境一致。", "咬碎": "搭配：“咬碎”多用于食物或硬物，不能与“钱”搭配。", "踩扁": "语义：“踩扁”是用脚压平，与想知道能得到多少钱的意思不符。", "摔碎": "语义：“摔碎”是摔成碎片，与想知道能得到多少钱的意思不相合。"}, "sentence_index": 6, "correct_answer": "分得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在比赛中分得了金牌。", "explanation": "这里应该用〈摘得〉。分得是在分配中拿到份额，金牌要靠比赛摘得。"}, {"text": "他为学校分得了荣誉。", "explanation": "这里应该用〈争得〉。分得只用于分配所得，荣誉要靠努力争得。"}, {"text": "他通过考试分得了资格。", "explanation": "这里应该用〈获取〉。分得指拿到自己那一份，资格要通过考试获取，不能说分得。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acb0be78-9a99-43af-b1b3-cb80d28a5a5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27258, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "分钱的时候，他被分得了自己的那一份。", "corrected_sentence": "分钱的时候，他分得了自己的那一份。", "error_description": "错误：“分得”是主动动词，句中多加了“被”。应为“他分得了自己的那一份”，不能说“被分得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acb0be78-9a99-43af-b1b3-cb80d28a5a5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27258, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次分钱，他了分得不少。", "corrected_sentence": "这次分钱，他分得了不少。", "error_description": "错误：“了”放在了“分得”前面。“了”须紧跟动词之后，应说“他分得了不少”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acb0be78-9a99-43af-b1b3-cb80d28a5a5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
