INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27270, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a5c2b32-6777-4a54-a7ca-acda70d34102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27270, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做事情快不快，做得好不好。", "primary_collocate": null, "pronunciation": "gōng zuò xiào lǜ", "ipa": "kʊŋ˥ tswo˥˩ ɕjɑʊ˥˩ ly˥˩", "syllable_count": 4, "sentences": [{"text": "他没睡好，今天工作效率很低。", "target_word": "工作效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你工作效率这么高，是怎么做到的？", "target_word": "工作效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别总看手机，会影响你的工作效率。", "target_word": "工作效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她做事有计划，工作效率总是很高。", "target_word": "工作效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天太热，大家的工作效率都下降了。", "target_word": "工作效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听音乐能让我的工作效率更高。", "target_word": "工作效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同事们都佩服他的工作效率。", "target_word": "工作效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上我的工作效率最高。", "target_word": "工作效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作效率低的人常常晚上还在加班。", "target_word": "工作效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了提高工作效率，她把桌子收拾干净了。", "target_word": "工作效率", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一个人做事的快慢和好坏，日常说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a1f4a47-9547-4776-9185-3bf29a88cb1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27270, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工作效率", "is_correct": true, "explanation": "正确：没睡好导致做事慢、做得差，“工作效率很低”符合句意。"}, {"text": "房价", "is_correct": false, "explanation": "语义：没睡好和房价没有关系，句意不通。"}, {"text": "海拔", "is_correct": false, "explanation": "语义：海拔是地势的高度，不能描述一个人睡眠不足后的状态。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：“很低”不能用于“体积”，应说“很小”，与句中的状态描述不合。"}], "explanations": {"工作效率": "正确：没睡好导致做事慢、做得差，“工作效率很低”符合句意。", "房价": "语义：没睡好和房价没有关系，句意不通。", "海拔": "语义：海拔是地势的高度，不能描述一个人睡眠不足后的状态。", "体积": "搭配：“很低”不能用于“体积”，应说“很小”，与句中的状态描述不合。"}, "sentence_index": 0, "correct_answer": "工作效率"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆车的工作效率很快。", "explanation": "这里应该用〈速度〉。车的快慢要说“速度”，效率只说“高”或“低”。"}, {"text": "这批产品的工作效率很便宜。", "explanation": "这里应该用〈价格〉。“便宜”形容价格，“工作效率”只说“高”或“低”，不能这样形容。"}, {"text": "他每天的工作效率很长。", "explanation": "这里应该用〈工作时间〉。“长”形容时间的多少，效率只说“高”或“低”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a5c2b32-6777-4a54-a7ca-acda70d34102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27270, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工作效率", "is_correct": true, "explanation": "正确：同事佩服的是他做事快、做得好，“工作效率”符合句意。"}, {"text": "身高", "is_correct": false, "explanation": "语义：佩服一个人不会因为他的身高，句意不通。"}, {"text": "工资", "is_correct": false, "explanation": "语义：佩服一个人一般不针对工资，与“做事”的评价不合。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“佩服”不跟“体重”搭配，体重不是可以被佩服的能力。"}], "explanations": {"工作效率": "正确：同事佩服的是他做事快、做得好，“工作效率”符合句意。", "身高": "语义：佩服一个人不会因为他的身高，句意不通。", "工资": "语义：佩服一个人一般不针对工资，与“做事”的评价不合。", "体重": "搭配：“佩服”不跟“体重”搭配，体重不是可以被佩服的能力。"}, "sentence_index": 6, "correct_answer": "工作效率"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次项目的工作效率很大。", "explanation": "这里应该用〈工作量〉。效率用“高”或“低”描述，工作量才说“大”或“多”。"}, {"text": "这个方法的工作效率很轻。", "explanation": "这里应该用〈效果〉。“轻”说重量或负担，“工作效率”只说“高”或“低”，方法的作用要说“效果”。"}, {"text": "她的组织工作效率很强。", "explanation": "这里应该用〈组织能力〉。“强”形容能力，效率只说“高”或“低”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a5c2b32-6777-4a54-a7ca-acda70d34102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27270, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "早上睡够了，我的工作效率就很多。", "corrected_sentence": "早上睡够了，我的工作效率就很高。", "error_description": "错误：“很多”，应为“很高”。效率说“高”或“低”，不说“多”，“多”多用于数量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a5c2b32-6777-4a54-a7ca-acda70d34102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27270, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的工作效率高很，大家都佩服她。", "corrected_sentence": "她的工作效率很高，大家都佩服她。", "error_description": "错误：“高很”，应为“很高”。形容词作谓语时，程度副词“很”要放在形容词前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a5c2b32-6777-4a54-a7ca-acda70d34102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
