INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27272, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe460a13-b349-4f9d-a31a-e0d890935749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27272, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "没有很多钱的人。", "primary_collocate": null, "pronunciation": "qióng rén", "ipa": "tɕʰʏŋ˧˥ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "穷人没有很多钱，所以不常去饭店。", "target_word": "穷人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小城里有富人，也有穷人。", "target_word": "穷人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好心的老板常常送米给穷人。", "target_word": "穷人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "穷人的钱不多，每一分都要想好再用。", "target_word": "穷人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她说：“我是穷人，可是我很快乐。”", "target_word": "穷人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书写的是一个穷人的故事。", "target_word": "穷人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "穷人买东西时，先看价钱。", "target_word": "穷人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨天，穷人没有伞，只好在路边等。", "target_word": "穷人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把自己的钱都给了穷人。", "target_word": "穷人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要帮助穷人，不要看不起他们。", "target_word": "穷人", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "窮人", "label": "繁体"}], "register": "中性", "sense_fingerprint": "钱不多的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbaaaf73-74c4-4217-9399-ec60d52059ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27272, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "穷人", "is_correct": true, "explanation": "正确。「穷人没有很多钱，所以不常去饭店」描述没有很多钱的人，只有「穷人」能填入空格。"}, {"text": "富人", "is_correct": false, "explanation": "语义：富人一般有很多钱，「富人没有很多钱」与句意矛盾。"}, {"text": "富豪", "is_correct": false, "explanation": "语义：富豪的钱通常很多，「富豪没有很多钱」与后半句的因果不成立。"}, {"text": "富商", "is_correct": false, "explanation": "语义：富商一般钱很多，「富商没有很多钱」与句意矛盾。"}], "explanations": {"穷人": "正确。「穷人没有很多钱，所以不常去饭店」描述没有很多钱的人，只有「穷人」能填入空格。", "富人": "语义：富人一般有很多钱，「富人没有很多钱」与句意矛盾。", "富豪": "语义：富豪的钱通常很多，「富豪没有很多钱」与后半句的因果不成立。", "富商": "语义：富商一般钱很多，「富商没有很多钱」与句意矛盾。"}, "sentence_index": 0, "correct_answer": "穷人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个小镇的穷人家家都有好几辆汽车。", "explanation": "「穷人」指没有很多钱的人，「家家都有好几辆汽车」与之矛盾，句子不成立。"}, {"text": "这个穷人国家正在积极寻找外国援助。", "explanation": "「穷人」指人，说国家经济落后应该用「穷国」。"}, {"text": "这所小学的穷人学生都是富二代。", "explanation": "「穷人」指没有很多钱的人，与「富二代」矛盾，句子不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe460a13-b349-4f9d-a31a-e0d890935749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27272, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "穷人", "is_correct": true, "explanation": "正确。「穷人买东西时，先看价钱」描述钱不多的人的消费习惯，只有「穷人」能填入空格。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿不会买东西，「婴儿买东西时先看价钱」句意不通。"}, {"text": "神仙", "is_correct": false, "explanation": "语义：神仙一般不需要买东西，「神仙买东西时先看价钱」句意不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会买东西，「石头买东西时先看价钱」句意不通。"}], "explanations": {"穷人": "正确。「穷人买东西时，先看价钱」描述钱不多的人的消费习惯，只有「穷人」能填入空格。", "婴儿": "语义：婴儿不会买东西，「婴儿买东西时先看价钱」句意不通。", "神仙": "语义：神仙一般不需要买东西，「神仙买东西时先看价钱」句意不通。", "石头": "语义：石头不会买东西，「石头买东西时先看价钱」句意不通。"}, "sentence_index": 6, "correct_answer": "穷人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这项政策能帮助国家摆脱穷人的局面。", "explanation": "「摆脱」的对象应是「贫困」，「穷人」指人，不能用来表示状况。"}, {"text": "这座老城里有一片穷人窟。", "explanation": "「穷人窟」不是固定说法，表示居住区应说「贫民窟」，「穷人」只指人。"}, {"text": "这所学校的穷人生最近增加了很多。", "explanation": "「穷人」不能缩略成「生」，表示家境困难的学生应说「贫困生」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe460a13-b349-4f9d-a31a-e0d890935749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27272, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只穷人很可怜，我想帮助他。", "corrected_sentence": "这位穷人很可怜，我想帮助他。", "error_description": "错误形式「这只穷人」，量词「只」用于指人错误。正确形式「这位穷人」，指人应该用「位」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe460a13-b349-4f9d-a31a-e0d890935749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27272, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把东西送给了很穷人。", "corrected_sentence": "他把东西送给了很穷的人。", "error_description": "错误形式「很穷人」，「穷」是形容词，直接修饰名词时要加「的」。正确形式「很穷的人」，形容词修饰名词需用「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe460a13-b349-4f9d-a31a-e0d890935749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27274, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '129bcd71-d37e-4369-81ee-80399ce3f28a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27274, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '129bcd71-d37e-4369-81ee-80399ce3f28a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27274, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个人有很多钱和东西。", "primary_collocate": null, "pronunciation": "cái fù", "ipa": "tsʰaɪ˧˥ fu˥˩", "syllable_count": 2, "sentences": [{"text": "他很有钱，财富多得数不清。", "target_word": "财富", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "富人的财富常常来自生意。", "target_word": "财富", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从爷爷那里得到一大笔财富。", "target_word": "财富", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把财富留给了三个孩子。", "target_word": "财富", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人的财富比我们想的多。", "target_word": "财富", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻时他没有财富，但是很努力。", "target_word": "财富", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别看他穿得简单，其实财富很多。", "target_word": "财富", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "杂志每年公布最有钱的人和他们的财富。", "target_word": "财富", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想用自己的财富帮助穷人。", "target_word": "财富", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座大房子是他一生的财富。", "target_word": "财富", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一笔财富", "label": "量词"}, {"form": "财富观", "label": "复合"}, {"form": "財富", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一个人拥有的大量钱和东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d06d5c5-2367-404d-917b-166cece11c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27274, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "财富", "is_correct": true, "explanation": "正确：“财富”指一个人拥有的大量钱和东西，与“很有钱”呼应。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是身体特征，与“很有钱”没有关系，也不能“多得数不清”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不会“多得数不清”，句子语义不通。"}, {"text": "饭量", "is_correct": false, "explanation": "搭配：“多得数不清”不与“饭量”搭配，句意荒谬。"}], "explanations": {"财富": "正确：“财富”指一个人拥有的大量钱和东西，与“很有钱”呼应。", "身高": "体貌：身高是身体特征，与“很有钱”没有关系，也不能“多得数不清”。", "年龄": "语义：年龄不会“多得数不清”，句子语义不通。", "饭量": "搭配：“多得数不清”不与“饭量”搭配，句意荒谬。"}, "sentence_index": 0, "correct_answer": "财富"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他出门时身上带了很多财富。", "explanation": "这里应该用〈钱〉。随身携带的现金要说“钱”，财富指积累的财物总和。"}, {"text": "他这几年财富特别旺，买东西总是很顺利。", "explanation": "这里应该用〈财运〉。财运指一段时间的运气，财富是已拥有财物的总和，不能说“旺”。"}, {"text": "他在科研上取得了很大的财富。", "explanation": "这里应该用〈成就〉。财富指财物，不用于说明科研或事业上的成绩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '129bcd71-d37e-4369-81ee-80399ce3f28a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27274, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "财富", "is_correct": true, "explanation": "正确：“财富”指一个人拥有的大量钱和东西，与“穿得简单”形成对比。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温不是可以“很多”的东西，句意不通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材是外形特征，“其实身材很多”不通，也与“穿得简单”无关。"}, {"text": "血型", "is_correct": false, "explanation": "语义：血型只有有限的类别，不能说“很多”，句意不通。"}], "explanations": {"财富": "正确：“财富”指一个人拥有的大量钱和东西，与“穿得简单”形成对比。", "体温": "语义：体温不是可以“很多”的东西，句意不通。", "身材": "体貌：身材是外形特征，“其实身材很多”不通，也与“穿得简单”无关。", "血型": "语义：血型只有有限的类别，不能说“很多”，句意不通。"}, "sentence_index": 6, "correct_answer": "财富"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的财富很好，每件事都记得清清楚楚。", "explanation": "这里应该用〈记性〉。财富指财物和金钱的总和，不用来说明记忆力的好坏。"}, {"text": "他的财富每个月按时发到银行卡上。", "explanation": "这里应该用〈工资〉。财富是积累的财物总和，不是每月定期发放的款项。"}, {"text": "这部电影的财富很高，大家都喜欢。", "explanation": "这里应该用〈价值〉。财富指财物和金钱的总和，不用来评价一部电影的好坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '129bcd71-d37e-4369-81ee-80399ce3f28a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27274, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他留下了一本可观的财富。", "corrected_sentence": "他留下了一笔可观的财富。", "error_description": "错误：量词“本”；正确：量词“笔”。“本”用于书籍等，不能修饰财富。财富的量词是“笔”，错误形式是“一本财富”，正确形式是“一笔财富”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '129bcd71-d37e-4369-81ee-80399ce3f28a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27274, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个人有很财富，却很少帮助别人。", "corrected_sentence": "这个人有很多财富，却很少帮助别人。", "error_description": "错误：“很财富”；正确：“很多财富”。“很”不能直接修饰名词“财富”，表示数量多要用“很多”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '129bcd71-d37e-4369-81ee-80399ce3f28a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
