INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27276, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大人教小孩学做工作的本领。", "primary_collocate": null, "pronunciation": "zhí yè péi xùn", "ipa": "ʈʂʅ˧˥ jɛ˥˩ pʰei̯˧˥ ɕyn˥˩", "syllable_count": 4, "sentences": [{"text": "他从小接受爸爸的职业培训，学会了修车。", "target_word": "职业培训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷教孩子做木工，这是一种职业培训。", "target_word": "职业培训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农村的孩子常常先在家里接受职业培训。", "target_word": "职业培训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈每天带女儿去店里，让她接受职业培训。", "target_word": "职业培训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小男孩十岁就开始了职业培训。", "target_word": "职业培训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅对徒弟的职业培训很严格。", "target_word": "职业培训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的职业培训是从扫地和洗碗开始的。", "target_word": "职业培训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在老饭馆里跟着大人接受职业培训。", "target_word": "职业培训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶说，家里的职业培训比学校的更有用。", "target_word": "职业培训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过几年职业培训，他成了一名好木匠。", "target_word": "职业培训", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "职业培训班", "label": "复合词"}], "register": "中性", "sense_fingerprint": "大人教孩子学习谋生的工作本领", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a1f4a47-9547-4776-9185-3bf29a88cb1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27276, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "职业培训", "is_correct": true, "explanation": "正确：指从小跟着父亲学本领，符合“学会了修车”的句意。"}, {"text": "检查", "is_correct": false, "explanation": "语义：“接受检查”不是学本领，与“学会了修车”的意思不合。"}, {"text": "治疗", "is_correct": false, "explanation": "语义：“治疗”针对的是疾病，与学修车无关。"}, {"text": "刑罚", "is_correct": false, "explanation": "语域：“刑罚”是法律用语，与家庭里的口吻不协调，也与学修车无关。"}], "explanations": {"职业培训": "正确：指从小跟着父亲学本领，符合“学会了修车”的句意。", "检查": "语义：“接受检查”不是学本领，与“学会了修车”的意思不合。", "治疗": "语义：“治疗”针对的是疾病，与学修车无关。", "刑罚": "语域：“刑罚”是法律用语，与家庭里的口吻不协调，也与学修车无关。"}, "sentence_index": 0, "correct_answer": "职业培训"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个小男孩十岁就当上了职业培训。", "explanation": "这里应该用〈老板〉。“当上”指担任职位，“职业培训”是学本领的过程，不能这样说。"}, {"text": "她接受了一只职业培训。", "explanation": "这里应该用〈段〉。“只”用于动物或成对的东西，学本领的过程要用“段”。"}, {"text": "他的职业培训很高大。", "explanation": "这里应该用〈师傅〉。“高大”形容人的身材或建筑的外形，“职业培训”是学习过程，不能这样形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a5c2b32-6777-4a54-a7ca-acda70d34102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27276, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "职业培训", "is_correct": true, "explanation": "正确：指从小在店里学做事的本领，符合“从扫地和洗碗开始”的句意。"}, {"text": "生日", "is_correct": false, "explanation": "语义：生日是出生的日子，不可能从扫地和洗碗开始。"}, {"text": "学费", "is_correct": false, "explanation": "语义：学费是学校收取的钱，不是从扫地和洗碗开始的。"}, {"text": "门票", "is_correct": false, "explanation": "语义：门票是入场凭证，不能从扫地和洗碗开始。"}], "explanations": {"职业培训": "正确：指从小在店里学做事的本领，符合“从扫地和洗碗开始”的句意。", "生日": "语义：生日是出生的日子，不可能从扫地和洗碗开始。", "学费": "语义：学费是学校收取的钱，不是从扫地和洗碗开始的。", "门票": "语义：门票是入场凭证，不能从扫地和洗碗开始。"}, "sentence_index": 6, "correct_answer": "职业培训"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是一名职业培训。", "explanation": "这里应该用〈学徒〉。“职业培训”是学本领的活动，不能指人。"}, {"text": "他的职业培训很甜。", "explanation": "这里应该用〈糖〉。“甜”形容味道，“职业培训”不是食物，不能这样形容。"}, {"text": "他每月的职业培训很高。", "explanation": "这里应该用〈工钱〉。“高”形容工钱的多少，学习的过程不能说高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a5c2b32-6777-4a54-a7ca-acda70d34102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27276, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他小时候就开始过职业培训。", "corrected_sentence": "他小时候就开始了职业培训。", "error_description": "体貌错误：“开始”表示动作的起点，后面应接动态助词“了”，写作“开始了”。“过”表示曾经有过的经历，不能用在“开始”后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a5c2b32-6777-4a54-a7ca-acda70d34102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27276, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他十二岁就接受了一台职业培训，每天在店里干活。", "corrected_sentence": "他十二岁就接受了一段职业培训，每天在店里干活。", "error_description": "错误：“一台职业培训”，应为“一段职业培训”。“台”用于机器，学本领的过程要用“段”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a5c2b32-6777-4a54-a7ca-acda70d34102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27278, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "更少", "is_correct": true, "explanation": "更少：数量比原来或别处少，与“更多”意义相反。"}, {"text": "快", "is_correct": false, "explanation": "快：形容速度，与“更多”没有反义关系。"}, {"text": "好", "is_correct": false, "explanation": "好：形容品质，与“更多”没有反义关系。"}, {"text": "高", "is_correct": false, "explanation": "高：形容高度，与“更多”没有反义关系。"}], "correct_answer": "更少", "explanations": {"更少": "更少：数量比原来或别处少，与“更多”意义相反。", "快": "快：形容速度，与“更多”没有反义关系。", "好": "好：形容品质，与“更多”没有反义关系。", "高": "高：形容高度，与“更多”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a5c2b32-6777-4a54-a7ca-acda70d34102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27278, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "更少", "is_correct": true, "explanation": "更少：数量比原来或别处少，与“更多”意义相反。"}, {"text": "远", "is_correct": false, "explanation": "远：形容距离，与“更多”没有反义关系。"}, {"text": "贵", "is_correct": false, "explanation": "贵：形容价格，与“更多”没有反义关系。"}, {"text": "新", "is_correct": false, "explanation": "新：形容时间或状态，与“更多”没有反义关系。"}], "correct_answer": "更少", "explanations": {"更少": "更少：数量比原来或别处少，与“更多”意义相反。", "远": "远：形容距离，与“更多”没有反义关系。", "贵": "贵：形容价格，与“更多”没有反义关系。", "新": "新：形容时间或状态，与“更多”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a5c2b32-6777-4a54-a7ca-acda70d34102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27278, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "更多就是比之前还要多。", "primary_collocate": null, "pronunciation": "gèng duō", "ipa": "kɤŋ˥˩ tuɔ˥", "syllable_count": 2, "sentences": [{"text": "这个月的雨比上个月更多。", "target_word": "更多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友来了以后，家里的人更多了。", "target_word": "更多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天买的苹果比昨天更多。", "target_word": "更多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们这次带来了更多的礼物。", "target_word": "更多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学了一年汉语，我认识的字更多了。", "target_word": "更多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气变冷以后，穿厚衣服的人更多了。", "target_word": "更多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你已经吃了很多，还想要更多吗？", "target_word": "更多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年的游客比去年更多。", "target_word": "更多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，明天会有更多的同学来。", "target_word": "更多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的钱已经不少了，可是他还想赚更多。", "target_word": "更多", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "更多的", "label": "定语形式"}], "register": "中性", "sense_fingerprint": "比之前或比较对象还要多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a1f4a47-9547-4776-9185-3bf29a88cb1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27278, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "更多", "is_correct": true, "explanation": "正确：“更多”表示雨量增多，与“比上个月”的比较一致。"}, {"text": "更远", "is_correct": false, "explanation": "语义：“远”形容距离，雨量不能用距离来比较，与语境不符。"}, {"text": "更甜", "is_correct": false, "explanation": "语义：“甜”形容味道，不能用来说雨。"}, {"text": "更亮", "is_correct": false, "explanation": "搭配：“亮”形容光线，不能用来比较雨量。"}], "explanations": {"更多": "正确：“更多”表示雨量增多，与“比上个月”的比较一致。", "更远": "语义：“远”形容距离，雨量不能用距离来比较，与语境不符。", "更甜": "语义：“甜”形容味道，不能用来说雨。", "更亮": "搭配：“亮”形容光线，不能用来比较雨量。"}, "sentence_index": 0, "correct_answer": "更多"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座山比那座更多。", "explanation": "这里应该用〈更高〉。“更多”说的是数量，山的高低要用“更高”。"}, {"text": "这辆车的速度比那辆更多。", "explanation": "这里应该用〈更快〉。“更多”说的是数量，速度的快慢要用“更快”。"}, {"text": "这个孩子的胆子比去年更多。", "explanation": "这里应该用〈更大〉。“更多”说的是数量，胆子的大小要用“更大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a5c2b32-6777-4a54-a7ca-acda70d34102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27278, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "更多", "is_correct": true, "explanation": "正确：“更多”表示数量增加，与“你已经吃了很多，还想要……吗”的语境一致。"}, {"text": "更重", "is_correct": false, "explanation": "语义：“重”指重量，与“还想要”的语境不符。"}, {"text": "更冷", "is_correct": false, "explanation": "语义：“冷”指温度，与“还想要”的语境不符。"}, {"text": "更慢", "is_correct": false, "explanation": "搭配：“慢”形容速度，不能作为“想要”的对象。"}], "explanations": {"更多": "正确：“更多”表示数量增加，与“你已经吃了很多，还想要……吗”的语境一致。", "更重": "语义：“重”指重量，与“还想要”的语境不符。", "更冷": "语义：“冷”指温度，与“还想要”的语境不符。", "更慢": "搭配：“慢”形容速度，不能作为“想要”的对象。"}, "sentence_index": 6, "correct_answer": "更多"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他比我更多地聪明。", "explanation": "这里应该用〈更聪明〉。“更多地”表示数量或次数，不能用来修饰“聪明”这样的性质。"}, {"text": "这个房间的温度比那个更多。", "explanation": "这里应该用〈更高〉。“更多”说的是数量，温度的高低要用“更高”。"}, {"text": "她的年纪比我更多。", "explanation": "这里应该用〈更大〉。“更多”说的是数量，年纪的大小要用“更大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a5c2b32-6777-4a54-a7ca-acda70d34102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27278, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家超市的顾客比去年更多着。", "corrected_sentence": "这家超市的顾客比去年更多了。", "error_description": "体貌错误：“更多”表示已经发生的变化，应用体标“了”，写作“更多了”。“着”表示状态的持续，不能用于这种比较变化。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a5c2b32-6777-4a54-a7ca-acda70d34102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27278, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "教室里的同学比昨天更多的了。", "corrected_sentence": "教室里的同学比昨天更多了。", "error_description": "助词错误：比较结构应写作“比昨天更多了”，“更多”后不能再接结构助词“的”，应去掉“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a5c2b32-6777-4a54-a7ca-acda70d34102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
