INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27286, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国家向人们收的钱，用来修路、建学校。", "primary_collocate": null, "pronunciation": "shuì", "ipa": "ʂweɪ˥˩", "syllable_count": 1, "sentences": [{"text": "大家都要给国家交税。", "target_word": "税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条新路是用大家交的税修的。", "target_word": "税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爸爸每年都要交税。", "target_word": "税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家收税,是为了建学校。", "target_word": "税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "税高了,东西就会变贵。", "target_word": "税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开了一家小店,也要交税。", "target_word": "税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说,税可以用来修路。", "target_word": "税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月我的工资要扣税。", "target_word": "税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为什么我们每个人都要交税?", "target_word": "税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有钱不交税,是不对的。", "target_word": "税", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "税收", "label": "复合"}, {"form": "税款", "label": "复合"}, {"form": "纳税", "label": "复合"}], "register": "中性", "sense_fingerprint": "国家向人们收的钱，用来修路建学校", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938960e5-f255-4470-af12-4986b8304979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27286, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "税", "is_correct": true, "explanation": "税（shuì）：国家向人们收的钱，正是此义。"}, {"text": "水", "is_correct": false, "explanation": "shuǐ（第三声）与 shuì（第四声）声调不同，意思是水。"}, {"text": "岁", "is_correct": false, "explanation": "suì 与 shuì 声母不同（s 与 sh），意思是年龄单位。"}, {"text": "碎", "is_correct": false, "explanation": "suì 与 shuì 声母不同（s 与 sh），意思是破碎。"}], "explanations": {"税": "税（shuì）：国家向人们收的钱，正是此义。", "水": "shuǐ（第三声）与 shuì（第四声）声调不同，意思是水。", "岁": "suì 与 shuì 声母不同（s 与 sh），意思是年龄单位。", "碎": "suì 与 shuì 声母不同（s 与 sh），意思是破碎。"}, "sentence_index": null, "correct_answer": "税"}, "level_3": {"options": [{"text": "税", "is_correct": true, "explanation": "税：国家向人们收的钱，与“大家都要给国家交税”相符。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是交给老师的，不是交给国家的，句子不合理。"}, {"text": "朋友", "is_correct": false, "explanation": "语义：朋友是人，不是要交给国家的东西，“给国家交朋友”不通。"}, {"text": "饭", "is_correct": false, "explanation": "配价：“交”的宾语应是可以交付的东西，“饭”不能被“交”。"}], "explanations": {"税": "税：国家向人们收的钱，与“大家都要给国家交税”相符。", "作业": "语义：作业是交给老师的，不是交给国家的，句子不合理。", "朋友": "语义：朋友是人，不是要交给国家的东西，“给国家交朋友”不通。", "饭": "配价：“交”的宾语应是可以交付的东西，“饭”不能被“交”。"}, "sentence_index": 0, "correct_answer": "税"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老板每个月都给他发税，他很高兴。", "explanation": "这里应该用〈工资〉。老板发给员工的钱是工资，税是国家依法征收的。"}, {"text": "他每个月都给房东交税。", "explanation": "这里应该用〈房租〉。交给房东的钱是房租，税是国家依法征收的。"}, {"text": "弟弟考上大学，爸爸给学校交税。", "explanation": "这里应该用〈学费〉。交给学校的读书费用是学费，税是国家依法征收的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5292da8-fd78-4714-8e8c-11cef0901870') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27286, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "税", "is_correct": true, "explanation": "税（shuì）：国家向人们收的钱，正是此义。"}, {"text": "谁", "is_correct": false, "explanation": "shuí（第二声）与 shuì（第四声）声调不同，意思是谁。"}, {"text": "随", "is_correct": false, "explanation": "suí 与 shuì 声母不同（s 与 sh），声调也不同，意思是跟随。"}, {"text": "瑞", "is_correct": false, "explanation": "ruì 与 shuì 声母不同（r 与 sh），意思是吉祥。"}], "explanations": {"税": "税（shuì）：国家向人们收的钱，正是此义。", "谁": "shuí（第二声）与 shuì（第四声）声调不同，意思是谁。", "随": "suí 与 shuì 声母不同（s 与 sh），声调也不同，意思是跟随。", "瑞": "ruì 与 shuì 声母不同（r 与 sh），意思是吉祥。"}, "sentence_index": null, "correct_answer": "税"}, "level_3": {"options": [{"text": "税", "is_correct": true, "explanation": "税：可以用来修路的钱，与“老师说，税可以用来修路”相符。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本不能用来修路，句子读起来不通。"}, {"text": "棉花糖", "is_correct": false, "explanation": "语义：棉花糖不能用来修路，与句意不符。"}, {"text": "字典", "is_correct": false, "explanation": "语义：字典不能用来修路，与句子的意思不符。"}], "explanations": {"税": "税：可以用来修路的钱，与“老师说，税可以用来修路”相符。", "课本": "语义：课本不能用来修路，句子读起来不通。", "棉花糖": "语义：棉花糖不能用来修路，与句意不符。", "字典": "语义：字典不能用来修路，与句子的意思不符。"}, "sentence_index": 6, "correct_answer": "税"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他闯了红灯，交税是应该的。", "explanation": "这里应该用〈罚款〉。税是依法征收用于公共服务的钱，违章后交的钱是罚款。"}, {"text": "去医院看病要交税，这很正常。", "explanation": "这里应该用〈费用〉。看病要交的钱是费用，税是政府依法征收的。"}, {"text": "他每年都向希望小学交一笔税。", "explanation": "这里应该用〈捐款〉。自愿交给学校的钱是捐款，税是依法征收的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5292da8-fd78-4714-8e8c-11cef0901870') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27286, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我爸爸以前交税过。", "corrected_sentence": "我爸爸以前交过税。", "error_description": "错误在于“过”的位置。“过”应紧跟动词，说“交过税”，不能放在宾语“税”后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5292da8-fd78-4714-8e8c-11cef0901870') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27286, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司的税都交很及时。", "corrected_sentence": "这家公司的税都交得很及时。", "error_description": "错误在于“交很及时”缺少补语标记“得”。正确说法是“交得很及时”，“得”连接动词和补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5292da8-fd78-4714-8e8c-11cef0901870') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
