INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27294, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "接电话、回答别人问题的人。", "primary_collocate": null, "pronunciation": "kè fú", "ipa": "kʰɤ˥˩ fu˧˥", "syllable_count": 2, "sentences": [{"text": "我给客服打了电话，问快递在哪儿。", "target_word": "客服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客服接了电话，说马上帮我查。", "target_word": "客服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话那头的客服声音很好听。", "target_word": "客服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客服问我：“您有什么问题？”", "target_word": "客服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客服一天要接上百个电话。", "target_word": "客服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不会用这台机器，就问了客服。", "target_word": "客服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客服说我的问题他解决不了。", "target_word": "客服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的工作是做客服，每天回答问题。", "target_word": "客服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客服很忙，我等了十分钟才有人接。", "target_word": "客服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把订单号告诉客服。", "target_word": "客服", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "人工客服", "label": "复合"}, {"form": "在线客服", "label": "复合"}], "register": "中性", "sense_fingerprint": "接电话、答疑的那个人，日常说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a1f4a47-9547-4776-9185-3bf29a88cb1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27294, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "客服", "is_correct": true, "explanation": "这里指接电话、回答问题的人，与“打了电话，问快递”的语境吻合。"}, {"text": "理发师", "is_correct": false, "explanation": "语义：理发师不负责解答快递问题，句中要找的是答疑的人。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师与“问快递在哪儿”无关，不是打电话答疑的对象。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“打电话”的对象应是人或机构，“窗户”不能接电话。"}], "explanations": {"客服": "这里指接电话、回答问题的人，与“打了电话，问快递”的语境吻合。", "理发师": "语义：理发师不负责解答快递问题，句中要找的是答疑的人。", "厨师": "语义：厨师与“问快递在哪儿”无关，不是打电话答疑的对象。", "窗户": "搭配：“打电话”的对象应是人或机构，“窗户”不能接电话。"}, "sentence_index": 0, "correct_answer": "客服"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "客服每天骑车送外卖。", "explanation": "这里应该用〈外卖员〉。客服负责接电话、回答问题，送餐的应说外卖员。"}, {"text": "客服把菜端上了桌。", "explanation": "这里应该用〈服务员〉。客服负责解答问题，端菜上桌的是服务员。"}, {"text": "客服会做很多菜。", "explanation": "这里应该用〈厨师〉。客服不做菜，会做很多菜的是厨师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a5c2b32-6777-4a54-a7ca-acda70d34102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27294, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "客服", "is_correct": true, "explanation": "这里指解答问题的人，能够说“解决不了”，与句意吻合。"}, {"text": "树", "is_correct": false, "explanation": "语义：树不会说话，不能说“我的问题他解决不了”。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视不能对具体问题作出判断，与句意不符。"}, {"text": "花瓶", "is_correct": false, "explanation": "配价：“说”要求有言语能力的主语，“花瓶”不能充当。"}], "explanations": {"客服": "这里指解答问题的人，能够说“解决不了”，与句意吻合。", "树": "语义：树不会说话，不能说“我的问题他解决不了”。", "电视": "语义：电视不能对具体问题作出判断，与句意不符。", "花瓶": "配价：“说”要求有言语能力的主语，“花瓶”不能充当。"}, "sentence_index": 6, "correct_answer": "客服"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "客服每天都在响，吵得人睡不着。", "explanation": "此处把“客服”当成了〈电话〉来用。接电话的是人，电话才会响，应说“电话每天都在响”。"}, {"text": "客服今天给我修了一下午的车。", "explanation": "此处把“客服”当成了〈修理工〉来用。客服负责接电话、回答问题，修车的是修理工。"}, {"text": "客服在田里种菜。", "explanation": "此处把“客服”当成了〈农民〉来用。客服是接电话的人，种菜的是农民。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a5c2b32-6777-4a54-a7ca-acda70d34102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27294, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我打电话问了一台客服。", "corrected_sentence": "我打电话问了一位客服。", "error_description": "量词错误：“客服”指人，应用“位”或“名”计量，“台”用于机器，不能计量人。正确说法是“一位客服”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a5c2b32-6777-4a54-a7ca-acda70d34102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27294, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我刚刚跟一只客服聊了半个小时。", "corrected_sentence": "我刚刚跟一位客服聊了半个小时。", "error_description": "量词错误：“只”用于动物或成对的东西，“客服”指人，应用“位”计量。正确说法是“一位客服”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a5c2b32-6777-4a54-a7ca-acda70d34102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
