INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27296, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "工人是上班做事情、拿工资的人。", "primary_collocate": null, "pronunciation": "gōng rén", "ipa": "kʊŋ˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "我家旁边有一家工厂,里面有很多工人。", "target_word": "工人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人每天都要去工厂上班。", "target_word": "工人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人做完事情,就回家了。", "target_word": "工人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我叔叔是一名工人。", "target_word": "工人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人每个月都拿工资。", "target_word": "工人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些工人正在盖新房子。", "target_word": "工人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板请了五个工人来帮忙。", "target_word": "工人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们中午在一起吃饭。", "target_word": "工人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他以前是工人,现在当老师。", "target_word": "工人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人修好了我家的水管。", "target_word": "工人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "工人们", "label": "复数"}], "register": "中性", "sense_fingerprint": "上班做事情拿工资的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938960e5-f255-4470-af12-4986b8304979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27296, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "工人", "is_correct": true, "explanation": "正确。指上班做事、拿工资的人。"}, {"text": "公认", "is_correct": false, "explanation": "rèn（第四声）与 rén（第二声）声调不同，意思是大家都承认，与“工人”不同。"}, {"text": "公然", "is_correct": false, "explanation": "rán 与 rén 的韵母不同（a 与 e），意思是公开地、毫不掩饰地。"}, {"text": "公文", "is_correct": false, "explanation": "wén 与 rén 的声母不同（w 与 r），意思是公文、正式文件。"}], "explanations": {"工人": "正确。指上班做事、拿工资的人。", "公认": "rèn（第四声）与 rén（第二声）声调不同，意思是大家都承认，与“工人”不同。", "公然": "rán 与 rén 的韵母不同（a 与 e），意思是公开地、毫不掩饰地。", "公文": "wén 与 rén 的声母不同（w 与 r），意思是公文、正式文件。"}, "sentence_index": null, "correct_answer": "工人"}, "level_3": {"options": [{"text": "病人", "is_correct": false, "explanation": "语义：工厂里不会有很多病人，这里说的是在工厂上班的人。"}, {"text": "工人", "is_correct": true, "explanation": "正确。工厂里很多人在这里上班做事，只有“工人”符合。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：工厂不是交通工具，里面不会有很多乘客。"}, {"text": "哥们儿", "is_correct": false, "explanation": "语域：“哥们儿”是口语、随便的说法，与这段平实的描述不相称。"}], "explanations": {"病人": "语义：工厂里不会有很多病人，这里说的是在工厂上班的人。", "工人": "正确。工厂里很多人在这里上班做事，只有“工人”符合。", "乘客": "语义：工厂不是交通工具，里面不会有很多乘客。", "哥们儿": "语域：“哥们儿”是口语、随便的说法，与这段平实的描述不相称。"}, "sentence_index": 0, "correct_answer": "工人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我侄子是一名工人，每天早上去学校上课。", "explanation": "这里应该用〈学生〉。去学校上课的是学生，不上班、不拿工资，“工人”指上班做事、拿工资的人。"}, {"text": "我叔叔是一名工人，每天不去厂里上班，只在自家的菜地里种菜。", "explanation": "这里应该用〈农民〉。不去上班、只在自家菜地里种菜的是农民，“工人”指上班做事、拿工资的人。"}, {"text": "我表姐是一名工人，可是她从来不去上班，只在社区里义务帮忙。", "explanation": "这里应该用〈志愿者〉。不上班、只义务帮忙的是志愿者，“工人”指上班做事、拿工资的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5292da8-fd78-4714-8e8c-11cef0901870') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27296, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头不能被请来帮忙，这句话请的是人。"}, {"text": "工人", "is_correct": true, "explanation": "正确。老板请来帮忙的是人，只有“工人”符合。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不能被请来帮忙，与“请了五个”的对象不符。"}, {"text": "老朽", "is_correct": false, "explanation": "语域：“老朽”是书面而带贬义的说法，与这句平实的叙述不相称。"}], "explanations": {"石头": "语义：石头不能被请来帮忙，这句话请的是人。", "工人": "正确。老板请来帮忙的是人，只有“工人”符合。", "窗户": "语义：窗户不能被请来帮忙，与“请了五个”的对象不符。", "老朽": "语域：“老朽”是书面而带贬义的说法，与这句平实的叙述不相称。"}, "sentence_index": 6, "correct_answer": "工人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我舅舅是一名工人，可是他不去上班，每天在街上摆摊卖水果。", "explanation": "这里应该用〈小贩〉。不去上班、自己摆摊做生意的是小贩，“工人”指上班做事、拿工资的人。"}, {"text": "我舅舅是一名工人，他是这家公司的老板。", "explanation": "这里应该用〈老板〉。公司的老板是经营者，不替别人上班、拿工资，“工人”指上班做事、拿工资的人。"}, {"text": "我姐姐是一名工人，每天在家做饭、带孩子，没有工资。", "explanation": "这里应该用〈家庭主妇〉。在家做家务、没有工资的不是工人，“工人”指上班做事、拿工资的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5292da8-fd78-4714-8e8c-11cef0901870') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27296, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我叔叔是厂里的一头工人。", "corrected_sentence": "我叔叔是厂里的一名工人。", "error_description": "量词错误：“工人”前应用“名”或“位”。“头”用于牲畜，不能用来数人，正确说法是“一名工人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5292da8-fd78-4714-8e8c-11cef0901870') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27296, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我嫂子当过一只工人。", "corrected_sentence": "我嫂子当过一名工人。", "error_description": "量词错误：“工人”指人，前面应用“名”或“个”，“只”用于动物等，不能用来数人。正确说法是“当过一名工人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5292da8-fd78-4714-8e8c-11cef0901870') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
