INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27298, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做一件事时，会遇到的不容易的地方。", "primary_collocate": null, "pronunciation": "kùn nan", "ipa": "kʰwən˥˩ nan", "syllable_count": 2, "sentences": [{"text": "学外语最大的困难是发音。", "target_word": "困难", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你觉得做这件事有什么困难？", "target_word": "困难", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "搬运这么大的桌子，困难在于门太窄了。", "target_word": "困难", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "写论文时，他碰到了不少困难。", "target_word": "困难", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开车去山里，路上的困难比我想的多。", "target_word": "困难", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你有什么困难，请先告诉我。", "target_word": "困难", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "刚开始做生意时，最大的困难是没有钱。", "target_word": "困难", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把每个困难都写在本子上，一个一个解决。", "target_word": "困难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种花看起来简单，其实也有很多困难。", "target_word": "困难", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次爬山没有想象中那么多困难。", "target_word": "困难", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词（一个困难）"}, {"form": "困难户", "label": "复合"}, {"form": "困難", "label": "繁体"}], "register": "中性", "sense_fingerprint": "困难：做事时遇到的不容易之处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f3cf8ff-25c5-4d6f-b0ac-df147fb79767') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27298, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "爱好", "is_correct": false, "explanation": "语义：「爱好」指喜欢做的事，与句中指学习障碍的意思不同，句意不通。"}, {"text": "困难", "is_correct": true, "explanation": "正确。「最大的困难」指学外语时遇到的最难的地方，与「是发音」呼应。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：「颜色」指具体的色彩，不能用在「学外语最大的……」这样的抽象说法里。"}, {"text": "动力", "is_correct": false, "explanation": "语义：「动力」指推动前进的力量，与句中要说的阻碍相反。"}], "explanations": {"爱好": "语义：「爱好」指喜欢做的事，与句中指学习障碍的意思不同，句意不通。", "困难": "正确。「最大的困难」指学外语时遇到的最难的地方，与「是发音」呼应。", "颜色": "搭配：「颜色」指具体的色彩，不能用在「学外语最大的……」这样的抽象说法里。", "动力": "语义：「动力」指推动前进的力量，与句中要说的阻碍相反。"}, "sentence_index": 0, "correct_answer": "困难"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "写论文时，他捡到了不少困难。", "explanation": "这里应该用〈机会〉。「捡到机会」是常见说法；「困难」指遇到的阻碍，不能捡拾。"}, {"text": "这台复印机有困难，总是卡纸。", "explanation": "这里应该用〈故障〉。「困难」指人做事时遇到的阻碍，机器出问题应说「有故障」，不能说机器有困难。"}, {"text": "写论文时，他碰到了一根困难。", "explanation": "这里应该用〈个〉。「根」用于细长的东西，不用于困难。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a272a790-830f-4bd5-a3e2-ce1c82265682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27298, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "利润", "is_correct": false, "explanation": "语义：「利润」指赚到的钱，与「没有钱」相矛盾。"}, {"text": "困难", "is_correct": true, "explanation": "正确。「最大的困难」指做生意初期遇到的阻碍，与「是没有钱」呼应。"}, {"text": "朋友", "is_correct": false, "explanation": "搭配：「朋友」指人，不能用来说明「最大的……是没有钱」这种情况。"}, {"text": "收入", "is_correct": false, "explanation": "语义：「收入」指赚得的钱，与「没有钱」相矛盾。"}], "explanations": {"利润": "语义：「利润」指赚到的钱，与「没有钱」相矛盾。", "困难": "正确。「最大的困难」指做生意初期遇到的阻碍，与「是没有钱」呼应。", "朋友": "搭配：「朋友」指人，不能用来说明「最大的……是没有钱」这种情况。", "收入": "语义：「收入」指赚得的钱，与「没有钱」相矛盾。"}, "sentence_index": 6, "correct_answer": "困难"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次爬山他犯了不少困难。", "explanation": "这里应该用〈错误〉。「犯错误」是固定搭配，「犯困难」不通。"}, {"text": "这次爬山我遇到了一只困难。", "explanation": "这里应该用〈个〉。「只」用于动物或成对器官之一，不用于困难。"}, {"text": "这次爬山我吃了很多困难。", "explanation": "这里应该用〈苦头〉。「吃苦头」是固定说法，「吃困难」不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a272a790-830f-4bd5-a3e2-ce1c82265682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27298, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他碰到了一颗困难，但很快就解决了。", "corrected_sentence": "他碰到了一个困难，但很快就解决了。", "error_description": "量词错误：「困难」应搭配「个」，「颗」用于颗粒状的小东西，不能用于困难。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a272a790-830f-4bd5-a3e2-ce1c82265682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27298, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是他遇到了的最大困难。", "corrected_sentence": "这是他遇到的最大困难。", "error_description": "助词多余：「遇到的最大困难」中的定语不需要「了」，「遇到了的」是不规范的说法，应去掉「了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a272a790-830f-4bd5-a3e2-ce1c82265682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27300, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "坏事", "is_correct": true, "explanation": "反义：「坏事」与「好事」相对，指不好的、有害的事情，词典有此反义关系。"}, {"text": "烦恼", "is_correct": false, "explanation": "「烦恼」指心里的忧虑，与「好事」没有反义关系。"}, {"text": "道理", "is_correct": false, "explanation": "「道理」指事物的规律或理由，与「好事」没有反义关系。"}, {"text": "天气", "is_correct": false, "explanation": "「天气」是自然现象，与「好事」不构成反义关系。"}], "correct_answer": "坏事", "explanations": {"坏事": "反义：「坏事」与「好事」相对，指不好的、有害的事情，词典有此反义关系。", "烦恼": "「烦恼」指心里的忧虑，与「好事」没有反义关系。", "道理": "「道理」指事物的规律或理由，与「好事」没有反义关系。", "天气": "「天气」是自然现象，与「好事」不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
