INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27300, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "好事是让人开心的事情。", "primary_collocate": null, "pronunciation": "hǎo shì", "ipa": "xɑʊ̯˨˩˦ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "今天我遇到一件好事，朋友请我吃饭庆祝。", "target_word": "好事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他考上了大学，这是我们家的好事。", "target_word": "好事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶身体好了，这真是一件好事。", "target_word": "好事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有什么好事？看你笑得这么开心。", "target_word": "好事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说你要结婚了，真是好事啊！", "target_word": "好事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天天气好，朋友又来看我，都是好事。", "target_word": "好事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好事一件接一件，大家都替他高兴，他笑得很开心。", "target_word": "好事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们得到了新书，这对他们是好事。", "target_word": "好事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王最近好事不断，工作也找到了。", "target_word": "好事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明得了第一名，大家都说这是好事。", "target_word": "好事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一件好事", "label": "量词"}, {"form": "好事多磨", "label": "复合"}], "register": "中性", "sense_fingerprint": "好事：让人开心的喜事、顺心的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9da955b2-9cb2-4719-95b9-57d75913c78c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27300, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "好事", "is_correct": true, "explanation": "正确：好事，指让人开心的事情。"}, {"text": "好戏", "is_correct": false, "explanation": "声母不同：「好戏」的第二音节是 xì，「好事」是 shì，意思是精彩的演出。"}, {"text": "海事", "is_correct": false, "explanation": "韵母不同：「海事」的第一音节韵母是 ai，「好事」是 ao，意思是海上的事务。"}, {"text": "考试", "is_correct": false, "explanation": "声母不同：「考试」以 k 开头，「好事」以 h 开头，意思是测验。"}, {"text": "好使", "is_correct": false, "explanation": "声调不同：「好使」的第二音节是第三声，「好事」是第四声，意思是好用、管用。"}], "explanations": {"好事": "正确：好事，指让人开心的事情。", "好戏": "声母不同：「好戏」的第二音节是 xì，「好事」是 shì，意思是精彩的演出。", "海事": "韵母不同：「海事」的第一音节韵母是 ai，「好事」是 ao，意思是海上的事务。", "考试": "声母不同：「考试」以 k 开头，「好事」以 h 开头，意思是测验。", "好使": "声调不同：「好使」的第二音节是第三声，「好事」是第四声，意思是好用、管用。"}, "sentence_index": null, "correct_answer": "好事"}, "level_3": {"options": [{"text": "好事", "is_correct": true, "explanation": "正确：「朋友请我吃饭」是高兴的事，只有「好事」与之相合。"}, {"text": "坏事", "is_correct": false, "explanation": "语义：「朋友请我吃饭」是愉快的事，「坏事」与之矛盾。"}, {"text": "祸事", "is_correct": false, "explanation": "语义：「祸事」指灾祸，与「朋友请我吃饭」的喜悦语境矛盾。"}, {"text": "噩耗", "is_correct": false, "explanation": "语域：「噩耗」是书面语，指坏消息，且与「朋友请我吃饭」的轻松语境矛盾。"}], "explanations": {"好事": "正确：「朋友请我吃饭」是高兴的事，只有「好事」与之相合。", "坏事": "语义：「朋友请我吃饭」是愉快的事，「坏事」与之矛盾。", "祸事": "语义：「祸事」指灾祸，与「朋友请我吃饭」的喜悦语境矛盾。", "噩耗": "语域：「噩耗」是书面语，指坏消息，且与「朋友请我吃饭」的轻松语境矛盾。"}, "sentence_index": 0, "correct_answer": "好事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们的研究取得了好事，大家都很高兴。", "explanation": "这里应该用〈成果〉。「取得」后面接研究、工作的结果，要说「取得成果」；「好事」指发生的事情，不能说「取得好事」。"}, {"text": "比赛后，他领到了一件好事。", "explanation": "这里应该用〈奖品〉。领到的是具体的奖品，要说「领到奖品」，「好事」不能用来指奖品。"}, {"text": "他总爱打听邻居的私事，真是个好事的人。", "explanation": "这里的「好事」读 hào，是爱管闲事的意思，指好打听、好过问别人事情的人，与指让人开心的事情不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27300, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "好事", "is_correct": true, "explanation": "正确：好事，指让人开心的事情。"}, {"text": "好诗", "is_correct": false, "explanation": "声调不同：「好诗」的第二音节是第一声 shī，「好事」是第四声 shì，意思是好的诗作。"}, {"text": "早市", "is_correct": false, "explanation": "声母不同：「早市」以 z 开头，意思是早上的集市。"}, {"text": "搞事", "is_correct": false, "explanation": "声母不同：「搞事」以 g 开头，意思是找麻烦、闹事。"}, {"text": "好似", "is_correct": false, "explanation": "声母不同：「好似」的第二音节是 sì，「好事」是 shì，意思是好像。"}], "explanations": {"好事": "正确：好事，指让人开心的事情。", "好诗": "声调不同：「好诗」的第二音节是第一声 shī，「好事」是第四声 shì，意思是好的诗作。", "早市": "声母不同：「早市」以 z 开头，意思是早上的集市。", "搞事": "声母不同：「搞事」以 g 开头，意思是找麻烦、闹事。", "好似": "声母不同：「好似」的第二音节是 sì，「好事」是 shì，意思是好像。"}, "sentence_index": null, "correct_answer": "好事"}, "level_3": {"options": [{"text": "好事", "is_correct": true, "explanation": "正确：「一件接一件」后面「他笑得很开心」，只有「好事」与之相合。"}, {"text": "苦事", "is_correct": false, "explanation": "语义：「苦事」指令人难受的事，与「他笑得很开心」矛盾。"}, {"text": "烦心事", "is_correct": false, "explanation": "语义：「烦心事」令人烦恼，与「他笑得很开心」矛盾。"}, {"text": "病痛", "is_correct": false, "explanation": "搭配：「病痛」一般说「一阵」「一种」，不说「一件接一件」，且与「他笑得很开心」矛盾。"}], "explanations": {"好事": "正确：「一件接一件」后面「他笑得很开心」，只有「好事」与之相合。", "苦事": "语义：「苦事」指令人难受的事，与「他笑得很开心」矛盾。", "烦心事": "语义：「烦心事」令人烦恼，与「他笑得很开心」矛盾。", "病痛": "搭配：「病痛」一般说「一阵」「一种」，不说「一件接一件」，且与「他笑得很开心」矛盾。"}, "sentence_index": 6, "correct_answer": "好事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这个月的好事很高，老板很满意。", "explanation": "这里应该用〈收入〉。说钱收入多要用「收入」，「好事」是事情，不能说「好事很高」。"}, {"text": "朋友送了我好事，我很感动。", "explanation": "这里应该用〈礼物〉。「送」后面接具体的东西，要说「送了我礼物」；「好事」指让人开心的事情，不能说「送好事」。"}, {"text": "他这人很好事，总爱打听别人家的私事。", "explanation": "这里的「好事」读 hào，是爱管闲事的意思，指好打听、好过问别人事情，与指让人开心的事情不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27300, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个月我家有一只好事，大家都很高兴。", "corrected_sentence": "这个月我家有一件好事，大家都很高兴。", "error_description": "量词错误：「好事」的量词应为「件」，不能用「只」。「只」多用于动物或单个的小东西，不用于事情。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27300, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班得了一只好事，老师很高兴。", "corrected_sentence": "我们班得了一件好事，老师很高兴。", "error_description": "量词错误：「好事」的量词应为「件」，不能用「只」。应说「得了一件好事」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27302, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "受损", "is_correct": true, "explanation": "受损：与“受益”相反，指遭受损失"}, {"text": "跳舞", "is_correct": false, "explanation": "跳舞：与“受益”没有反义关系"}, {"text": "思考", "is_correct": false, "explanation": "思考：与“受益”没有反义关系"}, {"text": "上班", "is_correct": false, "explanation": "上班：与“受益”没有反义关系"}], "correct_answer": "受损", "explanations": {"受损": "受损：与“受益”相反，指遭受损失", "跳舞": "跳舞：与“受益”没有反义关系", "思考": "思考：与“受益”没有反义关系", "上班": "上班：与“受益”没有反义关系"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c60899f1-e56a-4535-96d2-aa943636429c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27302, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "受害", "is_correct": true, "explanation": "受害：与“受益”相反，指遭受损害"}, {"text": "游泳", "is_correct": false, "explanation": "游泳：与“受益”没有反义关系"}, {"text": "观察", "is_correct": false, "explanation": "观察：与“受益”没有反义关系"}, {"text": "报名", "is_correct": false, "explanation": "报名：与“受益”没有反义关系"}], "correct_answer": "受害", "explanations": {"受害": "受害：与“受益”相反，指遭受损害", "游泳": "游泳：与“受益”没有反义关系", "观察": "观察：与“受益”没有反义关系", "报名": "报名：与“受益”没有反义关系"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c60899f1-e56a-4535-96d2-aa943636429c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27302, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "得到好处。", "primary_collocate": null, "pronunciation": "shòu yì", "ipa": "ʂoʊ⁵¹ i⁵¹", "syllable_count": 2, "sentences": [{"text": "好好学习，你会受益一生。", "target_word": "受益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个人都能从这个计划中受益。", "target_word": "受益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次培训让大家都受益了。", "target_word": "受益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "住在公园旁边的人最受益。", "target_word": "受益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从父母的教育中受益很多。", "target_word": "受益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家一起工作，公司和客人都受益。", "target_word": "受益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新的医保政策让老人受益。", "target_word": "受益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多听别人的意见，你会受益。", "target_word": "受益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书让我受益不少。", "target_word": "受益", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们从这门课受益。", "target_word": "受益", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "受益人", "label": "复合"}, {"form": "受益者", "label": "复合"}, {"form": "受益了", "label": "体标"}], "register": "中性", "sense_fingerprint": "得到好处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ade6ce41-a0e9-49cf-8af0-3740ac5cd6f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27302, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "受益", "is_correct": true, "explanation": "受益（shòu yì）：得到好处，与听到的读音一致"}, {"text": "收益", "is_correct": false, "explanation": "shōu（第一声）与 shòu（第四声）声调不同，收益指所得的利润或收入"}, {"text": "手艺", "is_correct": false, "explanation": "shǒu（第三声）与 shòu（第四声）声调不同，手艺指手工技能"}, {"text": "寿衣", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，寿衣指为去世者准备的衣服"}, {"text": "兽医", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，兽医指给动物看病的人"}], "explanations": {"受益": "受益（shòu yì）：得到好处，与听到的读音一致", "收益": "shōu（第一声）与 shòu（第四声）声调不同，收益指所得的利润或收入", "手艺": "shǒu（第三声）与 shòu（第四声）声调不同，手艺指手工技能", "寿衣": "yī（第一声）与 yì（第四声）声调不同，寿衣指为去世者准备的衣服", "兽医": "yī（第一声）与 yì（第四声）声调不同，兽医指给动物看病的人"}, "sentence_index": null, "correct_answer": "受益"}, "level_3": {"options": [{"text": "受益", "is_correct": true, "explanation": "受益：得到好处，符合“好好学习”的积极结果"}, {"text": "受伤", "is_correct": false, "explanation": "语义：“受伤”是坏结果，与“好好学习”的好处相反"}, {"text": "受罪", "is_correct": false, "explanation": "语域：“受罪”口语色彩重，且与“好好学习”的积极结果相反"}, {"text": "吃亏", "is_correct": false, "explanation": "语义：“吃亏”指遭受损失，与“受益一生”的意思相反"}], "explanations": {"受益": "受益：得到好处，符合“好好学习”的积极结果", "受伤": "语义：“受伤”是坏结果，与“好好学习”的好处相反", "受罪": "语域：“受罪”口语色彩重，且与“好好学习”的积极结果相反", "吃亏": "语义：“吃亏”指遭受损失，与“受益一生”的意思相反"}, "sentence_index": 0, "correct_answer": "受益"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在工作中受益了很多经验。", "explanation": "这里应该用〈获得〉。受益是不及物动词，后面不能直接带“经验”作宾语；获得可以带宾语"}, {"text": "这个计划受益了很多人。", "explanation": "这里应该用〈帮助〉。受益是不及物动词，不能直接带“很多人”作宾语；帮助可以。"}, {"text": "他因为总是抽烟，肺部受益了很多。", "explanation": "这里应该用〈受损〉。受益表示得到好处，抽烟带来的是伤害，应说“受损”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c60899f1-e56a-4535-96d2-aa943636429c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27302, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "受益", "is_correct": true, "explanation": "受益：得到好处，符合“新的医保政策”的作用"}, {"text": "变丑", "is_correct": false, "explanation": "体貌：“变丑”说的是外貌，与政策带来的实际好处不合"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”是坏结果，与医保政策的作用相反"}, {"text": "挨饿", "is_correct": false, "explanation": "语义：“挨饿”指遭受困苦，与政策的积极作用相反"}], "explanations": {"受益": "受益：得到好处，符合“新的医保政策”的作用", "变丑": "体貌：“变丑”说的是外貌，与政策带来的实际好处不合", "生病": "语义：“生病”是坏结果，与医保政策的作用相反", "挨饿": "语义：“挨饿”指遭受困苦，与政策的积极作用相反"}, "sentence_index": 6, "correct_answer": "受益"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "早睡受益健康。", "explanation": "这里应该用〈有益于〉。受益是不及物动词，不能直接带“健康”作宾语；“有益于”可以。"}, {"text": "这场比赛让我们队受益惨重。", "explanation": "这里应该用〈损失〉。“惨重”说明是损失，而受益表示得到好处，与句意相反"}, {"text": "周末我们在山上受益了清新的空气。", "explanation": "这里应该用〈享受〉。受益是不及物动词，不能直接带“空气”作宾语；享受可以带宾语"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c60899f1-e56a-4535-96d2-aa943636429c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27302, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我从这次旅行中被受益很多。", "corrected_sentence": "我从这次旅行中受益很多。", "error_description": "错误：加了“被”。“受益”是不及物动词，不能用于被动结构，应说“我从这次旅行中受益很多”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c60899f1-e56a-4535-96d2-aa943636429c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27302, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同学们从这门课被受益了不少。", "corrected_sentence": "同学们从这门课受益了不少。", "error_description": "错误：多加了“被”。“受益”是不及物动词，不能用于被动结构，应删去“被”，说“同学们从这门课受益了不少”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c60899f1-e56a-4535-96d2-aa943636429c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
