INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27304, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "想事情。", "primary_collocate": null, "pronunciation": "sī kǎo", "ipa": "sɹ̩˥ kʰɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "安静的晚上，我喜欢一个人思考。", "target_word": "思考", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这道题很难，我需要思考一下。", "target_word": "思考", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不说话，好像在思考什么。", "target_word": "思考", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "先思考，再回答。", "target_word": "思考", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师让我们安静地思考五分钟。", "target_word": "思考", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她看着窗外，一直在思考。", "target_word": "思考", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不要急，慢慢思考。", "target_word": "思考", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "睡觉前，他常常思考一天的事。", "target_word": "思考", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个问题值得我们认真思考。", "target_word": "思考", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明低着头，认真地思考怎么回答。", "target_word": "思考", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "思考了", "label": "体标"}, {"form": "思考着", "label": "体标"}, {"form": "思考过", "label": "体标"}, {"form": "思考思考", "label": "重叠"}], "register": "中性", "sense_fingerprint": "动脑子想事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f3cf8ff-25c5-4d6f-b0ac-df147fb79767') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27304, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "思考", "is_correct": true, "explanation": "正确：“一个人思考”符合“安静的晚上”的语境，句意通顺。"}, {"text": "大喊", "is_correct": false, "explanation": "语义：“大喊”声音很大，与句中“安静的晚上”的语境矛盾。"}, {"text": "吵架", "is_correct": false, "explanation": "配价：“吵架”需要对象，不能只说“一个人吵架”。"}, {"text": "喧哗", "is_correct": false, "explanation": "语义：“喧哗”指吵闹，与“安静的晚上”正好相反。"}], "explanations": {"思考": "正确：“一个人思考”符合“安静的晚上”的语境，句意通顺。", "大喊": "语义：“大喊”声音很大，与句中“安静的晚上”的语境矛盾。", "吵架": "配价：“吵架”需要对象，不能只说“一个人吵架”。", "喧哗": "语义：“喧哗”指吵闹，与“安静的晚上”正好相反。"}, "sentence_index": 0, "correct_answer": "思考"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我思考吃饭。", "explanation": "这里应该用〈想〉。思考表示动脑子想事情，不能表示想要做某事。"}, {"text": "我思考了一觉。", "explanation": "这里应该用〈睡〉。思考是动脑子想事情，不能表示睡觉这个动作。"}, {"text": "他先思考手，然后回家。", "explanation": "这里应该用〈洗〉。思考是动脑子想事情，不能表示洗手这个动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a272a790-830f-4bd5-a3e2-ce1c82265682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27304, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "思考", "is_correct": true, "explanation": "正确：“你不要急，慢慢思考”是常见的劝说语，句意通顺。"}, {"text": "冲刺", "is_correct": false, "explanation": "语义：“冲刺”指快速向前，与句中“慢慢”矛盾。"}, {"text": "抢夺", "is_correct": false, "explanation": "配价：“抢夺”需要受事宾语，句中没有可以承受动作的对象。"}, {"text": "逃跑", "is_correct": false, "explanation": "语义：“逃跑”与“你不要急”的劝说语境不符。"}], "explanations": {"思考": "正确：“你不要急，慢慢思考”是常见的劝说语，句意通顺。", "冲刺": "语义：“冲刺”指快速向前，与句中“慢慢”矛盾。", "抢夺": "配价：“抢夺”需要受事宾语，句中没有可以承受动作的对象。", "逃跑": "语义：“逃跑”与“你不要急”的劝说语境不符。"}, "sentence_index": 6, "correct_answer": "思考"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈去超市思考了一斤苹果。", "explanation": "这里应该用〈买〉。思考是动脑子想事情，不能表示购买东西的动作。"}, {"text": "他每天思考书到深夜。", "explanation": "这里应该用〈看〉。思考不能表示用眼睛阅读。"}, {"text": "他饿了，去思考饭。", "explanation": "这里应该用〈吃〉。思考不能表示吃饭的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a272a790-830f-4bd5-a3e2-ce1c82265682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27304, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这道题很难，我得先思考了一下。", "corrected_sentence": "这道题很难，我得先思考一下。", "error_description": "错误形式：“得……思考了一下”。正确形式：“得……思考一下”。“得”表示需要，后面的动词不能带“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a272a790-830f-4bd5-a3e2-ce1c82265682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27304, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你要仔细得思考这个问题。", "corrected_sentence": "你要仔细思考这个问题。", "error_description": "错误形式：“仔细得思考”。正确形式：“仔细思考”或“仔细地思考”。“得”是补语标记，不能用在动词前作状语；修饰动词的状语要用“地”，或直接省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a272a790-830f-4bd5-a3e2-ce1c82265682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27310, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "马虎", "is_correct": true, "explanation": "反义：“认真”与“马虎”相对，“认真对待”的反面是做事不认真、不在意。"}, {"text": "研究", "is_correct": false, "explanation": "“研究”指探究事物，与“认真对待”没有反义关系。"}, {"text": "参加", "is_correct": false, "explanation": "“参加”指加入某项活动，与“认真对待”没有反义关系。"}, {"text": "完成", "is_correct": false, "explanation": "“完成”指做完某件事，与“认真对待”没有反义关系。"}], "correct_answer": "马虎", "explanations": {"马虎": "反义：“认真”与“马虎”相对，“认真对待”的反面是做事不认真、不在意。", "研究": "“研究”指探究事物，与“认真对待”没有反义关系。", "参加": "“参加”指加入某项活动，与“认真对待”没有反义关系。", "完成": "“完成”指做完某件事，与“认真对待”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0637b4-a516-4149-95c7-5f1973d11154') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27310, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "马虎", "is_correct": true, "explanation": "反义：“认真”与“马虎”相对，“认真对待”的反面是做事不在意。"}, {"text": "清洗", "is_correct": false, "explanation": "“清洗”指用水去除污垢，与“认真对待”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”指悠闲地走路，与“认真对待”没有反义关系。"}, {"text": "观察", "is_correct": false, "explanation": "“观察”指仔细看，与“认真对待”没有反义关系。"}], "correct_answer": "马虎", "explanations": {"马虎": "反义：“认真”与“马虎”相对，“认真对待”的反面是做事不在意。", "清洗": "“清洗”指用水去除污垢，与“认真对待”没有反义关系。", "散步": "“散步”指悠闲地走路，与“认真对待”没有反义关系。", "观察": "“观察”指仔细看，与“认真对待”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0637b4-a516-4149-95c7-5f1973d11154') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27310, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "要认真地做事情，不马虎。", "primary_collocate": null, "pronunciation": "rèn zhēn duì dài", "ipa": "ɻən˥˩ ʈʂən˥ tweɪ˥˩ taɪ˥˩", "syllable_count": 4, "sentences": [{"text": "做作业时要认真对待，不能马虎。", "target_word": "认真对待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，写字要认真对待。", "target_word": "认真对待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不管事情大小，我们都要认真对待。", "target_word": "认真对待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他做事不马虎，对每件小事都认真对待。", "target_word": "认真对待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要认真对待这次比赛，别太随便。", "target_word": "认真对待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈让我认真对待学习，不要玩手机。", "target_word": "认真对待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我会认真对待你交给我的任务。", "target_word": "认真对待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不认真对待，工作容易出错。", "target_word": "认真对待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们认真对待值日，教室很干净。", "target_word": "认真对待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她对什么事都认真对待，从不马虎。", "target_word": "认真对待", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "认真对待了", "label": "体标"}, {"form": "认真对待过", "label": "体标"}], "register": "中性", "sense_fingerprint": "做事认真、不马虎、不敷衍", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79963f23-daa7-47ea-a422-83820dc3fd66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27310, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "认真对待", "is_correct": true, "explanation": "“认真对待”表示做事不马虎，与“做作业时要……不能马虎”相符。"}, {"text": "种植", "is_correct": false, "explanation": "搭配：“种植”用于植物，不能用于做作业。"}, {"text": "组装", "is_correct": false, "explanation": "搭配：“组装”用于零件或机器，不能用于做作业。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：作业不能被欣赏，与“不能马虎”的要求冲突。"}], "explanations": {"认真对待": "“认真对待”表示做事不马虎，与“做作业时要……不能马虎”相符。", "种植": "搭配：“种植”用于植物，不能用于做作业。", "组装": "搭配：“组装”用于零件或机器，不能用于做作业。", "欣赏": "语义：作业不能被欣赏，与“不能马虎”的要求冲突。"}, "sentence_index": 0, "correct_answer": "认真对待"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天都认真对待那片云。", "explanation": "这里应该用〈欣赏〉。〈认真对待〉指对事情的态度，不用于“那片云”这类景物，应说“欣赏那片云”。"}, {"text": "奶奶认真对待了一阵风。", "explanation": "这里应该用〈感受〉。〈认真对待〉指对事情的态度，不用于“一阵风”这类自然现象，应说“感受了一阵风”。"}, {"text": "他认真对待了一道闪电。", "explanation": "这里应该用〈躲避〉。〈认真对待〉指对事情的态度，不用于“一道闪电”，应说“躲避了一道闪电”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0637b4-a516-4149-95c7-5f1973d11154') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27310, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "认真对待", "is_correct": true, "explanation": "“认真对待”表示认真处理，“我会……你交给我的任务”符合语境。"}, {"text": "出售", "is_correct": false, "explanation": "语义：“出售”指卖东西，任务不能出售。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”用于场所或展览，不能用于任务。"}, {"text": "饲养", "is_correct": false, "explanation": "搭配：“饲养”用于动物，不能用于任务。"}], "explanations": {"认真对待": "“认真对待”表示认真处理，“我会……你交给我的任务”符合语境。", "出售": "语义：“出售”指卖东西，任务不能出售。", "参观": "搭配：“参观”用于场所或展览，不能用于任务。", "饲养": "搭配：“饲养”用于动物，不能用于任务。"}, "sentence_index": 6, "correct_answer": "认真对待"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她每天都认真对待那片天空。", "explanation": "这里应该用〈仰望〉。〈认真对待〉指对事情的态度，不用于“那片天空”，应说“仰望那片天空”。"}, {"text": "她认真对待了那片海。", "explanation": "这里应该用〈眺望〉。〈认真对待〉不用于“那片海”这类景物，应说“眺望那片海”。"}, {"text": "她认真对待了那阵雷声。", "explanation": "这里应该用〈听见〉。〈认真对待〉不用于“那阵雷声”这类声音，应说“听见那阵雷声”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0637b4-a516-4149-95c7-5f1973d11154') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27310, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从来没有认真对待了作业。", "corrected_sentence": "他从来没有认真对待过作业。", "error_description": "错误：表示经历的“认真对待”后用了“了”。正确：“从来没有”表示经历，应说“认真对待过作业”，用“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0637b4-a516-4149-95c7-5f1973d11154') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27310, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她对作业认真对待很好。", "corrected_sentence": "她对作业认真对待得很好。", "error_description": "错误：“认真对待”作谓语时缺少补语标记“得”。正确：表示程度的补语要用“得”连接，应说“认真对待得很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0637b4-a516-4149-95c7-5f1973d11154') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
