INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27314, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "机器人是一种能自己动的机器。", "primary_collocate": null, "pronunciation": "jī qì rén", "ipa": "tɕi˥ tɕʰi˥˩ ɻən˧˥", "syllable_count": 3, "sentences": [{"text": "这个机器人会跳舞。", "target_word": "机器人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂里有很多机器人。", "target_word": "机器人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给机器人起了一个名字。", "target_word": "机器人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器人可以帮我打扫房间。", "target_word": "机器人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的生日礼物是一个小机器人。", "target_word": "机器人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机器人会说中文。", "target_word": "机器人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "儿子正玩着机器人。", "target_word": "机器人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器人不会累，也不会生气。", "target_word": "机器人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一个会唱歌的机器人。", "target_word": "机器人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院里的机器人给病人送药。", "target_word": "机器人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个机器人", "label": "量词"}, {"form": "服务机器人", "label": "复合"}], "register": "中性", "sense_fingerprint": "能自动做事的机器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06053499-ed7b-46b4-88c1-4bffbe9831f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27314, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头没有生命，不会跳舞，与“会跳舞”相矛盾。"}, {"text": "机器人", "is_correct": true, "explanation": "“机器人”是能自己动的机器，可以“会跳舞”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是静止的家具，不能跳舞。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是静止的家电，不能跳舞，与“会跳舞”相矛盾。"}], "explanations": {"石头": "语义：石头没有生命，不会跳舞，与“会跳舞”相矛盾。", "机器人": "“机器人”是能自己动的机器，可以“会跳舞”。", "桌子": "语义：桌子是静止的家具，不能跳舞。", "冰箱": "语义：冰箱是静止的家电，不能跳舞，与“会跳舞”相矛盾。"}, "sentence_index": 0, "correct_answer": "机器人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "姐姐给弟弟买了一条机器人当生日礼物。", "explanation": "这里应该用〈个〉。“条”用于细长的事物，机器人的量词要用“个”或“台”。"}, {"text": "他工作起来像个机器人，从不休息。", "explanation": "这里的“机器人”是比喻义，指人像机器一样不知疲倦、缺少感情，不是“能自己动的机器”的意思。"}, {"text": "这台机器人要人踩着踏板才能动。", "explanation": "这里应该用〈机器〉。机器人是能自己动的机器，需要人踩踏板才能动的应该说“机器”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a704dd41-623e-44e9-8b48-d1a704de2e07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27314, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作业", "is_correct": false, "explanation": "搭配：“玩”后面不接“作业”，这里应说“做作业”。"}, {"text": "眼泪", "is_correct": false, "explanation": "语义：眼泪不能被当作玩具去玩，与“玩着”不搭。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不能作“玩”的对象，这个句子读来不通。"}, {"text": "机器人", "is_correct": true, "explanation": "“机器人”是儿子正在玩的玩具，与“玩着”相符。"}], "explanations": {"作业": "搭配：“玩”后面不接“作业”，这里应说“做作业”。", "眼泪": "语义：眼泪不能被当作玩具去玩，与“玩着”不搭。", "天气": "搭配：“天气”不能作“玩”的对象，这个句子读来不通。", "机器人": "“机器人”是儿子正在玩的玩具，与“玩着”相符。"}, "sentence_index": 6, "correct_answer": "机器人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家的机器人每天要吃两次饭。", "explanation": "这里应该用〈宠物〉。机器人靠电力或电池工作，不需要吃饭，“吃饭”一般用于宠物等生物。"}, {"text": "妈妈给弟弟买了一支机器人当玩具。", "explanation": "这里应该用〈个〉。“支”用于笔等细长物品，机器人不用“支”作量词。"}, {"text": "这家公司的网络机器人每天自动回复上千条消息。", "explanation": "这里的“机器人”是网络程序的意思，指自动运行的软件，不是实体机器，这一句用的是另一个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a704dd41-623e-44e9-8b48-d1a704de2e07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27314, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姐姐给弟弟买了一只机器人当生日礼物。", "corrected_sentence": "姐姐给弟弟买了一个机器人当生日礼物。", "error_description": "错误：“只”用于动物，机器人的量词应该用“个”，应说“买了一个机器人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a704dd41-623e-44e9-8b48-d1a704de2e07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27314, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个机器人搬很快，一小时就能搬完一车货。", "corrected_sentence": "这个机器人搬得很快，一小时就能搬完一车货。", "error_description": "错误：动词和补语之间要用结构助词“得”连接，应说“搬得很快”，不能说“搬很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a704dd41-623e-44e9-8b48-d1a704de2e07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
