INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27324, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西弄好，让它不坏。", "primary_collocate": null, "pronunciation": "xiū", "ipa": "ɕjoʊ˥", "syllable_count": 1, "sentences": [{"text": "冰箱坏了，我得找人修。", "target_word": "修", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在家里修椅子。", "target_word": "修", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "门锁坏了，爸爸正在修。", "target_word": "修", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这把雨伞还能修吗？", "target_word": "修", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想请人修一下这张桌子。", "target_word": "修", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥会修车，朋友们都找他帮忙。", "target_word": "修", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "灯不亮了，你会不会修？", "target_word": "修", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈的眼镜坏了，我陪她去店里修。", "target_word": "修", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房顶漏水了，工人今天来修。", "target_word": "修", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台洗衣机太旧了，修了也用不了多久。", "target_word": "修", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "修了", "label": "体标"}, {"form": "修着", "label": "体标"}, {"form": "修修", "label": "重叠"}, {"form": "修理", "label": "复合"}], "register": "口语", "sense_fingerprint": "把坏东西弄好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd4e57f7-af7c-4ea1-9953-f36f2503a567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27324, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "修", "is_correct": true, "explanation": "修 xiū（第一声）是本词，意思是修理。"}, {"text": "秀", "is_correct": false, "explanation": "xiù（第四声）与 xiū（第一声）声调不同，意思是秀丽、展示。"}, {"text": "袖", "is_correct": false, "explanation": "xiù（第四声）与 xiū（第一声）声调不同，意思是衣袖。"}, {"text": "朽", "is_correct": false, "explanation": "xiǔ（第三声）与 xiū（第一声）声调不同，意思是腐烂、腐朽。"}], "explanations": {"修": "修 xiū（第一声）是本词，意思是修理。", "秀": "xiù（第四声）与 xiū（第一声）声调不同，意思是秀丽、展示。", "袖": "xiù（第四声）与 xiū（第一声）声调不同，意思是衣袖。", "朽": "xiǔ（第三声）与 xiū（第一声）声调不同，意思是腐烂、腐朽。"}, "sentence_index": null, "correct_answer": "修"}, "level_3": {"options": [{"text": "修", "is_correct": true, "explanation": "正确：修指把坏了的东西弄好，符合“冰箱坏了，我得找人”的语境。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱与冰箱坏了后的处理需求无关，句子不通。"}, {"text": "洗", "is_correct": false, "explanation": "语义：洗与冰箱坏了之后需要的处理不符，句意不通。"}, {"text": "吃", "is_correct": false, "explanation": "语义：找人吃与冰箱坏了的语境无关，句意不通。"}], "explanations": {"修": "正确：修指把坏了的东西弄好，符合“冰箱坏了，我得找人”的语境。", "唱": "语义：唱与冰箱坏了后的处理需求无关，句子不通。", "洗": "语义：洗与冰箱坏了之后需要的处理不符，句意不通。", "吃": "语义：找人吃与冰箱坏了的语境无关，句意不通。"}, "sentence_index": 0, "correct_answer": "修"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈每天在厨房修蛋糕。", "explanation": "这里应该用〈烤〉。修指修理，不能用于烤制食物。"}, {"text": "他在锅里修饺子。", "explanation": "这里应该用〈煮〉。修指修理，不能用于烹煮饺子。"}, {"text": "学生们每天晚上在教室里修作业。", "explanation": "这里应该用〈写〉。修指把东西弄好，不能用于写作业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d10861e-3ecc-466f-9829-225dcfb68c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27324, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "修", "is_correct": true, "explanation": "修 xiū（第一声）是本词，意思是修理。"}, {"text": "绣", "is_correct": false, "explanation": "xiù（第四声）与 xiū（第一声）声调不同，意思是刺绣。"}, {"text": "锈", "is_correct": false, "explanation": "xiù（第四声）与 xiū（第一声）声调不同，意思是金属生锈。"}, {"text": "嗅", "is_correct": false, "explanation": "xiù（第四声）与 xiū（第一声）声调不同，意思是用鼻子闻。"}], "explanations": {"修": "修 xiū（第一声）是本词，意思是修理。", "绣": "xiù（第四声）与 xiū（第一声）声调不同，意思是刺绣。", "锈": "xiù（第四声）与 xiū（第一声）声调不同，意思是金属生锈。", "嗅": "xiù（第四声）与 xiū（第一声）声调不同，意思是用鼻子闻。"}, "sentence_index": null, "correct_answer": "修"}, "level_3": {"options": [{"text": "修", "is_correct": true, "explanation": "正确：修指把坏了的东西弄好，符合“灯不亮了，你会不会”的语境。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：跳舞与灯不亮的问题无关，句子不通。"}, {"text": "骑", "is_correct": false, "explanation": "语义：骑与灯不亮的问题无关，句意不通。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：游泳与灯不亮的问题无关，句意不合理。"}], "explanations": {"修": "正确：修指把坏了的东西弄好，符合“灯不亮了，你会不会”的语境。", "跳舞": "语义：跳舞与灯不亮的问题无关，句子不通。", "骑": "语义：骑与灯不亮的问题无关，句意不通。", "游泳": "语义：游泳与灯不亮的问题无关，句意不合理。"}, "sentence_index": 6, "correct_answer": "修"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天早上都要修水。", "explanation": "这里应该用〈喝〉。修指修理，不能用于饮水。"}, {"text": "她在舞台上修歌。", "explanation": "这里应该用〈唱〉。修指修理，不能用于唱歌。"}, {"text": "孩子们在操场上修舞。", "explanation": "这里应该用〈跳〉。修指修理，不能用于跳舞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d10861e-3ecc-466f-9829-225dcfb68c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27324, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把雨伞已经修了好。", "corrected_sentence": "这把雨伞已经修好了。", "error_description": "错误：结果补语“好”应紧跟动词“修”，正确说法是“修好了”，不能说“修了好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d10861e-3ecc-466f-9829-225dcfb68c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27324, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他昨天没修了这台电脑。", "corrected_sentence": "他昨天没修这台电脑。", "error_description": "错误：“没”表示否定时不与“了”同用，应说“他昨天没修这台电脑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d10861e-3ecc-466f-9829-225dcfb68c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27326, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "整齐", "is_correct": true, "explanation": "“整齐”与“乱”构成反义，指东西摆放有序。"}, {"text": "薄", "is_correct": false, "explanation": "“薄”说厚度，与“乱”没有反义关系。"}, {"text": "近", "is_correct": false, "explanation": "“近”说距离，与“乱”没有反义关系。"}, {"text": "窄", "is_correct": false, "explanation": "“窄”说宽度，与“乱”没有反义关系。"}], "correct_answer": "整齐", "explanations": {"整齐": "“整齐”与“乱”构成反义，指东西摆放有序。", "薄": "“薄”说厚度，与“乱”没有反义关系。", "近": "“近”说距离，与“乱”没有反义关系。", "窄": "“窄”说宽度，与“乱”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d10861e-3ecc-466f-9829-225dcfb68c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27326, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "井井有条", "is_correct": true, "explanation": "“井井有条”与“乱”构成反义，指东西摆放有条理。"}, {"text": "厚", "is_correct": false, "explanation": "“厚”说厚度，与“乱”没有反义关系。"}, {"text": "远", "is_correct": false, "explanation": "“远”说距离，与“乱”没有反义关系。"}, {"text": "慢", "is_correct": false, "explanation": "“慢”说速度，与“乱”没有反义关系。"}], "correct_answer": "井井有条", "explanations": {"井井有条": "“井井有条”与“乱”构成反义，指东西摆放有条理。", "厚": "“厚”说厚度，与“乱”没有反义关系。", "远": "“远”说距离，与“乱”没有反义关系。", "慢": "“慢”说速度，与“乱”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d10861e-3ecc-466f-9829-225dcfb68c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27326, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "东西摆放杂乱，没有次序。", "primary_collocate": null, "pronunciation": "luàn", "ipa": "lwan˥˩", "syllable_count": 1, "sentences": [{"text": "他不高兴，屋子里的东西很乱。", "target_word": "乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她生气以后，桌上的书乱了。", "target_word": "乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟发了脾气，玩具扔得很乱。", "target_word": "乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不高兴地回家，鞋子放得很乱。", "target_word": "乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈不高兴了，因为客厅太乱。", "target_word": "乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明心情不好，书包里乱得很。", "target_word": "乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吵架以后，房间里乱极了。", "target_word": "乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生气地走了，房间里的衣服和书都乱了。", "target_word": "乱", "complexity_tier": "T3", "furigana": "luàn", "sentence_source": "generated"}, {"text": "姐姐心情不好，衣服扔得很乱。", "target_word": "乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到乱的房间，妈妈更不高兴了。", "target_word": "乱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "乱了", "label": "体标"}, {"form": "混乱", "label": "复合"}, {"form": "亂", "label": "繁体"}], "register": "中性", "sense_fingerprint": "东西摆放杂乱无序", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd4e57f7-af7c-4ea1-9953-f36f2503a567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27326, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "乱", "is_correct": true, "explanation": "正确答案。“乱”读 luàn，指东西摆放得东倒西歪，即本词。"}, {"text": "算", "is_correct": false, "explanation": "suàn（算）与 luàn 声母不同（s 与 l），意思是计算。"}, {"text": "烂", "is_correct": false, "explanation": "làn（烂）比 luàn 少了介音 u，声音不同，意思是腐烂。"}, {"text": "论", "is_correct": false, "explanation": "lùn（论）比 luàn 少了韵母中的 a，声音不同，意思是讨论。"}, {"text": "换", "is_correct": false, "explanation": "huàn（换）与 luàn 声母不同（h 与 l），意思是交换。"}, {"text": "惯", "is_correct": false, "explanation": "guàn（惯）与 luàn 声母不同（g 与 l），意思是习惯。"}], "explanations": {"乱": "正确答案。“乱”读 luàn，指东西摆放得东倒西歪，即本词。", "算": "suàn（算）与 luàn 声母不同（s 与 l），意思是计算。", "烂": "làn（烂）比 luàn 少了介音 u，声音不同，意思是腐烂。", "论": "lùn（论）比 luàn 少了韵母中的 a，声音不同，意思是讨论。", "换": "huàn（换）与 luàn 声母不同（h 与 l），意思是交换。", "惯": "guàn（惯）与 luàn 声母不同（g 与 l），意思是习惯。"}, "sentence_index": null, "correct_answer": "乱"}, "level_3": {"options": [{"text": "乱", "is_correct": true, "explanation": "“乱”指东西摆放杂乱，与句中屋子的状态相符，句意通顺。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”形容高度或身材，不能用来形容屋子里东西的状态。"}, {"text": "慢", "is_correct": false, "explanation": "语义：“慢”说速度，不能用来形容屋子里东西的摆放。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”形容身材，东西不能用“胖”来形容。"}], "explanations": {"乱": "“乱”指东西摆放杂乱，与句中屋子的状态相符，句意通顺。", "矮": "体貌：“矮”形容高度或身材，不能用来形容屋子里东西的状态。", "慢": "语义：“慢”说速度，不能用来形容屋子里东西的摆放。", "胖": "体貌：“胖”形容身材，东西不能用“胖”来形容。"}, "sentence_index": 0, "correct_answer": "乱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服很乱，要两千块钱。", "explanation": "这里应该用〈贵〉。“乱”指没有条理，不能用来说价格高。"}, {"text": "学校离家很乱，要走一个小时。", "explanation": "这里应该用〈远〉。“乱”指没有条理，不能用来说距离远近。"}, {"text": "他的脚很乱，穿不下这双鞋。", "explanation": "这里应该用〈大〉。“乱”指没有条理，不能用来形容脚的大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d10861e-3ecc-466f-9829-225dcfb68c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27326, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "乱", "is_correct": true, "explanation": "正确答案。“乱”读 luàn，指东西摆放得东倒西歪，即本词。"}, {"text": "卵", "is_correct": false, "explanation": "luǎn（卵）与 luàn 声调不同（第三声与第四声），意思是卵子。"}, {"text": "段", "is_correct": false, "explanation": "duàn（段）与 luàn 声母不同（d 与 l），意思是一段。"}, {"text": "卷", "is_correct": false, "explanation": "juàn（卷）与 luàn 声母不同（j 与 l），意思是卷起。"}, {"text": "劝", "is_correct": false, "explanation": "quàn（劝）与 luàn 声母不同（q 与 l），意思是劝说。"}, {"text": "钻", "is_correct": false, "explanation": "zuàn（钻）与 luàn 声母不同（z 与 l），意思是钻研。"}], "explanations": {"乱": "正确答案。“乱”读 luàn，指东西摆放得东倒西歪，即本词。", "卵": "luǎn（卵）与 luàn 声调不同（第三声与第四声），意思是卵子。", "段": "duàn（段）与 luàn 声母不同（d 与 l），意思是一段。", "卷": "juàn（卷）与 luàn 声母不同（j 与 l），意思是卷起。", "劝": "quàn（劝）与 luàn 声母不同（q 与 l），意思是劝说。", "钻": "zuàn（钻）与 luàn 声母不同（z 与 l），意思是钻研。"}, "sentence_index": null, "correct_answer": "乱"}, "level_3": {"options": [{"text": "乱", "is_correct": true, "explanation": "“乱”指东西杂乱，“乱极了”形容房间很乱，句意通顺。"}, {"text": "快", "is_correct": false, "explanation": "语义：“快”说速度，不能用来形容房间的状态。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”说味道，与房间的状态无关，句子不通。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”形容人或动物的身材，不能用来形容房间。"}], "explanations": {"乱": "“乱”指东西杂乱，“乱极了”形容房间很乱，句意通顺。", "快": "语义：“快”说速度，不能用来形容房间的状态。", "甜": "语义：“甜”说味道，与房间的状态无关，句子不通。", "瘦": "体貌：“瘦”形容人或动物的身材，不能用来形容房间。"}, "sentence_index": 6, "correct_answer": "乱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块肉放久了，已经乱了。", "explanation": "这里应该用〈烂〉。“乱”指东西摆放杂乱，不能用来说食物腐坏。"}, {"text": "他的身高很乱，几乎有一米九。", "explanation": "这里应该用〈高〉。“乱”指没有条理，不能用来形容身高。"}, {"text": "这顿饭的味道很乱，大家都没吃。", "explanation": "这里应该用〈糟糕〉。“乱”指没有条理，不能用来评价味道的好坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d10861e-3ecc-466f-9829-225dcfb68c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27326, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一生气，床上的被子就掀得乱很。", "corrected_sentence": "他一生气，床上的被子就掀得很乱。", "error_description": "语序错误：补语“乱”前要加“很”，应说“掀得很乱”，“掀得乱很”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d10861e-3ecc-466f-9829-225dcfb68c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27326, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把衣柜乱了，找不到外套。", "corrected_sentence": "他把衣柜弄乱了，找不到外套。", "error_description": "漏掉动词：“乱”不能直接放在“把”字句中作谓语，应补“弄”，说“把衣柜弄乱了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d10861e-3ecc-466f-9829-225dcfb68c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
