INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27330, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "有的人钱很多，有的人钱很少，他们之间的差别。", "primary_collocate": null, "pronunciation": "pín fù chā jù", "ipa": "pʰin˧˥ fu˥˩ ʈʂʰa˥ tɕy˥˩", "syllable_count": 4, "sentences": [{"text": "这个村子的贫富差距很明显。", "target_word": "贫富差距", "complexity_tier": "T3", "furigana": "zhè gè cūnzi de pínfù chājù hěn míngxiǎn", "sentence_source": "generated"}, {"text": "贫富差距大的地方，孩子上学也不容易。", "target_word": "贫富差距", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她写了一本书，说的是贫富差距。", "target_word": "贫富差距", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都希望缩小贫富差距。", "target_word": "贫富差距", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "在这个城市，贫富差距让很多人不高兴。", "target_word": "贫富差距", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师问我们：贫富差距是什么意思？", "target_word": "贫富差距", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过去那里没有明显的贫富差距。", "target_word": "贫富差距", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电视里正在讨论贫富差距。", "target_word": "贫富差距", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "两个地方的贫富差距还在变大。", "target_word": "贫富差距", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我觉得贫富差距对社会不好。", "target_word": "贫富差距", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "有钱人和没钱人之间钱财多少的差别", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f3cf8ff-25c5-4d6f-b0ac-df147fb79767') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27330, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "贫富差距", "is_correct": true, "explanation": "正确：“这个村子的贫富差距很明显”说的是村里人之间财富的差别，符合句意。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”是人的性情，村子没有脾气，不能说“很明显”。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“心情”只用于人，村子不能有心情。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，不能用来形容村子。"}], "explanations": {"贫富差距": "正确：“这个村子的贫富差距很明显”说的是村里人之间财富的差别，符合句意。", "脾气": "语义：“脾气”是人的性情，村子没有脾气，不能说“很明显”。", "心情": "语义：“心情”只用于人，村子不能有心情。", "身材": "体貌：“身材”指人的体形，不能用来形容村子。"}, "sentence_index": 0, "correct_answer": "贫富差距"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我比弟弟高，贫富差距有五厘米。", "explanation": "这里应该用〈身高差距〉。贫富差距指财富上的差别，不能用厘米来计算。"}, {"text": "这次考试，我和他的贫富差距有二十分。", "explanation": "这里应该用〈成绩差距〉。“二十分”是分数，贫富差距指财富的差别，不能用分数来计算。"}, {"text": "这辆车和那辆车的贫富差距很大。", "explanation": "这里应该用〈速度差距〉。贫富差距指人与人之间财富、收入的差别，不能用来比较车的速度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a272a790-830f-4bd5-a3e2-ce1c82265682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27330, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "贫富差距", "is_correct": true, "explanation": "正确：“过去那里没有明显的贫富差距”指当地财富差别不大，符合句意。"}, {"text": "日期", "is_correct": false, "explanation": "搭配：“日期”是确定的时间，不说“明显的日期”，与“明显”不搭配。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，不能用来形容一个地方。"}, {"text": "饭量", "is_correct": false, "explanation": "语义：“饭量”指一个人吃饭的分量，不能用来说一个地方“没有明显的饭量”。"}], "explanations": {"贫富差距": "正确：“过去那里没有明显的贫富差距”指当地财富差别不大，符合句意。", "日期": "搭配：“日期”是确定的时间，不说“明显的日期”，与“明显”不搭配。", "身材": "体貌：“身材”指人的体形，不能用来形容一个地方。", "饭量": "语义：“饭量”指一个人吃饭的分量，不能用来说一个地方“没有明显的饭量”。"}, "sentence_index": 6, "correct_answer": "贫富差距"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我和哥哥的贫富差距有十公斤。", "explanation": "这里应该用〈体重差距〉。贫富差距说的是财富，不能用公斤来计量。"}, {"text": "他的贫富差距是一点五。", "explanation": "这里应该用〈视力差距〉。贫富差距指财富的差别，不能用视力数值来表示。"}, {"text": "这两件衣服的贫富差距很大。", "explanation": "这里应该用〈尺寸差距〉。贫富差距指人与人之间财富、收入的差别，不能用来比较衣服的尺寸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a272a790-830f-4bd5-a3e2-ce1c82265682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27330, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个村子有一片很明显的贫富差距。", "corrected_sentence": "这个村子有一个很明显的贫富差距。", "error_description": "错误形式：“一片”。正确形式：“一个”。“片”用于成片的事物或面积，不能修饰“贫富差距”，应用量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a272a790-830f-4bd5-a3e2-ce1c82265682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27330, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要把这只贫富差距缩小，好吗？", "corrected_sentence": "我们要把这种贫富差距缩小，好吗？", "error_description": "错误形式：“这只贫富差距”。正确形式：“这种贫富差距”。“只”用于动物或成只的物品，不能修饰抽象的“贫富差距”，应用量词“种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a272a790-830f-4bd5-a3e2-ce1c82265682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27331, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "真话", "is_correct": true, "explanation": "“真话”与“假话”构成反义，指真实的言语。"}, {"text": "歌", "is_correct": false, "explanation": "“歌”指歌曲，与“假话”没有反义关系。"}, {"text": "饭", "is_correct": false, "explanation": "“饭”指食物，与“假话”没有反义关系。"}, {"text": "树", "is_correct": false, "explanation": "“树”指植物，与“假话”没有反义关系。"}], "correct_answer": "真话", "explanations": {"真话": "“真话”与“假话”构成反义，指真实的言语。", "歌": "“歌”指歌曲，与“假话”没有反义关系。", "饭": "“饭”指食物，与“假话”没有反义关系。", "树": "“树”指植物，与“假话”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d10861e-3ecc-466f-9829-225dcfb68c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27331, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "实话", "is_correct": true, "explanation": "“实话”与“假话”构成反义，指真实的言语。"}, {"text": "书", "is_correct": false, "explanation": "“书”指书籍，与“假话”没有反义关系。"}, {"text": "车", "is_correct": false, "explanation": "“车”指交通工具，与“假话”没有反义关系。"}, {"text": "花", "is_correct": false, "explanation": "“花”指植物，与“假话”没有反义关系。"}], "correct_answer": "实话", "explanations": {"实话": "“实话”与“假话”构成反义，指真实的言语。", "书": "“书”指书籍，与“假话”没有反义关系。", "车": "“车”指交通工具，与“假话”没有反义关系。", "花": "“花”指植物，与“假话”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d10861e-3ecc-466f-9829-225dcfb68c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27331, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "假话就是不说真的事情，故意骗别人。", "primary_collocate": null, "pronunciation": "jiǎ huà", "ipa": "tɕja˨˩ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "他故意说假话，想骗我借钱给他。", "target_word": "假话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明没做作业，却对老师说假话。", "target_word": "假话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用假话骗了奶奶很多年。", "target_word": "假话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子怕挨骂，就编了一句假话。", "target_word": "假话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了不让妈妈担心，他说了假话。", "target_word": "假话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商人说的都是假话，别相信他。", "target_word": "假话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "假话骗得了一时，骗不了一世。", "target_word": "假话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我发现他的话是假话，心里很难过。", "target_word": "假话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一直对朋友说假话，最后朋友都不理他了。", "target_word": "假话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说自己生病了，可那是假话。", "target_word": "假话", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一句假话", "label": "量词"}, {"form": "假話", "label": "繁体"}], "register": "口语", "sense_fingerprint": "故意骗人的话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd4e57f7-af7c-4ea1-9953-f36f2503a567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27331, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "假话", "is_correct": true, "explanation": "正确答案。“假话”读 jiǎ huà，指故意骗人的话，即本词。"}, {"text": "傻话", "is_correct": false, "explanation": "shǎ（傻）与 jiǎ 声母不同（sh 与 j），意思是糊涂的话。"}, {"text": "佳话", "is_correct": false, "explanation": "jiā（佳）与 jiǎ 声调不同（第一声与第三声），意思是美好的事迹、传为美谈的事。"}, {"text": "假花", "is_correct": false, "explanation": "huā（花）与 huà 声调不同（第一声与第四声），意思是假的花。"}, {"text": "蠢话", "is_correct": false, "explanation": "chǔn（蠢）与 jiǎ 声母不同（ch 与 j），意思是愚蠢的话。"}], "explanations": {"假话": "正确答案。“假话”读 jiǎ huà，指故意骗人的话，即本词。", "傻话": "shǎ（傻）与 jiǎ 声母不同（sh 与 j），意思是糊涂的话。", "佳话": "jiā（佳）与 jiǎ 声调不同（第一声与第三声），意思是美好的事迹、传为美谈的事。", "假花": "huā（花）与 huà 声调不同（第一声与第四声），意思是假的花。", "蠢话": "chǔn（蠢）与 jiǎ 声母不同（ch 与 j），意思是愚蠢的话。"}, "sentence_index": null, "correct_answer": "假话"}, "level_3": {"options": [{"text": "假话", "is_correct": true, "explanation": "“假话”指故意骗人的话，与“说”搭配，句意通顺。"}, {"text": "诗", "is_correct": false, "explanation": "语义：“诗”与“骗我借钱”的语境不符，句意不通。"}, {"text": "饭", "is_correct": false, "explanation": "语义：“饭”指食物，不能作为“说”的内容，句子不通。"}, {"text": "纸", "is_correct": false, "explanation": "语义：“纸”指材料，不能作为“说”的内容，句子不通。"}], "explanations": {"假话": "“假话”指故意骗人的话，与“说”搭配，句意通顺。", "诗": "语义：“诗”与“骗我借钱”的语境不符，句意不通。", "饭": "语义：“饭”指食物，不能作为“说”的内容，句子不通。", "纸": "语义：“纸”指材料，不能作为“说”的内容，句子不通。"}, "sentence_index": 0, "correct_answer": "假话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这批假话是厂里生产的，质量很好。", "explanation": "这里应该用〈假货〉。“假话”指虚假的言语，不能指生产的商品，要说“假货”。"}, {"text": "他一件假话都不肯说。", "explanation": "这里应该用〈句〉。“件”用于物品，“假话”以“句”计量。"}, {"text": "这事很假话，大家都不相信。", "explanation": "这里应该用形容词〈虚假〉。“假话”是名词，不能直接作谓语形容事情不真实。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d10861e-3ecc-466f-9829-225dcfb68c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27331, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "假话", "is_correct": true, "explanation": "“假话”指故意骗人的话，可以作主语“骗得了一时”，句意通顺。"}, {"text": "真话", "is_correct": false, "explanation": "语义：“真话”与“骗”矛盾，真话骗不了人，句子不通。"}, {"text": "歌", "is_correct": false, "explanation": "语义：“歌”不能用来骗人，句子不通。"}, {"text": "粗话", "is_correct": false, "explanation": "语义：粗话不能用来骗人，“粗话骗得了一时”句意不通。"}], "explanations": {"假话": "“假话”指故意骗人的话，可以作主语“骗得了一时”，句意通顺。", "真话": "语义：“真话”与“骗”矛盾，真话骗不了人，句子不通。", "歌": "语义：“歌”不能用来骗人，句子不通。", "粗话": "语义：粗话不能用来骗人，“粗话骗得了一时”句意不通。"}, "sentence_index": 6, "correct_answer": "假话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块表是假话做的，戴出去很丢人。", "explanation": "这里应该用〈假货〉。“假话”指虚假的言语，不能指做成的物件，要说“假货”。"}, {"text": "她编了一块假话，骗了老师。", "explanation": "这里应该用〈句〉。“块”用于块状物，不能用于话语；“假话”以“句”计量。"}, {"text": "他很假话，大家都不喜欢他。", "explanation": "这里应该用形容词〈虚伪〉。“假话”是名词，指虚假的言语，不能作谓语评价人的性格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d10861e-3ecc-466f-9829-225dcfb68c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27331, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她为了躲避责任，一直在说一块假话。", "corrected_sentence": "她为了躲避责任，一直在说一句假话。", "error_description": "量词错误：“假话”以“句”计量，“块”不能用于话语，应说“一句假话”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d10861e-3ecc-466f-9829-225dcfb68c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27331, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他写的信里有很多块假话，别信他。", "corrected_sentence": "他写的信里有很多句假话，别信他。", "error_description": "量词错误：“假话”以“句”计量，“块”不能用于话语，应说“很多句假话”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d10861e-3ecc-466f-9829-225dcfb68c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
