INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27340, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "表示肯定，意思是“对的”。", "primary_collocate": null, "pronunciation": "shì", "ipa": "ʂʐ̩˥˩", "syllable_count": 1, "sentences": [{"text": "“你叫王明吗？”“是，我叫王明。”", "target_word": "是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他问我累不累，我说：“是，有点累。”", "target_word": "是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问：“作业写完了吗？”小林答：“是，写完了。”", "target_word": "是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理说：“明天八点开会。”小张说：“是，我记住了。”", "target_word": "是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“你是新来的同学吧？”“是，我今天刚到。”", "target_word": "是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈问：“你去过那儿吗？”我答：“是，去过一次。”", "target_word": "是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他点点头说：“是，你说得对。”", "target_word": "是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“这是你的书包吗？”“是，是我的。”", "target_word": "是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说：“请把门关上。”小王答：“是，马上关。”", "target_word": "是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“你也喜欢音乐吧？”“是，我天天听。”", "target_word": "是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "回答时表示肯定、同意，意思是对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '447b2f2c-611b-4adc-a6ed-b618209aaf2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27340, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "是", "is_correct": true, "explanation": "是：表示肯定、同意，意思是“对”，即本词条的目标词。"}, {"text": "寺", "is_correct": false, "explanation": "sì 与 shì 声母不同（s / sh），声调相同，意思是“寺庙”。"}, {"text": "失", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，意思是“丢失”。"}, {"text": "施", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，意思是“施行、给予”。"}, {"text": "石", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是“石头”。"}], "explanations": {"是": "是：表示肯定、同意，意思是“对”，即本词条的目标词。", "寺": "sì 与 shì 声母不同（s / sh），声调相同，意思是“寺庙”。", "失": "shī（第一声）与 shì（第四声）声调不同，意思是“丢失”。", "施": "shī（第一声）与 shì（第四声）声调不同，意思是“施行、给予”。", "石": "shí（第二声）与 shì（第四声）声调不同，意思是“石头”。"}, "sentence_index": null, "correct_answer": "是"}, "level_3": {"options": [{"text": "是", "is_correct": true, "explanation": "是：表示肯定，用于回答“你叫王明吗？”，符合语境。"}, {"text": "哇", "is_correct": false, "explanation": "语义：“哇”表示惊叹或哭声，不表示应答，与“我叫王明”的确认语境不合。"}, {"text": "哈", "is_correct": false, "explanation": "语义：“哈”表示笑声或轻笑，不能用来确认自己的名字。"}, {"text": "呸", "is_correct": false, "explanation": "语域：“呸”是表示鄙视的口语叹词，用在这里语气不对，也不表示应答。"}], "explanations": {"是": "是：表示肯定，用于回答“你叫王明吗？”，符合语境。", "哇": "语义：“哇”表示惊叹或哭声，不表示应答，与“我叫王明”的确认语境不合。", "哈": "语义：“哈”表示笑声或轻笑，不能用来确认自己的名字。", "呸": "语域：“呸”是表示鄙视的口语叹词，用在这里语气不对，也不表示应答。"}, "sentence_index": 0, "correct_answer": "是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "“你要茶还是咖啡？”“是，我要茶。”", "explanation": "“是”只用来回答是非问句，不能回答选择问句；这里应直接说“我要茶”。"}, {"text": "“谢谢你的帮助！”“是，不客气。”", "explanation": "对感谢一般直接说“不客气”，不用“是”来回应，用在这里语气不对。"}, {"text": "“谁能帮我搬一下箱子？”“是，我来吧。”", "explanation": "这里应直接说“我来吧”。“是”只用来回答是非问句，不能回答“谁”这类特殊疑问句。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6a458cc-0e81-446e-9b52-8645627b3211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27340, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "是", "is_correct": true, "explanation": "是：表示肯定、同意，意思是“对”，即本词条的目标词。"}, {"text": "似", "is_correct": false, "explanation": "sì 与 shì 声母不同（s / sh），声调相同，意思是“像”。"}, {"text": "狮", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，意思是“狮子”。"}, {"text": "十", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是数字“十”。"}, {"text": "史", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）声调不同，意思是“历史”。"}], "explanations": {"是": "是：表示肯定、同意，意思是“对”，即本词条的目标词。", "似": "sì 与 shì 声母不同（s / sh），声调相同，意思是“像”。", "狮": "shī（第一声）与 shì（第四声）声调不同，意思是“狮子”。", "十": "shí（第二声）与 shì（第四声）声调不同，意思是数字“十”。", "史": "shǐ（第三声）与 shì（第四声）声调不同，意思是“历史”。"}, "sentence_index": null, "correct_answer": "是"}, "level_3": {"options": [{"text": "是", "is_correct": true, "explanation": "是：表示肯定，用于回应对方的意见，符合“你说得对”的语境。"}, {"text": "哼", "is_correct": false, "explanation": "语义：“哼”表示不满或轻蔑，与“点点头”的赞同动作相矛盾。"}, {"text": "咦", "is_correct": false, "explanation": "语义：“咦”表示惊讶或疑问，不表示同意。"}, {"text": "嘁", "is_correct": false, "explanation": "语域：“嘁”是轻蔑的口语叹词，与“点点头说”的认真应答语气不符。"}], "explanations": {"是": "是：表示肯定，用于回应对方的意见，符合“你说得对”的语境。", "哼": "语义：“哼”表示不满或轻蔑，与“点点头”的赞同动作相矛盾。", "咦": "语义：“咦”表示惊讶或疑问，不表示同意。", "嘁": "语域：“嘁”是轻蔑的口语叹词，与“点点头说”的认真应答语气不符。"}, "sentence_index": 6, "correct_answer": "是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "“你叫什么名字？”“是，我叫王明。”", "explanation": "“是”只用来回答是非问句，不能回答“什么”这类特殊疑问句，这里应直接说“我叫王明”。"}, {"text": "“你好！”“是，你也好。”", "explanation": "问候时一般回应“你好”，不用“是”来回应，用在这里不合习惯。"}, {"text": "“天气怎么样？”“是，很好。”", "explanation": "这里应该直接说“很好”。“是”表示肯定，不用来回答“怎么样”这类询问状况的问题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6a458cc-0e81-446e-9b52-8645627b3211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27340, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "“你是老板吗？”“不是，我是老板。”", "corrected_sentence": "“你是老板吗？”“是，我是老板。”", "error_description": "“不是”表示否定，与后面的“我是老板”矛盾；对肯定问句的肯定回答应说“是”，不说“不是”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6a458cc-0e81-446e-9b52-8645627b3211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27340, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "“这本书是你的吗？”“是不是，我天天看。”", "corrected_sentence": "“这本书是你的吗？”“是，我天天看。”", "error_description": "“是不是”是正反问结构，不能用来回答；对是非问句作肯定回答直接说“是”，应说“是，我天天看。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6a458cc-0e81-446e-9b52-8645627b3211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
