INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27342, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "看看数据有没有问题。", "primary_collocate": null, "pronunciation": "jiǎn chá shù jù", "ipa": "tɕjɛn˨˩ ʈʂʰa˧˥ ʂu˥˩ tɕy˥˩", "syllable_count": 4, "sentences": [{"text": "开会以前，我想先检查数据。", "target_word": "检查数据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "财务部的同事在检查数据，请等一下。", "target_word": "检查数据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让学生检查数据，看有没有写错。", "target_word": "检查数据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "把表格发出去以前，先检查数据。", "target_word": "检查数据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边检查数据，一边在本子上写字。", "target_word": "检查数据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天晚上我检查数据到十一点。", "target_word": "检查数据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她很认真，总是仔细检查数据。", "target_word": "检查数据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次的表格太长了，一个人检查数据要花很长时间。", "target_word": "检查数据", "complexity_tier": "T3", "furigana": "zhè cì de biǎo gé tài cháng le, yí gè rén jiǎn chá shù jù yào huā hěn cháng shí jiān.", "sentence_source": "generated"}, {"text": "机器出错以后，工程师马上检查数据。", "target_word": "检查数据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你检查数据，看看哪里不对。", "target_word": "检查数据", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "检查了数据", "label": "体标"}, {"form": "檢查數據", "label": "繁体"}], "register": "通用", "sense_fingerprint": "查看数据有没有问题", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd4e57f7-af7c-4ea1-9953-f36f2503a567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27342, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "检查数据", "is_correct": true, "explanation": "正确：检查数据指查看数据有没有问题，符合“开会以前，我想先”的语境。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：跳舞与开会前的准备无关，句子不通。"}, {"text": "吵架", "is_correct": false, "explanation": "语义：开会前先吵架与会议的正常准备相悖，句意不合理。"}, {"text": "养狗", "is_correct": false, "explanation": "语义：养狗与开会前的准备无关，句子不通。"}], "explanations": {"检查数据": "正确：检查数据指查看数据有没有问题，符合“开会以前，我想先”的语境。", "跳舞": "语义：跳舞与开会前的准备无关，句子不通。", "吵架": "语义：开会前先吵架与会议的正常准备相悖，句意不合理。", "养狗": "语义：养狗与开会前的准备无关，句子不通。"}, "sentence_index": 0, "correct_answer": "检查数据"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "爷爷每个月都去医院检查数据。", "explanation": "这里应该用〈体检〉。检查数据针对信息，人的身体健康检查要说体检。"}, {"text": "研究人员正在野外检查笑话，大家都笑了。", "explanation": "这里应该用〈讲〉。检查数据指看东西有没有问题，不能用于讲笑话。"}, {"text": "他每天去公园检查数据，锻炼身体。", "explanation": "这里应该用〈运动〉。检查数据指看东西有没有问题，不指在公园做运动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d10861e-3ecc-466f-9829-225dcfb68c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27342, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "检查数据", "is_correct": true, "explanation": "正确：检查数据指仔细核对信息，符合“她很认真，总是仔细”的语境。"}, {"text": "说谎", "is_correct": false, "explanation": "语义：说谎与“很认真”的描述相矛盾，句意不通。"}, {"text": "逃跑", "is_correct": false, "explanation": "语义：逃跑与“很认真”“仔细”的描述不符，句意不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉与“很认真”“仔细”的描述不相符，句子不通。"}], "explanations": {"检查数据": "正确：检查数据指仔细核对信息，符合“她很认真，总是仔细”的语境。", "说谎": "语义：说谎与“很认真”的描述相矛盾，句意不通。", "逃跑": "语义：逃跑与“很认真”“仔细”的描述不符，句意不通。", "睡觉": "语义：睡觉与“很认真”“仔细”的描述不相符，句子不通。"}, "sentence_index": 6, "correct_answer": "检查数据"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请你检查数据的味道，看看哪里不对。", "explanation": "这里应该用〈尝〉。检查数据指看东西有没有问题，不指品尝味道。"}, {"text": "请你检查数据的身高，看看哪里不对。", "explanation": "这里应该用〈量〉。检查数据指看东西有没有问题，不指测量身高。"}, {"text": "请你检查数据的脾气，看看哪里不对。", "explanation": "这里应该用〈了解〉。检查数据指看东西有没有问题，不用于了解别人的脾气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d10861e-3ecc-466f-9829-225dcfb68c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27342, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她明天检查过数据。", "corrected_sentence": "她明天检查数据。", "error_description": "体标误用：“过”表示已经发生或曾经历的动作，不能与表示将来的“明天”同用。正确：删去“过”，应说“她明天检查数据”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d10861e-3ecc-466f-9829-225dcfb68c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27342, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们昨天没检查了数据。", "corrected_sentence": "我们昨天没检查数据。", "error_description": "错误：“没”表示否定时不与“了”同用，应说“我们昨天没检查数据”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d10861e-3ecc-466f-9829-225dcfb68c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
