INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27352, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示否定，常见于判断句“不是”。", "primary_collocate": null, "pronunciation": "bù", "ipa": "pu˥˩", "syllable_count": 1, "sentences": [{"text": "他不是老师，是医生。", "target_word": "不", "complexity_tier": "T3", "furigana": "tā bú shì lǎoshī, shì yīshēng.", "sentence_source": "generated"}, {"text": "这不是我的书。", "target_word": "不", "complexity_tier": "T3", "furigana": "zhè bú shì wǒ de shū.", "sentence_source": "generated"}, {"text": "今天不是星期天。", "target_word": "不", "complexity_tier": "T3", "furigana": "jīntiān bú shì xīngqītiān.", "sentence_source": "generated"}, {"text": "那个人不是我弟弟。", "target_word": "不", "complexity_tier": "T3", "furigana": "nàge rén bú shì wǒ dìdi.", "sentence_source": "generated"}, {"text": "这个东西不是免费的。", "target_word": "不", "complexity_tier": "T3", "furigana": "zhège dōngxi bú shì miǎnfèi de.", "sentence_source": "generated"}, {"text": "他不是中国人，是日本人。", "target_word": "不", "complexity_tier": "T3", "furigana": "tā bú shì Zhōngguórén, shì Rìběnrén.", "sentence_source": "generated"}, {"text": "她不是学生，她是工人。", "target_word": "不", "complexity_tier": "T3", "furigana": "tā bú shì xuésheng, tā shì gōngrén.", "sentence_source": "generated"}, {"text": "这不是问题，而是机会。", "target_word": "不", "complexity_tier": "T3", "furigana": "zhè bú shì wèntí, ér shì jīhuì.", "sentence_source": "generated"}, {"text": "我不是故意的。", "target_word": "不", "complexity_tier": "T3", "furigana": "wǒ bú shì gùyì de.", "sentence_source": "generated"}, {"text": "这不是真的。", "target_word": "不", "complexity_tier": "T3", "furigana": "zhè bú shì zhēn de.", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词：放在动词或形容词前，表示否定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff2dc4db-9995-4fb8-b9e3-e98d425bf1f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27352, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不", "is_correct": true, "explanation": "正确。“不”（bù，第四声）用在“是”前表示否定判断。"}, {"text": "度", "is_correct": false, "explanation": "度（dù，第四声）与 bù 声母不同（d 与 b），意思是程度。"}, {"text": "路", "is_correct": false, "explanation": "路（lù，第四声）与 bù 声母不同（l 与 b），意思是道路。"}, {"text": "护", "is_correct": false, "explanation": "护（hù，第四声）与 bù 声母不同（h 与 b），意思是保护。"}, {"text": "故", "is_correct": false, "explanation": "故（gù，第四声）与 bù 声母不同（g 与 b），意思是缘故。"}], "explanations": {"不": "正确。“不”（bù，第四声）用在“是”前表示否定判断。", "度": "度（dù，第四声）与 bù 声母不同（d 与 b），意思是程度。", "路": "路（lù，第四声）与 bù 声母不同（l 与 b），意思是道路。", "护": "护（hù，第四声）与 bù 声母不同（h 与 b），意思是保护。", "故": "故（gù，第四声）与 bù 声母不同（g 与 b），意思是缘故。"}, "sentence_index": null, "correct_answer": "不"}, "level_3": {"options": [{"text": "不", "is_correct": true, "explanation": "正确。“他不是老师”是否定判断句，与后句“是医生”相符。"}, {"text": "没", "is_correct": false, "explanation": "搭配：“没”不能与“是”直接组合，“没是老师”不成立。"}, {"text": "正在", "is_correct": false, "explanation": "搭配：“正在”表示动作进行，不能与判断动词“是”搭配，“他正在是老师”不成立。"}, {"text": "很", "is_correct": false, "explanation": "语域：“很是”属于书面语，且与后句的对比结构不协调，口语中不这样说。"}], "explanations": {"不": "正确。“他不是老师”是否定判断句，与后句“是医生”相符。", "没": "搭配：“没”不能与“是”直接组合，“没是老师”不成立。", "正在": "搭配：“正在”表示动作进行，不能与判断动词“是”搭配，“他正在是老师”不成立。", "很": "语域：“很是”属于书面语，且与后句的对比结构不协调，口语中不这样说。"}, "sentence_index": 0, "correct_answer": "不"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我不是知道他的名字，我不认识他。", "explanation": "这里应该用〈不〉。〈不是〉用于判断，这里要陈述“不知道”这一状态，应说“我不知道他的名字”。"}, {"text": "他不是来了，所以我们开始吧。", "explanation": "这里应该用〈没〉。〈不是〉用于判断，不能否定“来了”这种动作的完成，应说“他没来，所以我们开始吧。”"}, {"text": "我不是饱了，所以还要吃饭。", "explanation": "这里应该用〈没〉。〈不是〉用于判断，不能否定“饱了”这类状态，应说“我还没饱，所以还要吃饭。”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bb3f5c4-42e4-4b4e-92d9-88bee7a69a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27352, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "不", "is_correct": true, "explanation": "正确。“不”（bù）用在“是”前表示否定判断。"}, {"text": "木", "is_correct": false, "explanation": "木（mù，第四声）与 bù 声母不同（m 与 b），意思是树木。"}, {"text": "怒", "is_correct": false, "explanation": "怒（nù，第四声）与 bù 声母不同（n 与 b），意思是愤怒。"}, {"text": "补", "is_correct": false, "explanation": "补（bǔ，第三声）与 bù 声调不同，意思是补充。"}, {"text": "幕", "is_correct": false, "explanation": "幕（mù，第四声）与 bù 声母不同（m 与 b），意思是幕布。"}], "explanations": {"不": "正确。“不”（bù）用在“是”前表示否定判断。", "木": "木（mù，第四声）与 bù 声母不同（m 与 b），意思是树木。", "怒": "怒（nù，第四声）与 bù 声母不同（n 与 b），意思是愤怒。", "补": "补（bǔ，第三声）与 bù 声调不同，意思是补充。", "幕": "幕（mù，第四声）与 bù 声母不同（m 与 b），意思是幕布。"}, "sentence_index": null, "correct_answer": "不"}, "level_3": {"options": [{"text": "不", "is_correct": true, "explanation": "正确。“她不是学生”是否定判断句，与后句“她是工人”相符。"}, {"text": "正在", "is_correct": false, "explanation": "搭配：“正在”表示动作进行，不能与“是”这类判断动词搭配。"}, {"text": "最", "is_correct": false, "explanation": "语义：“最”表示最高程度，与判断句“是学生”的语义不合。"}, {"text": "太", "is_correct": false, "explanation": "搭配：“太”要修饰形容词或心理动词，不能直接修饰“是”。"}], "explanations": {"不": "正确。“她不是学生”是否定判断句，与后句“她是工人”相符。", "正在": "搭配：“正在”表示动作进行，不能与“是”这类判断动词搭配。", "最": "语义：“最”表示最高程度，与判断句“是学生”的语义不合。", "太": "搭配：“太”要修饰形容词或心理动词，不能直接修饰“是”。"}, "sentence_index": 6, "correct_answer": "不"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个苹果甜不是，我们吃吧。", "explanation": "这里应该用〈不〉。〈不是〉是判断动词，不能放在形容词后；应说“这个苹果不甜，我们吃吧。”"}, {"text": "这个消息很不是真，别相信。", "explanation": "这里应该用〈不〉。〈不是〉是判断动词，不能受〈很〉修饰；应说“这个消息不太真，别相信。”"}, {"text": "这个消息没是真的，别相信。", "explanation": "这里应该用〈不是〉。判断句的否定要用〈不是〉，〈没〉不能与〈是〉直接组合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bb3f5c4-42e4-4b4e-92d9-88bee7a69a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27352, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我姐姐是不老师，她是护士。", "corrected_sentence": "我姐姐不是老师，她是护士。", "error_description": "否定词位置错误：判断句的否定词“不”要放在“是”前，应为“不是老师”，不能说“是不老师”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bb3f5c4-42e4-4b4e-92d9-88bee7a69a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27352, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个消息不真是的，别相信。", "corrected_sentence": "这个消息不是真的，别相信。", "error_description": "语序错误：否定词和“是”应放在“真的”前，应为“不是真的”，不能说“不真是的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bb3f5c4-42e4-4b4e-92d9-88bee7a69a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
