INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27354, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把不对的变成对的。", "primary_collocate": null, "pronunciation": "gǎi", "ipa": "kai˨˩˦", "syllable_count": 1, "sentences": [{"text": "老师正在改同学们的作业。", "target_word": "改", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这句话有错，你改一下。", "target_word": "改", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他写错了字，马上改过来了。", "target_word": "改", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "知道错了就要改。", "target_word": "改", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我的作文有三个错字，我都改了。", "target_word": "改", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做错了没关系，改了就好。", "target_word": "改", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个坏习惯，他一直没改掉。", "target_word": "改", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的发音不对，老师让他改。", "target_word": "改", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把文章里的错别字改了。", "target_word": "改", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有错就改，这样才能进步。", "target_word": "改", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "改了", "label": "体标"}, {"form": "改过", "label": "体标"}, {"form": "改改", "label": "重叠"}, {"form": "改正", "label": "复合"}, {"form": "修改", "label": "复合"}], "register": "中性", "sense_fingerprint": "纠正错误、把错的变成对的（改错、改作业、改掉坏习惯）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b2747cf-51da-4bed-8a3e-6845ab573b37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27354, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "改", "is_correct": true, "explanation": "正确：改（gǎi），意思是纠正、把错的变成对的。"}, {"text": "海", "is_correct": false, "explanation": "hǎi（第三声）与 gǎi 声母不同（h 与 g），意思是大海。"}, {"text": "奶", "is_correct": false, "explanation": "nǎi（第三声）与 gǎi 声母不同（n 与 g），意思是牛奶。"}, {"text": "盖", "is_correct": false, "explanation": "gài（第四声）与 gǎi 声调不同，意思是覆盖、盖住。"}, {"text": "凯", "is_correct": false, "explanation": "kǎi（第三声）与 gǎi 声母不同（k 与 g），意思是凯旋、胜利。"}], "explanations": {"改": "正确：改（gǎi），意思是纠正、把错的变成对的。", "海": "hǎi（第三声）与 gǎi 声母不同（h 与 g），意思是大海。", "奶": "nǎi（第三声）与 gǎi 声母不同（n 与 g），意思是牛奶。", "盖": "gài（第四声）与 gǎi 声调不同，意思是覆盖、盖住。", "凯": "kǎi（第三声）与 gǎi 声母不同（k 与 g），意思是凯旋、胜利。"}, "sentence_index": null, "correct_answer": "改"}, "level_3": {"options": [{"text": "改", "is_correct": true, "explanation": "正确：“改同学们的作业”指批改、纠正作业中的错误，符合语境。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，作业不能吃。"}, {"text": "踢", "is_correct": false, "explanation": "语义：“踢”指用脚撞击，作业不能用脚去踢，句意不通。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不与“作业”搭配，不能说“唱作业”。"}], "explanations": {"改": "正确：“改同学们的作业”指批改、纠正作业中的错误，符合语境。", "吃": "语义：“吃”指进食，作业不能吃。", "踢": "语义：“踢”指用脚撞击，作业不能用脚去踢，句意不通。", "唱": "搭配：“唱”不与“作业”搭配，不能说“唱作业”。"}, "sentence_index": 0, "correct_answer": "改"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的个子改高了。", "explanation": "这里应该用〈长〉。个子是自然生长，没有对错，不能用“改”；“改”指把错的改成对的。"}, {"text": "他改得很均匀。", "explanation": "这里应该用〈呼吸〉。“改”用于把错的变成对的，不能形容呼吸这类动作；“呼吸得很均匀”要用“呼吸”。"}, {"text": "他改掉了旧手机。", "explanation": "这里应该用〈换〉。“改掉”表示改正或去除错误、坏习惯，不能用来表示替换东西；旧手机应说“换掉”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9f5352-89b3-42b0-bd8d-a9707f7bfa85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27354, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "改", "is_correct": true, "explanation": "正确：改（gǎi），意思是纠正、把错的变成对的。"}, {"text": "买", "is_correct": false, "explanation": "mǎi（第三声）与 gǎi 声母不同（m 与 g），意思是购买。"}, {"text": "搞", "is_correct": false, "explanation": "gǎo（第三声）与 gǎi 韵母不同（o 与 i），意思是做、干。"}, {"text": "该", "is_correct": false, "explanation": "gāi（第一声）与 gǎi 声调不同，意思是应当、该当。"}, {"text": "百", "is_correct": false, "explanation": "bǎi（第三声）与 gǎi 声母不同（b 与 g），意思是一百。"}, {"text": "感", "is_correct": false, "explanation": "gǎn（第三声）与 gǎi 韵母不同（n 与 i），意思是感觉。"}], "explanations": {"改": "正确：改（gǎi），意思是纠正、把错的变成对的。", "买": "mǎi（第三声）与 gǎi 声母不同（m 与 g），意思是购买。", "搞": "gǎo（第三声）与 gǎi 韵母不同（o 与 i），意思是做、干。", "该": "gāi（第一声）与 gǎi 声调不同，意思是应当、该当。", "百": "bǎi（第三声）与 gǎi 声母不同（b 与 g），意思是一百。", "感": "gǎn（第三声）与 gǎi 韵母不同（n 与 i），意思是感觉。"}, "sentence_index": null, "correct_answer": "改"}, "level_3": {"options": [{"text": "改", "is_correct": true, "explanation": "正确：“没改掉”指没有改正掉这个坏习惯，符合语境。"}, {"text": "养", "is_correct": false, "explanation": "搭配：“养”与“成”搭配成“养成习惯”，不说“养掉坏习惯”。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”指书写，与“坏习惯”无关，“没写掉坏习惯”说不通。"}, {"text": "玩", "is_correct": false, "explanation": "语义：“玩”指玩耍，“玩掉坏习惯”不成立。"}], "explanations": {"改": "正确：“没改掉”指没有改正掉这个坏习惯，符合语境。", "养": "搭配：“养”与“成”搭配成“养成习惯”，不说“养掉坏习惯”。", "写": "语义：“写”指书写，与“坏习惯”无关，“没写掉坏习惯”说不通。", "玩": "语义：“玩”指玩耍，“玩掉坏习惯”不成立。"}, "sentence_index": 6, "correct_answer": "改"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的血压改低了。", "explanation": "这里应该用〈降低〉。血压升降是数量变化，不是对错的纠正，不能说“改低”。"}, {"text": "他改了一朵花。", "explanation": "这里应该用〈摘〉。摘花是取下花朵的动作，“改”用于把错的变对，不能用于摘花。"}, {"text": "他改了一支烟。", "explanation": "这里应该用〈抽〉。烟是抽的，“改”只用于纠正对错，不能用于抽烟这类动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9f5352-89b3-42b0-bd8d-a9707f7bfa85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27354, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他下次会把错字改过来了。", "corrected_sentence": "他下次会把错字改过来。", "error_description": "“了”用错：“下次”表示将来，动作尚未发生，“改过来”后不能加“了”，应说“他下次会把错字改过来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9f5352-89b3-42b0-bd8d-a9707f7bfa85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27354, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我已经把错字好改了。", "corrected_sentence": "我已经把错字改好了。", "error_description": "错误形式：“好改了”；正确形式：“改好了”。结果补语“好”应紧跟在动词“改”之后，不能放在“改”前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9f5352-89b3-42b0-bd8d-a9707f7bfa85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27356, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "虚伪", "is_correct": true, "explanation": "反义：“虚伪”指表里不一、不真实，与“诚实”（不说谎、为人可靠）相反。"}, {"text": "活泼", "is_correct": false, "explanation": "无反义关系：“活泼”形容性格开朗、爱动，与“诚实”的意思无关。"}, {"text": "大方", "is_correct": false, "explanation": "无反义关系：“大方”形容不拘小节、慷慨，与“诚实”的意思无关。"}, {"text": "勇敢", "is_correct": false, "explanation": "无反义关系：“勇敢”形容胆量大，与“诚实”的意思无关。"}], "correct_answer": "虚伪", "explanations": {"虚伪": "反义：“虚伪”指表里不一、不真实，与“诚实”（不说谎、为人可靠）相反。", "活泼": "无反义关系：“活泼”形容性格开朗、爱动，与“诚实”的意思无关。", "大方": "无反义关系：“大方”形容不拘小节、慷慨，与“诚实”的意思无关。", "勇敢": "无反义关系：“勇敢”形容胆量大，与“诚实”的意思无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9f5352-89b3-42b0-bd8d-a9707f7bfa85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27356, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "虚伪", "is_correct": true, "explanation": "反义：“虚伪”指表里不一、不真实，与“诚实”（不说谎、为人可靠）相反。"}, {"text": "安静", "is_correct": false, "explanation": "无反义关系：“安静”形容声音小、环境静，与“诚实”的意思无关。"}, {"text": "严肃", "is_correct": false, "explanation": "无反义关系：“严肃”形容态度认真庄重，与“诚实”的意思无关。"}, {"text": "幽默", "is_correct": false, "explanation": "无反义关系：“幽默”形容说话风趣，与“诚实”的意思无关。"}], "correct_answer": "虚伪", "explanations": {"虚伪": "反义：“虚伪”指表里不一、不真实，与“诚实”（不说谎、为人可靠）相反。", "安静": "无反义关系：“安静”形容声音小、环境静，与“诚实”的意思无关。", "严肃": "无反义关系：“严肃”形容态度认真庄重，与“诚实”的意思无关。", "幽默": "无反义关系：“幽默”形容说话风趣，与“诚实”的意思无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9f5352-89b3-42b0-bd8d-a9707f7bfa85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27356, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不说谎，做实事。", "primary_collocate": null, "pronunciation": "chéng shí", "ipa": "tʂʰɤŋ˧˥ ʂɻ˧˥", "syllable_count": 2, "sentences": [{"text": "这个孩子很诚实，从来不说谎。", "target_word": "诚实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "诚实的人不会骗人。", "target_word": "诚实", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他为人诚实，做事认真。", "target_word": "诚实", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小明很诚实，打破杯子后马上承认了。", "target_word": "诚实", "complexity_tier": "T3", "furigana": "xiǎo míng hěn chéng shí, dǎ pò bēi zi hòu mǎ shàng chéng rèn le.", "sentence_source": "generated"}, {"text": "妈妈常教我们要诚实。", "target_word": "诚实", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他很诚实，捡到钱包就交给了警察。", "target_word": "诚实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考试的时候，诚实比分数更重要。", "target_word": "诚实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位商人诚实可靠，大家都愿意和他做生意。", "target_word": "诚实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有诚实地回答，所以老师有点生气。", "target_word": "诚实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做错了事，诚实地说出来才对。", "target_word": "诚实", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "誠實", "label": "繁体"}], "register": "中性", "sense_fingerprint": "不说谎、不骗人，为人踏实可靠（不说谎、诚实可靠、诚实地说出来）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b2747cf-51da-4bed-8a3e-6845ab573b37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27356, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "诚实", "is_correct": true, "explanation": "正确：“很诚实，从来不说谎”指不说谎、为人可靠，符合语境。"}, {"text": "狡猾", "is_correct": false, "explanation": "语义：“狡猾”指耍手段骗人，与“从来不说谎”相悖。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容体形，不用来说人的品性。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”说身材，与人的品性无关，不能和“从来不说谎”搭配。"}], "explanations": {"诚实": "正确：“很诚实，从来不说谎”指不说谎、为人可靠，符合语境。", "狡猾": "语义：“狡猾”指耍手段骗人，与“从来不说谎”相悖。", "高大": "搭配：“高大”形容体形，不用来说人的品性。", "瘦": "体貌：“瘦”说身材，与人的品性无关，不能和“从来不说谎”搭配。"}, "sentence_index": 0, "correct_answer": "诚实"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他诚实地帮助我们。", "explanation": "这里应该用〈真心〉。“诚实”指不说谎、言行可靠，不用来修饰“帮助”这类动作；表示待人态度真诚要用〈真心〉。"}, {"text": "他很诚实，敢一个人去救火。", "explanation": "这里应该用〈勇敢〉。“诚实”指不说谎、做实事，不表示胆量；敢一个人救火要说“勇敢”。"}, {"text": "这块石头很诚实。", "explanation": "这里应该用〈坚硬〉。石头的硬度要说“坚硬”，“诚实”只指人不说谎、做实事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9f5352-89b3-42b0-bd8d-a9707f7bfa85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27356, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "诚实", "is_correct": true, "explanation": "正确：“考试的时候，诚实比分数更重要”，表示为人可靠比分数重要，符合语境。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”说外貌，与“考试”和“分数”无关，不能说“漂亮比分数更重要”。"}, {"text": "吵闹", "is_correct": false, "explanation": "语义：“吵闹”指声音杂乱，与考试时对为人的要求不搭，说不通。"}, {"text": "懒", "is_correct": false, "explanation": "语义：“懒”指不愿动，说“懒比分数更重要”于理不通。"}], "explanations": {"诚实": "正确：“考试的时候，诚实比分数更重要”，表示为人可靠比分数重要，符合语境。", "漂亮": "体貌：“漂亮”说外貌，与“考试”和“分数”无关，不能说“漂亮比分数更重要”。", "吵闹": "语义：“吵闹”指声音杂乱，与考试时对为人的要求不搭，说不通。", "懒": "语义：“懒”指不愿动，说“懒比分数更重要”于理不通。"}, "sentence_index": 6, "correct_answer": "诚实"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈诚实地笑了。", "explanation": "这里应该用〈开心〉。“诚实”描述说话做事是否真实可靠，不用来形容笑这种表情。"}, {"text": "她学习很诚实，每天都复习。", "explanation": "这里应该用〈勤奋〉。“诚实”指不说谎、做实事，不说明学习用功与否；学习刻苦要用“勤奋”。"}, {"text": "这片云很诚实。", "explanation": "这里应该用〈洁白〉。云的颜色要说“洁白”，“诚实”只用于描述人的品行，不能形容云。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9f5352-89b3-42b0-bd8d-a9707f7bfa85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27356, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他回答很诚实。", "corrected_sentence": "他回答得很诚实。", "error_description": "错误形式：“回答很诚实”；正确形式：“回答得很诚实”。作补语的形容词前要用结构助词“得”连接动词和补语，漏掉“得”，句子不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9f5352-89b3-42b0-bd8d-a9707f7bfa85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27356, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她诚实的地承认了错误。", "corrected_sentence": "她诚实地承认了错误。", "error_description": "错误形式：“诚实的地承认”；正确形式：“诚实地承认”。修饰动词的状语要用“地”，“的”用于名词性定语，“诚实的”后不能再接“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9f5352-89b3-42b0-bd8d-a9707f7bfa85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27358, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86635e38-5915-4314-90db-e832f39de107') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
