INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27362, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "知道或懂得一件事。", "primary_collocate": null, "pronunciation": "míng bai", "ipa": "miŋ˧˥ pai", "syllable_count": 2, "sentences": [{"text": "老师讲得很慢，大家都明白了。", "target_word": "明白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不明白这个字的意思。", "target_word": "明白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你明白怎么做了吗？", "target_word": "明白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他明白妈妈为什么生气。", "target_word": "明白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题我明白了，谢谢你。", "target_word": "明白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子还不明白什么是危险。", "target_word": "明白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我明白你的想法，但是不同意。", "target_word": "明白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要先明白规则，再开始玩游戏。", "target_word": "明白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你明白老师的话吗？", "target_word": "明白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她点点头，说自己明白了。", "target_word": "明白", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "明白了", "label": "体标"}], "register": "中性", "sense_fingerprint": "知道或懂得一件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edbb42d2-d5e9-4e3a-bea1-4e5446f06e3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27362, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "名牌", "is_correct": false, "explanation": "名牌 míngpái 与 míngbai 第二个音节的声母不同（p 与 b），声调也不同，意思是名牌商品。"}, {"text": "明白", "is_correct": true, "explanation": "正确答案：明白 míngbai，表示知道或懂得一件事。"}, {"text": "清白", "is_correct": false, "explanation": "清白 qīngbai 与 míngbai 第一个音节的声母不同（q 与 m），声调也不同，意思是清白、无可指责。"}, {"text": "明摆", "is_correct": false, "explanation": "明摆 míngbǎi 与 míngbai 韵母相同，只差声调（第三声对轻声），意思是明显、摆在眼前。"}], "explanations": {"名牌": "名牌 míngpái 与 míngbai 第二个音节的声母不同（p 与 b），声调也不同，意思是名牌商品。", "明白": "正确答案：明白 míngbai，表示知道或懂得一件事。", "清白": "清白 qīngbai 与 míngbai 第一个音节的声母不同（q 与 m），声调也不同，意思是清白、无可指责。", "明摆": "明摆 míngbǎi 与 míngbai 韵母相同，只差声调（第三声对轻声），意思是明显、摆在眼前。"}, "sentence_index": null, "correct_answer": "明白"}, "level_3": {"options": [{"text": "反对", "is_correct": false, "explanation": "语义：“反对”与“老师讲得很慢”之后大家理解了的语境不符。"}, {"text": "明白", "is_correct": true, "explanation": "正确答案：“大家都明白了”表示大家都懂了老师讲的内容，符合句意。"}, {"text": "撒谎", "is_correct": false, "explanation": "语义：“撒谎”与课堂上的讲解和理解无关，句意荒谬。"}, {"text": "同情", "is_correct": false, "explanation": "语义：「同情」指对他人遭遇的怜悯，与老师讲得很慢、大家都理解了的语境不符。"}], "explanations": {"反对": "语义：“反对”与“老师讲得很慢”之后大家理解了的语境不符。", "明白": "正确答案：“大家都明白了”表示大家都懂了老师讲的内容，符合句意。", "撒谎": "语义：“撒谎”与课堂上的讲解和理解无关，句意荒谬。", "同情": "语义：「同情」指对他人遭遇的怜悯，与老师讲得很慢、大家都理解了的语境不符。"}, "sentence_index": 0, "correct_answer": "明白"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这篇文章写得很明白，连小学生都看得懂。", "explanation": "这里的“明白”作形容词，表示文章清楚易懂，不是“知道或懂得一件事”的意思。"}, {"text": "他是个明白人，从来不在大事上糊涂。", "explanation": "这里的“明白人”指头脑清楚、通情达理的人，形容人的品质，不表示懂得某件事。"}, {"text": "他明白地表示反对，没有绕弯子。", "explanation": "这里的“明白地”作副词，表示态度公开、直接，不表示懂得某件事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7c39780-8988-4b42-a3b5-6f702742c09d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27362, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同意", "is_correct": false, "explanation": "语义：“同意”与后句“但是不同意”自相矛盾，句意不通。"}, {"text": "明白", "is_correct": true, "explanation": "正确答案：“我明白你的想法，但是不同意”表示理解但不赞成，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“想法”搭配，不能说“吃你的想法”。"}, {"text": "碰", "is_correct": false, "explanation": "搭配：“碰”不能与“想法”搭配，句子不通。"}], "explanations": {"同意": "语义：“同意”与后句“但是不同意”自相矛盾，句意不通。", "明白": "正确答案：“我明白你的想法，但是不同意”表示理解但不赞成，符合句意。", "吃": "搭配：“吃”不能与“想法”搭配，不能说“吃你的想法”。", "碰": "搭配：“碰”不能与“想法”搭配，句子不通。"}, "sentence_index": 6, "correct_answer": "明白"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我明白了敲门声。", "explanation": "这里应该用〈听见〉。“明白”指理解，声音被听到要用“听见”。"}, {"text": "我明白了新同学。", "explanation": "这里应该用〈认识〉。“明白”不用于指认人，认识新同学要用“认识”。"}, {"text": "我明白了钥匙。", "explanation": "这里应该用〈找到〉。“明白”不表示寻找或发现具体物品，找到钥匙要用“找到”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7c39780-8988-4b42-a3b5-6f702742c09d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27362, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我还没明白了这道题的意思。", "corrected_sentence": "我还没明白这道题的意思。", "error_description": "错误：“没”否定尚未发生的动作时，动词后不能加“了”。应为“我还没明白这道题的意思”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7c39780-8988-4b42-a3b5-6f702742c09d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27362, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他被明白了妈妈的意思。", "corrected_sentence": "他明白了妈妈的意思。", "error_description": "错误：“明白”是心理动词，不能用“被”构成被动句，“被”不应加在“明白”前面。应为“他明白了妈妈的意思”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7c39780-8988-4b42-a3b5-6f702742c09d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
