INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27366, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让别人做事情。", "primary_collocate": null, "pronunciation": "ràng", "ipa": "ɻɑŋ˥˩", "syllable_count": 1, "sentences": [{"text": "老板让我今天写完报告。", "target_word": "让", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈让我去买牛奶。", "target_word": "让", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生让他多休息。", "target_word": "让", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师让我们打开书。", "target_word": "让", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他让朋友帮他拿行李。", "target_word": "让", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "奶奶让我早点回家。", "target_word": "让", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "经理让小王给客户打电话。", "target_word": "让", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "姐姐让我把门关上。", "target_word": "让", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她让儿子洗手再吃饭。", "target_word": "让", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "朋友让我明天一起去爬山。", "target_word": "让", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "让了", "label": "完成体"}, {"form": "不让", "label": "否定形式"}], "register": "中性", "sense_fingerprint": "动词：叫、吩咐别人去做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff2dc4db-9995-4fb8-b9e3-e98d425bf1f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27366, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "让", "is_correct": true, "explanation": "让：第四声，表示“使别人做某事”。"}, {"text": "浪", "is_correct": false, "explanation": "làng（第四声）与 ràng 声母不同（l 与 r），意思是波浪。"}, {"text": "嚷", "is_correct": false, "explanation": "rǎng（第三声）与 ràng 声调不同，意思是大声喊叫。"}, {"text": "瓤", "is_correct": false, "explanation": "ráng（第二声）与 ràng 只差声调，意思是瓜瓤。"}, {"text": "荡", "is_correct": false, "explanation": "dàng（第四声）与 ràng 声母不同（d 与 r），意思是摇荡。"}], "explanations": {"让": "让：第四声，表示“使别人做某事”。", "浪": "làng（第四声）与 ràng 声母不同（l 与 r），意思是波浪。", "嚷": "rǎng（第三声）与 ràng 声调不同，意思是大声喊叫。", "瓤": "ráng（第二声）与 ràng 只差声调，意思是瓜瓤。", "荡": "dàng（第四声）与 ràng 声母不同（d 与 r），意思是摇荡。"}, "sentence_index": null, "correct_answer": "让"}, "level_3": {"options": [{"text": "让", "is_correct": true, "explanation": "让：使役动词，表示“使别人做某事”，与后面的兼语结构搭配。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能带兼语结构“我今天写完报告”，句子不通。"}, {"text": "送", "is_correct": false, "explanation": "语义：“送”指递交、赠送，不能表示“使人去做事”。"}, {"text": "打", "is_correct": false, "explanation": "搭配：“打”与“写完报告”不搭配，句子不通。"}], "explanations": {"让": "让：使役动词，表示“使别人做某事”，与后面的兼语结构搭配。", "吃": "搭配：“吃”不能带兼语结构“我今天写完报告”，句子不通。", "送": "语义：“送”指递交、赠送，不能表示“使人去做事”。", "打": "搭配：“打”与“写完报告”不搭配，句子不通。"}, "sentence_index": 0, "correct_answer": "让"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的钱包让小偷偷走了。", "explanation": "这里的“让”表示被动，相当于“被”，指钱包被小偷偷走，不是“使别人做事”的意思。"}, {"text": "我把座位让给了老人。", "explanation": "这里的“让”是“把座位给别人”的意思（让座），不是“使别人做事”的意思。"}, {"text": "这件事我们各让一步。", "explanation": "这里的“让”是“退让、妥协”的意思（让步），不是“使别人做事”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bb3f5c4-42e4-4b4e-92d9-88bee7a69a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27366, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "让", "is_correct": true, "explanation": "让：第四声，表示“使别人做某事”。"}, {"text": "忘", "is_correct": false, "explanation": "wàng（第四声）与 ràng 声母不同（w 与 r），意思是忘记。"}, {"text": "壤", "is_correct": false, "explanation": "rǎng（第三声）与 ràng 声调不同，意思是土壤。"}, {"text": "葬", "is_correct": false, "explanation": "zàng（第四声）与 ràng 声母不同（z 与 r），意思是埋葬。"}], "explanations": {"让": "让：第四声，表示“使别人做某事”。", "忘": "wàng（第四声）与 ràng 声母不同（w 与 r），意思是忘记。", "壤": "rǎng（第三声）与 ràng 声调不同，意思是土壤。", "葬": "zàng（第四声）与 ràng 声母不同（z 与 r），意思是埋葬。"}, "sentence_index": null, "correct_answer": "让"}, "level_3": {"options": [{"text": "让", "is_correct": true, "explanation": "让：使役动词，表示“使别人做某事”，句中“让小王给客户打电话”是兼语结构。"}, {"text": "扶", "is_correct": false, "explanation": "语义：“扶”指搀扶身体，不能表示“使人去打电话”。"}, {"text": "拍", "is_correct": false, "explanation": "搭配：“拍”不能带兼语结构“小王给客户打电话”，句子不通。"}, {"text": "抱", "is_correct": false, "explanation": "配价：“抱”是及物动词，不能带兼语结构，句子不通。"}], "explanations": {"让": "让：使役动词，表示“使别人做某事”，句中“让小王给客户打电话”是兼语结构。", "扶": "语义：“扶”指搀扶身体，不能表示“使人去打电话”。", "拍": "搭配：“拍”不能带兼语结构“小王给客户打电话”，句子不通。", "抱": "配价：“抱”是及物动词，不能带兼语结构，句子不通。"}, "sentence_index": 6, "correct_answer": "让"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服可以再让五十块钱吗？", "explanation": "这里的“让”是“减价、少收”的意思（让价），不表示“使别人做事”。"}, {"text": "这盘棋他让我三个子，我还是输了。", "explanation": "这里的“让”是下棋时让对方先放几子、减少对方优势的意思（让子），不是“使别人做事”的意思。"}, {"text": "请大家让一让，我要过去。", "explanation": "这里的“让”是“躲开、让出路”的意思（让开），不是“使别人做事”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bb3f5c4-42e4-4b4e-92d9-88bee7a69a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27366, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈让不弟弟看电视。", "corrected_sentence": "妈妈不让弟弟看电视。", "error_description": "否定词“不”应放在“让”前面，应说“不让”，不能说“让不”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bb3f5c4-42e4-4b4e-92d9-88bee7a69a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27366, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店长让给顾客拿样品。", "corrected_sentence": "店长让小李给顾客拿样品。", "error_description": "“让”后面要有兼语，即指出谁去做事。应说“让小李给顾客拿样品”，这里缺少“小李”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bb3f5c4-42e4-4b4e-92d9-88bee7a69a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
