INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27370, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一起做事情的人或公司。", "primary_collocate": null, "pronunciation": "hé zuò huǒ bàn", "ipa": "xɤ˧˥ tswo˥˩ xwo˧˩ pan˥˩", "syllable_count": 4, "sentences": [{"text": "他是我做生意的合作伙伴。", "target_word": "合作伙伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和朋友成了合作伙伴，一起开了一家咖啡店。", "target_word": "合作伙伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位合作伙伴很聪明，也很努力。", "target_word": "合作伙伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想找一个能一起做事的合作伙伴。", "target_word": "合作伙伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的合作伙伴明天会来开会。", "target_word": "合作伙伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做这个游戏需要两个人，你想当我的合作伙伴吗？", "target_word": "合作伙伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家商店是我们公司的合作伙伴。", "target_word": "合作伙伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们做了五年的合作伙伴，从来没吵过架。", "target_word": "合作伙伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的合作伙伴今天没来，我一个人做事。", "target_word": "合作伙伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王和小李一起开公司，是好合作伙伴。", "target_word": "合作伙伴", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "一起做事情的人或公司", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edbb42d2-d5e9-4e3a-bea1-4e5446f06e3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27370, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "花朵", "is_correct": false, "explanation": "语义：「花朵」不能与人一起做生意，与「做生意的」语境不符。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：「雨伞」是物品，不是可以一起做生意的对象。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：「身材」是外形特征，不指做生意的人或组织。"}, {"text": "合作伙伴", "is_correct": true, "explanation": "正确。「做生意的合作伙伴」指一起经营的人或公司。"}], "explanations": {"花朵": "语义：「花朵」不能与人一起做生意，与「做生意的」语境不符。", "雨伞": "语义：「雨伞」是物品，不是可以一起做生意的对象。", "身材": "体貌：「身材」是外形特征，不指做生意的人或组织。", "合作伙伴": "正确。「做生意的合作伙伴」指一起经营的人或公司。"}, "sentence_index": 0, "correct_answer": "合作伙伴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天都给合作伙伴换一次电池。", "explanation": "这里应该用〈机器〉。合作伙伴指一起做事的人或公司，不能像机器一样换电池。"}, {"text": "他每天都给合作伙伴浇水。", "explanation": "这里应该用〈植物〉。合作伙伴指一起做事的人或公司，不能像植物一样浇水。"}, {"text": "他很喜欢吃合作伙伴。", "explanation": "这里应该用〈零食〉。合作伙伴指一起做事的人或公司，不能用“吃”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7c39780-8988-4b42-a3b5-6f702742c09d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27370, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同学", "is_correct": false, "explanation": "语义：「同学」指同校学习的人，不能用来指一家商店。"}, {"text": "小说", "is_correct": false, "explanation": "语义：「小说」是文学作品，不是可以与公司构成合作关系的对象。"}, {"text": "合作伙伴", "is_correct": true, "explanation": "正确。「公司的合作伙伴」指与公司共同做事的商店。"}, {"text": "哥们", "is_correct": false, "explanation": "语域：「哥们」是口语词，不适合用来正式描述公司之间的关系。"}], "explanations": {"同学": "语义：「同学」指同校学习的人，不能用来指一家商店。", "小说": "语义：「小说」是文学作品，不是可以与公司构成合作关系的对象。", "合作伙伴": "正确。「公司的合作伙伴」指与公司共同做事的商店。", "哥们": "语域：「哥们」是口语词，不适合用来正式描述公司之间的关系。"}, "sentence_index": 6, "correct_answer": "合作伙伴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "合作伙伴在黑板上写下了课文。", "explanation": "这里应该用〈老师〉。合作伙伴指一起做事的人，不指在黑板上教课的人。"}, {"text": "他把合作伙伴切成了三块。", "explanation": "这里应该用〈蛋糕〉。合作伙伴指一起做事的人或公司，不能被切开。"}, {"text": "他把合作伙伴放进了冰箱。", "explanation": "这里应该用〈食物〉。合作伙伴指一起做事的人或公司，不能像食物一样放进冰箱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7c39780-8988-4b42-a3b5-6f702742c09d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27370, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我和他合作伙伴了五年。", "corrected_sentence": "我和他合作了五年。", "error_description": "词性错误：「合作伙伴」是名词，不能当动词带「了」使用；应改用动词「合作」，写作「合作了五年」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7c39780-8988-4b42-a3b5-6f702742c09d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27370, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们公司有三合作伙伴。", "corrected_sentence": "我们公司有三个合作伙伴。", "error_description": "量词错误：数词「三」与「合作伙伴」之间须加量词「个」（或「位」），写作「三个合作伙伴」；「三合作伙伴」不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7c39780-8988-4b42-a3b5-6f702742c09d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
