INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27372, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "动手制作出具体成品，或作出决定、选择等。", "primary_collocate": null, "pronunciation": "zuò chū", "ipa": "tswo˥˩ tʂʰu˥", "syllable_count": 2, "sentences": [{"text": "妈妈用面粉做出了一个大蛋糕。", "target_word": "做出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用木头做出一张小桌子。", "target_word": "做出", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们用纸做出了很多小船。", "target_word": "做出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "厨师用鸡蛋和西红柿做出一道好菜。", "target_word": "做出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生们做出了一个会动的机器人。", "target_word": "做出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她想了一晚上，做出了一个决定。", "target_word": "做出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人们用三天时间做出了新的模型。", "target_word": "做出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你做出一个选择：去还是不去？", "target_word": "做出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶用旧布做出了一件漂亮的小衣服。", "target_word": "做出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用旧车的零件做出了一辆自行车。", "target_word": "做出", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "做出了", "label": "完成体"}, {"form": "做出过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "做出+具体成品或决定，把东西做成、做好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edbb42d2-d5e9-4e3a-bea1-4e5446f06e3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27372, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：“吃”表示进食，面粉不能被“吃”成蛋糕。"}, {"text": "做出", "is_correct": true, "explanation": "正确答案：“用面粉做出了一个大蛋糕”表示用面粉制成蛋糕，符合句意。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的对象是文字或图画，不能说“写一个大蛋糕”。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”表示饮用，不能与“蛋糕”搭配。"}], "explanations": {"吃": "语义：“吃”表示进食，面粉不能被“吃”成蛋糕。", "做出": "正确答案：“用面粉做出了一个大蛋糕”表示用面粉制成蛋糕，符合句意。", "写": "搭配：“写”的对象是文字或图画，不能说“写一个大蛋糕”。", "喝": "语义：“喝”表示饮用，不能与“蛋糕”搭配。"}, "sentence_index": 0, "correct_answer": "做出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他做出了一个新朋友。", "explanation": "这里应该用〈交〉。“做出”指制作具体成品，结交朋友要用“交”。"}, {"text": "妈妈做出了一个小宝宝。", "explanation": "这里应该用〈生〉。“做出”不表示生育，生孩子要用“生”。"}, {"text": "我做出了一位老朋友。", "explanation": "这里应该用〈遇到〉。“做出”指制作，已经存在的人遇见要用“遇到”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7c39780-8988-4b42-a3b5-6f702742c09d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27372, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吞", "is_correct": false, "explanation": "语义：“吞”表示咽下，与“用三天时间制作模型”的语境不符。"}, {"text": "做出", "is_correct": true, "explanation": "正确答案：“用三天时间做出了新的模型”表示制作完成，符合句意。"}, {"text": "说", "is_correct": false, "explanation": "搭配：“说”的对象是话语，不能说“说新的模型”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”表示歌唱，与“制作模型”的语境不符。"}], "explanations": {"吞": "语义：“吞”表示咽下，与“用三天时间制作模型”的语境不符。", "做出": "正确答案：“用三天时间做出了新的模型”表示制作完成，符合句意。", "说": "搭配：“说”的对象是话语，不能说“说新的模型”。", "唱": "语义：“唱”表示歌唱，与“制作模型”的语境不符。"}, "sentence_index": 6, "correct_answer": "做出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他做出了一个苹果。", "explanation": "这里应该用〈摘〉。“做出”指制作，树上现成的果实要用“摘”。"}, {"text": "我做出了一个电话。", "explanation": "这里应该用〈打〉。“做出”不能用于打电话，打电话要用“打”。"}, {"text": "科学家做出了一颗新星。", "explanation": "这里应该用〈发现〉。“做出”指人工制作，自然界已有的天体要用“发现”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7c39780-8988-4b42-a3b5-6f702742c09d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27372, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用纸没做出了一只小鸟。", "corrected_sentence": "他用纸做出了一只小鸟。", "error_description": "错误：“没”与“了”不能同时用于否定句中的“做出”。应去掉“没”，为“他用纸做出了一只小鸟”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7c39780-8988-4b42-a3b5-6f702742c09d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27372, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很快做出着一辆玩具车。", "corrected_sentence": "他很快做出了一辆玩具车。", "error_description": "错误：“做出”是结果动词，后面不能接“着”。完成的动作要用“了”，应为“他很快做出了一辆玩具车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7c39780-8988-4b42-a3b5-6f702742c09d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
