INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27378, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "说对了，没有错。", "primary_collocate": null, "pronunciation": "zhèng què", "ipa": "ʈʂɤŋ˥˩ tɕʰɥɛ˥˩", "syllable_count": 2, "sentences": [{"text": "你说得很正确，我同意。", "target_word": "正确", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他回答得完全正确。", "target_word": "正确", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师说我的答案正确。", "target_word": "正确", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的发音很正确，像中国人一样。", "target_word": "正确", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请在这里写出正确的日期。", "target_word": "正确", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你的想法正确，不用再改了。", "target_word": "正确", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个数字不正确，请再算一遍。", "target_word": "正确", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个句子的写法完全正确。", "target_word": "正确", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "考试结束后，老师告诉我们正确答案。", "target_word": "正确", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这道题我算了两次，结果都正确。", "target_word": "正确", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "不正确", "label": "否定式"}, {"form": "正确性", "label": "派生"}], "register": "中性", "sense_fingerprint": "形容答案、回答、写法、发音等答对了、没有错", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edbb42d2-d5e9-4e3a-bea1-4e5446f06e3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27378, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "正确", "is_correct": true, "explanation": "正确：说得对，没有错，修饰说话的内容，符合句意。"}, {"text": "雪白", "is_correct": false, "explanation": "体貌：「雪白」形容颜色，不能用来评价说话。"}, {"text": "幸福", "is_correct": false, "explanation": "语义：「幸福」形容心理感受，不能描述说话的样子。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：「瘦」形容人的体形，不能用来评价说话。"}], "explanations": {"正确": "正确：说得对，没有错，修饰说话的内容，符合句意。", "雪白": "体貌：「雪白」形容颜色，不能用来评价说话。", "幸福": "语义：「幸福」形容心理感受，不能描述说话的样子。", "瘦": "体貌：「瘦」形容人的体形，不能用来评价说话。"}, "sentence_index": 0, "correct_answer": "正确"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个房间很正确，我们就住这里。", "explanation": "这里应该用〈合适〉。正确用于答案、说法等的对错，不用来说房间是否适合居住。"}, {"text": "这家餐厅的音乐很正确，大家都很满意。", "explanation": "这里应该用〈好听〉。正确只判断对错，不用来评价音乐的好坏。"}, {"text": "这个计算工具的精确度很正确。", "explanation": "这里应该用〈准确〉。正确只判断对错，不能用来说程度的高低；测量结果与真实值相符的程度要用〈准确〉来说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7c39780-8988-4b42-a3b5-6f702742c09d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27378, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "正确", "is_correct": true, "explanation": "正确：表示判断对，修饰「数字」，符合句意，与「不」搭配表示否定。"}, {"text": "高兴", "is_correct": false, "explanation": "搭配：「高兴」形容人的情绪，不能用来形容「数字」。"}, {"text": "晴朗", "is_correct": false, "explanation": "语义：「晴朗」形容天气，不能用于「数字」。"}, {"text": "愉快", "is_correct": false, "explanation": "语义：「愉快」形容心情，不能用于「数字」。"}], "explanations": {"正确": "正确：表示判断对，修饰「数字」，符合句意，与「不」搭配表示否定。", "高兴": "搭配：「高兴」形容人的情绪，不能用来形容「数字」。", "晴朗": "语义：「晴朗」形容天气，不能用于「数字」。", "愉快": "语义：「愉快」形容心情，不能用于「数字」。"}, "sentence_index": 6, "correct_answer": "正确"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌很正确。", "explanation": "这里应该用〈好听〉。正确只判断对错，不能用来评价歌曲的好坏。"}, {"text": "我今天的心情很正确。", "explanation": "这里应该用〈好〉。正确只判断对错，心情的好坏不能用正确来说。"}, {"text": "今天的天气很正确。", "explanation": "这里应该用〈晴朗〉。正确只判断对错，不能用来形容天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7c39780-8988-4b42-a3b5-6f702742c09d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27378, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你的回答很正确性，老师很满意。", "corrected_sentence": "你的回答很正确，老师很满意。", "error_description": "错误形式：「正确性」；正确形式：「正确」。「正确性」是名词，不能用程度副词「很」修饰，这里应该用形容词「正确」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7c39780-8988-4b42-a3b5-6f702742c09d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27378, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个说法没正确，请大家注意。", "corrected_sentence": "这个说法不正确，请大家注意。", "error_description": "错误形式：「没正确」；正确形式：「不正确」。判断性形容词「正确」的否定要用「不」，不能用「没」来否定，应为「不正确」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7c39780-8988-4b42-a3b5-6f702742c09d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
