INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27382, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "表示事情应当这样做。", "primary_collocate": null, "pronunciation": "yīng gāi", "ipa": "iŋ˥ kaɪ˥", "syllable_count": 2, "sentences": [{"text": "过马路时应该看红绿灯。", "target_word": "应该", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你应该早点儿睡觉。", "target_word": "应该", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "在图书馆里应该小声说话。", "target_word": "应该", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃饭以前应该先洗手。", "target_word": "应该", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小朋友应该听老师的话。", "target_word": "应该", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "开车的人不应该喝酒。", "target_word": "应该", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们应该把垃圾放进垃圾桶。", "target_word": "应该", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐公共汽车时应该给老人让座。", "target_word": "应该", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友有困难，我们应该帮忙。", "target_word": "应该", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "借了别人的东西，应该按时还。", "target_word": "应该", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "不应该", "label": "否定式"}], "register": "中性", "sense_fingerprint": "应该：表示事情应当这样做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8ddd3f-1e11-496c-a1ad-5495bc12503a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27382, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "应该", "is_correct": true, "explanation": "正确：「过马路时应该看红绿灯」表示事情应当这样做，与句意相符。"}, {"text": "敢", "is_correct": false, "explanation": "语义：「敢」表示有胆量去做某事，「过马路时敢看红绿灯」不表示应当。"}, {"text": "肯", "is_correct": false, "explanation": "搭配：「肯」需要有意愿的主体，此处不能用「肯」来表示应当，搭配不当。"}, {"text": "愿意", "is_correct": false, "explanation": "语义：「愿意」表示乐意去做，与「过马路时……看红绿灯」表示的规范义不符。"}], "explanations": {"应该": "正确：「过马路时应该看红绿灯」表示事情应当这样做，与句意相符。", "敢": "语义：「敢」表示有胆量去做某事，「过马路时敢看红绿灯」不表示应当。", "肯": "搭配：「肯」需要有意愿的主体，此处不能用「肯」来表示应当，搭配不当。", "愿意": "语义：「愿意」表示乐意去做，与「过马路时……看红绿灯」表示的规范义不符。"}, "sentence_index": 0, "correct_answer": "应该"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他下个月应该去旅行，他还没买车票。", "explanation": "这里应该用〈大概〉。“应该”此处是推测义（大概会去），不是应当义。"}, {"text": "明天应该下雨，我还是想出去玩。", "explanation": "这里应该用〈可能〉。“应该”此处是推测义（大概会下雨），不是应当义。"}, {"text": "他应该不会唱歌，他从来不开口。", "explanation": "这里应该用〈大概〉。“应该不会”是推测义，不是应当义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '918f171c-e601-48c6-ab62-ef128fd25419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27382, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "应该", "is_correct": true, "explanation": "正确：「我们应该把垃圾放进垃圾桶」表示事情应当这样做，与句意相符。"}, {"text": "差点", "is_correct": false, "explanation": "语义：“差点”表示几乎发生，与“应当”义不符，句子变成险些把垃圾放进去。"}, {"text": "不必", "is_correct": false, "explanation": "语义：“不必”表示没有必要，与“应当”的意思相反。"}, {"text": "来不及", "is_correct": false, "explanation": "语义：“来不及”表示时间不够，与“应当”义不符。"}], "explanations": {"应该": "正确：「我们应该把垃圾放进垃圾桶」表示事情应当这样做，与句意相符。", "差点": "语义：“差点”表示几乎发生，与“应当”义不符，句子变成险些把垃圾放进去。", "不必": "语义：“不必”表示没有必要，与“应当”的意思相反。", "来不及": "语义：“来不及”表示时间不够，与“应当”义不符。"}, "sentence_index": 6, "correct_answer": "应该"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "借了别人的东西，他应该已经还了。", "explanation": "这里应该用〈大概〉。“应该”此处是推测义，不是应当义。"}, {"text": "他借的东西应该早就还了。", "explanation": "这里应该用〈可能〉。“应该”此处是推测义，不是应当义。"}, {"text": "他应该不会忘记还，你别担心。", "explanation": "这里应该用〈大概〉。“应该不会”是推测义，不是应当义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '918f171c-e601-48c6-ab62-ef128fd25419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27382, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子没应该玩火。", "corrected_sentence": "孩子不应该玩火。", "error_description": "错误：“没应该玩火”。正确：“不应该玩火”。情态动词“应该”的否定只能用“不”，不能用“没”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '918f171c-e601-48c6-ab62-ef128fd25419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27382, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在公共场所要应该保持安静。", "corrected_sentence": "在公共场所应该保持安静。", "error_description": "错误：“要应该保持”。正确：“应该保持”。“应该”与“要”都是情态动词，不能连用，应去掉多余的“要”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '918f171c-e601-48c6-ab62-ef128fd25419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
