INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27386, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87a84658-af8a-4322-bce7-fcff58dd6586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27386, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "向别人说你想做什么，请别人同意。", "primary_collocate": null, "pronunciation": "shēn qǐng", "ipa": "ʂən˥ tɕʰiŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我想申请换一个座位。", "target_word": "申请", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他向老师申请明天不交作业。", "target_word": "申请", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我向老板申请周五早点回家。", "target_word": "申请", "complexity_tier": "T3", "furigana": "wǒ xiàng lǎobǎn shēnqǐng zhōuwǔ zǎo diǎn huí jiā", "sentence_source": "generated"}, {"text": "我向经理申请了一天假。", "target_word": "申请", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她申请参加这次比赛，老师同意了。", "target_word": "申请", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟向妈妈申请养一只小狗。", "target_word": "申请", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们申请在教室里开一个会。", "target_word": "申请", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他申请提前下班，去接生病的女儿。", "target_word": "申请", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想向老师申请调到前排，可以吗？", "target_word": "申请", "complexity_tier": "T3", "furigana": "wǒ xiǎng xiàng lǎoshī shēnqǐng diào dào qiánpái, kěyǐ ma", "sentence_source": "generated"}, {"text": "她申请过一次，可是老师没有同意。", "target_word": "申请", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "申请了", "label": "完成体"}, {"form": "申请过", "label": "经历体"}, {"form": "申请书", "label": "复合"}], "register": "中性", "sense_fingerprint": "说出自己想做的事，请对方同意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab6374f-e90b-4270-b9f3-bb44f316482a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27386, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "申请", "is_correct": true, "explanation": "正确：shēn qǐng，说出自己想做的事，请对方同意。"}, {"text": "深情", "is_correct": false, "explanation": "声调不同：深情（shēn qíng）第二音节为阳平，与申请（shēn qǐng）的上声不同，意思是深厚的感情。"}, {"text": "神情", "is_correct": false, "explanation": "两个音节的声调都不同：神情（shén qíng）与申请（shēn qǐng）只差声调，意思是表情或神态。"}, {"text": "深井", "is_correct": false, "explanation": "声母不同：深井（shēn jǐng）第二音节为 j 开头，与申请的 q 不同，意思是很深的井。"}, {"text": "申明", "is_correct": false, "explanation": "声母与声调不同：申明（shēn míng）第二音节为 m 开头、阳平，与申请的 q 开头、上声不同，意思是公开说明。"}], "explanations": {"申请": "正确：shēn qǐng，说出自己想做的事，请对方同意。", "深情": "声调不同：深情（shēn qíng）第二音节为阳平，与申请（shēn qǐng）的上声不同，意思是深厚的感情。", "神情": "两个音节的声调都不同：神情（shén qíng）与申请（shēn qǐng）只差声调，意思是表情或神态。", "深井": "声母不同：深井（shēn jǐng）第二音节为 j 开头，与申请的 q 不同，意思是很深的井。", "申明": "声母与声调不同：申明（shēn míng）第二音节为 m 开头、阳平，与申请的 q 开头、上声不同，意思是公开说明。"}, "sentence_index": null, "correct_answer": "申请"}, "level_3": {"options": [{"text": "申请", "is_correct": true, "explanation": "正确：“申请换一个座位”表示说出自己想做的事，请对方同意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，不能说“吃换一个座位”，与句意不符。"}, {"text": "生气", "is_correct": false, "explanation": "配价：“生气”是不及物动词，后面不能直接接“换一个座位”这类动作宾语。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”指修复器物，换座位是人的行动，不能说修理。"}], "explanations": {"申请": "正确：“申请换一个座位”表示说出自己想做的事，请对方同意。", "吃": "语义：“吃”指进食，不能说“吃换一个座位”，与句意不符。", "生气": "配价：“生气”是不及物动词，后面不能直接接“换一个座位”这类动作宾语。", "修理": "语义：“修理”指修复器物，换座位是人的行动，不能说修理。"}, "sentence_index": 0, "correct_answer": "申请"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师申请同学们明天带书。", "explanation": "这里应该用〈通知〉。“申请”是说自己想做的事、请对方同意，老师告知学生要带书应说“通知”。"}, {"text": "我向老师申请了作业的要求。", "explanation": "这里应该用〈询问〉。“申请”的对象是自己想做的事，不能和“作业的要求”搭配，问要求应说“询问”。"}, {"text": "我申请了妈妈的生日礼物。", "explanation": "这里应该用〈准备〉。“申请”是请对方同意自己做某事，不用于备办东西，准备礼物应说“准备”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87a84658-af8a-4322-bce7-fcff58dd6586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27386, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "申请", "is_correct": true, "explanation": "正确：“同学们申请在教室里开一个会”表示请老师同意在教室开会，句意通顺。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”需要在水中进行，与“在教室里开一个会”的场景不符。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”指清理环境，不能与“开一个会”搭配成通顺的句子。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”是不及物动词，不能带“在教室里开一个会”这样的动作宾语。"}], "explanations": {"申请": "正确：“同学们申请在教室里开一个会”表示请老师同意在教室开会，句意通顺。", "游泳": "语义：“游泳”需要在水中进行，与“在教室里开一个会”的场景不符。", "打扫": "语义：“打扫”指清理环境，不能与“开一个会”搭配成通顺的句子。", "哭": "配价：“哭”是不及物动词，不能带“在教室里开一个会”这样的动作宾语。"}, "sentence_index": 6, "correct_answer": "申请"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我向老师申请了道歉。", "explanation": "这里应该用〈道歉〉。“申请”是请对方同意自己做某事，不能用来表示歉意，表达歉意应说“道歉”。"}, {"text": "我申请你考上了大学。", "explanation": "这里应该用〈祝贺〉。“申请”不能用来对他人的成就表态，表达祝贺应说“祝贺”。"}, {"text": "他向老板申请了迟到的原因。", "explanation": "这里应该用〈解释〉。“申请”是请对方同意自己的计划，说明迟到的原因应说“解释”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87a84658-af8a-4322-bce7-fcff58dd6586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27386, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他没有向老板申请了提前下班。", "corrected_sentence": "他没有向老板申请提前下班。", "error_description": "错误：“没有”与“了”同时使用，“申请”后多了“了”。正确：否定已发生的动作只用“没有”，应说“他没有向老板申请提前下班”，不说“他没有向老板申请了提前下班”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87a84658-af8a-4322-bce7-fcff58dd6586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27386, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想向班长申请换一张座位。", "corrected_sentence": "我想向班长申请换一个座位。", "error_description": "错误：量词“张”不能修饰“座位”，应用“个”。正确：应说“申请换一个座位”，“个”可修饰“座位”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87a84658-af8a-4322-bce7-fcff58dd6586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27388, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "接受", "is_correct": true, "explanation": "正确：“接受”与“拒绝”互为反义，指接收别人给的东西或同意别人的请求。"}, {"text": "清洗", "is_correct": false, "explanation": "“清洗”指把东西弄干净，与“拒绝”不构成反义关系。"}, {"text": "整理", "is_correct": false, "explanation": "“整理”指把东西归置有序，与“拒绝”不构成反义关系。"}, {"text": "陪伴", "is_correct": false, "explanation": "“陪伴”指和人在一起，与“拒绝”不构成反义关系。"}], "correct_answer": "接受", "explanations": {"接受": "正确：“接受”与“拒绝”互为反义，指接收别人给的东西或同意别人的请求。", "清洗": "“清洗”指把东西弄干净，与“拒绝”不构成反义关系。", "整理": "“整理”指把东西归置有序，与“拒绝”不构成反义关系。", "陪伴": "“陪伴”指和人在一起，与“拒绝”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87a84658-af8a-4322-bce7-fcff58dd6586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27388, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "接受", "is_correct": true, "explanation": "正确：“接受”与“拒绝”互为反义，指接收别人给的东西或同意别人的请求。"}, {"text": "讲解", "is_correct": false, "explanation": "“讲解”指把道理讲清楚，与“拒绝”不构成反义关系。"}, {"text": "赞美", "is_correct": false, "explanation": "“赞美”指称赞他人，与“拒绝”不构成反义关系。"}, {"text": "准备", "is_correct": false, "explanation": "“准备”指事先做好安排，与“拒绝”不构成反义关系。"}], "correct_answer": "接受", "explanations": {"接受": "正确：“接受”与“拒绝”互为反义，指接收别人给的东西或同意别人的请求。", "讲解": "“讲解”指把道理讲清楚，与“拒绝”不构成反义关系。", "赞美": "“赞美”指称赞他人，与“拒绝”不构成反义关系。", "准备": "“准备”指事先做好安排，与“拒绝”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87a84658-af8a-4322-bce7-fcff58dd6586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27388, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "说“不”，不要别人给的东西或事情。", "primary_collocate": null, "pronunciation": "jù jué", "ipa": "tɕy˥˩ tɕɥe˧˥", "syllable_count": 2, "sentences": [{"text": "他拒绝了朋友给的礼物。", "target_word": "拒绝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不饿，所以拒绝了她递来的蛋糕。", "target_word": "拒绝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小孩拒绝吃药，妈妈只好哄他。", "target_word": "拒绝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很客气，拒绝了我们请他吃饭的邀请。", "target_word": "拒绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人拒绝坐我让给他的座位。", "target_word": "拒绝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她想自己走，拒绝了哥哥的帮助。", "target_word": "拒绝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他生病了，拒绝去参加朋友的聚会。", "target_word": "拒绝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对不起，我不能拒绝你的好意。", "target_word": "拒绝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们给我钱，我拒绝了，因为那不是我的工作。", "target_word": "拒绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟拒绝和我分享他的玩具。", "target_word": "拒绝", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "拒绝了", "label": "完成体"}, {"form": "拒绝过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "对别人给的东西或邀请说不", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab6374f-e90b-4270-b9f3-bb44f316482a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27388, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拒绝", "is_correct": true, "explanation": "正确：“他拒绝了朋友给的礼物”，表示不接受别人给的东西。"}, {"text": "购买", "is_correct": false, "explanation": "语义：礼物是朋友给的，已经得到，不能说“购买”，与句意矛盾。"}, {"text": "咳嗽", "is_correct": false, "explanation": "配价：“咳嗽”是不及物动词，后面不能带“礼物”作宾语。"}, {"text": "微笑", "is_correct": false, "explanation": "配价：“微笑”是不及物动词，后面不能带“礼物”作宾语。"}], "explanations": {"拒绝": "正确：“他拒绝了朋友给的礼物”，表示不接受别人给的东西。", "购买": "语义：礼物是朋友给的，已经得到，不能说“购买”，与句意矛盾。", "咳嗽": "配价：“咳嗽”是不及物动词，后面不能带“礼物”作宾语。", "微笑": "配价：“微笑”是不及物动词，后面不能带“礼物”作宾语。"}, "sentence_index": 0, "correct_answer": "拒绝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她很感动，拒绝了朋友送的礼物，还把它戴在了手上。", "explanation": "这里应该用〈接受〉。拒绝表示不要，却又把礼物戴在手上，前后矛盾。"}, {"text": "爸爸拒绝了我的请求，马上把车钥匙递给了我。", "explanation": "这里应该用〈同意〉。拒绝表示不接受请求，与“马上把车钥匙递给了我”的顺从行为矛盾。"}, {"text": "他拒绝了我们的邀请，准时到了聚会。", "explanation": "这里应该用〈答应〉。拒绝邀请后又准时到场，前后矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87a84658-af8a-4322-bce7-fcff58dd6586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27388, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拒绝", "is_correct": true, "explanation": "正确：“他生病了，拒绝去参加朋友的聚会”，表示不接受参加聚会的邀请。"}, {"text": "奔跑", "is_correct": false, "explanation": "语义：生病时奔跑去参加聚会与句中的“生病”矛盾。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：生病时游泳去参加聚会与句中的“生病”矛盾。"}, {"text": "出血", "is_correct": false, "explanation": "语义：“出血”指流血，与“生病后去参加聚会”的句意不通。"}], "explanations": {"拒绝": "正确：“他生病了，拒绝去参加朋友的聚会”，表示不接受参加聚会的邀请。", "奔跑": "语义：生病时奔跑去参加聚会与句中的“生病”矛盾。", "游泳": "语义：生病时游泳去参加聚会与句中的“生病”矛盾。", "出血": "语义：“出血”指流血，与“生病后去参加聚会”的句意不通。"}, "sentence_index": 6, "correct_answer": "拒绝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我拒绝了这个星期的温度，所以多穿了一件衣服。", "explanation": "这里是把“拒绝”当成“不理会、不在乎”来用，但“拒绝”只用于别人提出的请求、建议或给予的东西，“温度”不能被拒绝。"}, {"text": "他拒绝了窗外的雨，所以把窗户打开了。", "explanation": "这里是把“拒绝”当成“挡住、阻隔”来用，但“拒绝”只用于别人提出的请求、建议或给予的东西，“雨”不能被拒绝。"}, {"text": "妈妈拒绝了今天的阳光，所以把窗帘拉上了。", "explanation": "这里是把“拒绝”当成“遮挡”来用，但“拒绝”只用于别人提出的请求、建议或给予的东西，“阳光”不能被拒绝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87a84658-af8a-4322-bce7-fcff58dd6586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27388, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他拒绝很干脆，我一点机会都没有。", "corrected_sentence": "他拒绝得很干脆，我一点机会都没有。", "error_description": "错误：“拒绝很干脆”，缺少连接状态补语的“得”；正确：“拒绝得很干脆”。动词后接形容词表示状态时要用“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87a84658-af8a-4322-bce7-fcff58dd6586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27388, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没有拒绝了我的好意，后来我就走了。", "corrected_sentence": "他没有拒绝我的好意，后来我就走了。", "error_description": "错误：“没有”与“了”同时使用，“拒绝”后多了“了”。正确：否定已发生的动作只用“没有”，应说“没有拒绝我的好意”，不说“没有拒绝了我的好意”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87a84658-af8a-4322-bce7-fcff58dd6586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
