INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27390, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "告诉别人一个东西很好。", "primary_collocate": null, "pronunciation": "tuī jiàn", "ipa": "tʰweɪ˥ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这家店的面很好吃，我推荐你试试。", "target_word": "推荐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友推荐这家医院，说医生很负责。", "target_word": "推荐", "complexity_tier": "T3", "furigana": "péng yǒu tuī jiàn zhè jiā yī yuàn, shuō yī shēng hěn fù zé。", "sentence_source": "generated"}, {"text": "我强烈推荐这部电影，非常好看。", "target_word": "推荐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他推荐的那本书我已经看完了。", "target_word": "推荐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸推荐我用这个牌子的牙膏。", "target_word": "推荐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请推荐一道你们店里最好的菜。", "target_word": "推荐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友推荐的旅馆又干净又便宜。", "target_word": "推荐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我推荐你去海边玩，那里很美。", "target_word": "推荐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都推荐这个软件，说它很好用。", "target_word": "推荐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板向客人推荐了今天的新茶。", "target_word": "推荐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "推荐了", "label": "体标"}, {"form": "推荐过", "label": "体标"}, {"form": "推荐信", "label": "复合"}, {"form": "推薦", "label": "繁体"}], "register": "中性", "sense_fingerprint": "告诉别人某东西很好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab6374f-e90b-4270-b9f3-bb44f316482a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27390, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "推荐", "is_correct": true, "explanation": "正确：表示告诉对方这家店的面好吃，值得试试，与句意相符。"}, {"text": "介绍", "is_correct": false, "explanation": "配价：“介绍”要带被介绍的事物，“介绍你试试”缺少对象，不成立。"}, {"text": "品尝", "is_correct": false, "explanation": "语义：“品尝”指自己尝味道，不能用来让别人试吃。"}, {"text": "夸奖", "is_correct": false, "explanation": "语义：“夸奖”是称赞，不表示让对方去试，与“试试”冲突。"}], "explanations": {"推荐": "正确：表示告诉对方这家店的面好吃，值得试试，与句意相符。", "介绍": "配价：“介绍”要带被介绍的事物，“介绍你试试”缺少对象，不成立。", "品尝": "语义：“品尝”指自己尝味道，不能用来让别人试吃。", "夸奖": "语义：“夸奖”是称赞，不表示让对方去试，与“试试”冲突。"}, "sentence_index": 0, "correct_answer": "推荐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他推荐了一个谎言。", "explanation": "这里应该用〈揭穿〉。推荐表示说某物好，不能用来指谎言这类坏东西。"}, {"text": "他推荐天气太热。", "explanation": "这里应该用〈埋怨〉。推荐表示说某物好，不能用来抱怨天气。"}, {"text": "他向我推荐了这件事的原因。", "explanation": "这里应该用〈说明〉。推荐表示说某东西好，不能用于解释事情的原因。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87a84658-af8a-4322-bce7-fcff58dd6586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27390, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "推荐", "is_correct": true, "explanation": "正确：“推荐的旅馆”指朋友认为好而推荐的旅馆，与“又干净又便宜”相符。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”含否定评价，与后句“又干净又便宜”的褒义冲突。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：旅馆被拆除后就无法再住，不可能“又干净又便宜”，句意矛盾。"}, {"text": "吐槽", "is_correct": false, "explanation": "语义：“吐槽”是挑剔抱怨，与“推荐”的褒扬含义及“又干净又便宜”的评价相反。"}], "explanations": {"推荐": "正确：“推荐的旅馆”指朋友认为好而推荐的旅馆，与“又干净又便宜”相符。", "批评": "语义：“批评”含否定评价，与后句“又干净又便宜”的褒义冲突。", "拆除": "语义：旅馆被拆除后就无法再住，不可能“又干净又便宜”，句意矛盾。", "吐槽": "语义：“吐槽”是挑剔抱怨，与“推荐”的褒扬含义及“又干净又便宜”的评价相反。"}, "sentence_index": 6, "correct_answer": "推荐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈推荐我的身体。", "explanation": "这里应该用〈担心〉。推荐表示说某物好，不能用来表达对身体的忧虑。"}, {"text": "他推荐黑夜。", "explanation": "这里应该用〈害怕〉。推荐表示说某物好，不能用来表达对黑夜的恐惧。"}, {"text": "父母推荐我的粗心。", "explanation": "这里应该用〈责怪〉。推荐表示说某物好，不能用来指责别人的粗心。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87a84658-af8a-4322-bce7-fcff58dd6586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27390, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我推荐了过这家店的面。", "corrected_sentence": "我推荐过这家店的面。", "error_description": "体标错误：“了”与“过”不能同时用在同一动词后，应说“推荐过这家店的面”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87a84658-af8a-4322-bce7-fcff58dd6586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27390, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我推荐他了一本好书。", "corrected_sentence": "我推荐了他一本好书。", "error_description": "体标位置错误：“了”应紧跟动词，说“推荐了他”，不能放在代词宾语“他”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87a84658-af8a-4322-bce7-fcff58dd6586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
