INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27392, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做东西时要用到的很小的、很重要的事情。", "primary_collocate": null, "pronunciation": "jì shù xì jié", "ipa": "tɕi˥˩ ʂu˥˩ ɕi˥˩ tɕje˧˥", "syllable_count": 4, "sentences": [{"text": "做这个模型时，每个技术细节都很重要。", "target_word": "技术细节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅一边做椅子，一边教我技术细节。", "target_word": "技术细节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个技术细节错了，机器就不能用了。", "target_word": "技术细节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把做蛋糕的技术细节都写在本子上。", "target_word": "技术细节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学做饭时，我常常忘记一些技术细节。", "target_word": "技术细节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新手做木工，要先注意技术细节。", "target_word": "技术细节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师傅很懂做鞋的技术细节。", "target_word": "技术细节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "视频里讲了修自行车的技术细节。", "target_word": "技术细节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些技术细节虽然小，却很重要。", "target_word": "技术细节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做手工时，别忽略技术细节。", "target_word": "技术细节", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "技術細節", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做东西时要注意的小而重要的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab6374f-e90b-4270-b9f3-bb44f316482a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27392, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "技术细节", "is_correct": true, "explanation": "正确：指做东西时要注意的小而重要的事，与“做这个模型”语境相符。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：做模型时需要注意的不是人的年龄，句意不通。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“每个心情都很重要”与做模型的具体工作无关，句意不通。"}, {"text": "八卦", "is_correct": false, "explanation": "语域：“八卦”是闲聊用语，与做模型的专业语境不符。"}], "explanations": {"技术细节": "正确：指做东西时要注意的小而重要的事，与“做这个模型”语境相符。", "年龄": "语义：做模型时需要注意的不是人的年龄，句意不通。", "心情": "语义：“每个心情都很重要”与做模型的具体工作无关，句意不通。", "八卦": "语域：“八卦”是闲聊用语，与做模型的专业语境不符。"}, "sentence_index": 0, "correct_answer": "技术细节"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这盘菜的技术细节很香。", "explanation": "这里应该用〈味道〉。技术细节指做东西时要用到的具体事情，不能用来形容菜的香气。"}, {"text": "他吃了一个技术细节。", "explanation": "这里应该用〈包子〉。技术细节指做东西时要注意的具体环节，不是可以吃的东西，不能说“吃了一个技术细节”。"}, {"text": "我的技术细节很疼。", "explanation": "这里应该用〈牙〉。技术细节指做东西时要注意的具体环节，不能用来说身体的疼痛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87a84658-af8a-4322-bce7-fcff58dd6586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27392, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "技术细节", "is_correct": true, "explanation": "正确：指做鞋时需要掌握的具体环节，与“很懂”的对象相符。"}, {"text": "股票", "is_correct": false, "explanation": "语义：股票与做鞋无关，“很懂做鞋的股票”不成立。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是做鞋的内容，句子搭配不通。"}, {"text": "段子", "is_correct": false, "explanation": "语域：“段子”是口语娱乐用语，与老师傅的专业技艺语域冲突。"}], "explanations": {"技术细节": "正确：指做鞋时需要掌握的具体环节，与“很懂”的对象相符。", "股票": "语义：股票与做鞋无关，“很懂做鞋的股票”不成立。", "天气": "语义：天气不是做鞋的内容，句子搭配不通。", "段子": "语域：“段子”是口语娱乐用语，与老师傅的专业技艺语域冲突。"}, "sentence_index": 6, "correct_answer": "技术细节"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的技术细节很合脚。", "explanation": "这里应该用〈鞋子〉。技术细节指做东西时要注意的具体环节，不能用来说穿着是否合脚。"}, {"text": "我的技术细节快到了。", "explanation": "这里应该用〈生日〉。技术细节指做东西时要注意的具体环节，不能用来说时间快到。"}, {"text": "今天的技术细节很蓝。", "explanation": "这里应该用〈天空〉。技术细节指做东西时要注意的具体环节，不能用来形容颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87a84658-af8a-4322-bce7-fcff58dd6586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27392, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "做木工时，这只技术细节不能忽略。", "corrected_sentence": "做木工时，这个技术细节不能忽略。", "error_description": "量词错误：“只”多用于动物或成对物品中的一个，不能修饰“技术细节”，应说“这个技术细节”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87a84658-af8a-4322-bce7-fcff58dd6586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27392, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想学会这些技术细节们。", "corrected_sentence": "我想学会这些技术细节。", "error_description": "词缀错误：“们”只用于人，抽象名词后不能加“们”，应说“这些技术细节”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87a84658-af8a-4322-bce7-fcff58dd6586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27394, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "违规", "is_correct": true, "explanation": "正确。“违规”与“合法”是反义词，指做事违反规则。"}, {"text": "宽敞", "is_correct": false, "explanation": "与“合法”无反义关系：“宽敞”说空间大，与规则无关。"}, {"text": "好吃", "is_correct": false, "explanation": "与“合法”无反义关系：“好吃”说味道，与规则无关。"}, {"text": "清凉", "is_correct": false, "explanation": "与“合法”无反义关系：“清凉”说温度或感觉，与规则无关。"}], "correct_answer": "违规", "explanations": {"违规": "正确。“违规”与“合法”是反义词，指做事违反规则。", "宽敞": "与“合法”无反义关系：“宽敞”说空间大，与规则无关。", "好吃": "与“合法”无反义关系：“好吃”说味道，与规则无关。", "清凉": "与“合法”无反义关系：“清凉”说温度或感觉，与规则无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5620aa9b-086b-46b2-96a5-0da3736dc0a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27394, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "违规", "is_correct": true, "explanation": "正确。“违规”与“合法”是反义词，指做事违反规则。"}, {"text": "冰冷", "is_correct": false, "explanation": "与“合法”无反义关系：“冰冷”说温度，与规则无关。"}, {"text": "狭窄", "is_correct": false, "explanation": "与“合法”无反义关系：“狭窄”说空间小，与规则无关。"}, {"text": "圆滑", "is_correct": false, "explanation": "与“合法”无反义关系：“圆滑”说处事或形状，与规则的符合与否无关。"}], "correct_answer": "违规", "explanations": {"违规": "正确。“违规”与“合法”是反义词，指做事违反规则。", "冰冷": "与“合法”无反义关系：“冰冷”说温度，与规则无关。", "狭窄": "与“合法”无反义关系：“狭窄”说空间小，与规则无关。", "圆滑": "与“合法”无反义关系：“圆滑”说处事或形状，与规则的符合与否无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5620aa9b-086b-46b2-96a5-0da3736dc0a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27394, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "做事情不违反规则。", "primary_collocate": null, "pronunciation": "hé fǎ", "ipa": "xɤ˧˥ fa˨˩˦", "syllable_count": 2, "sentences": [{"text": "比赛中这样拿球是合法的，裁判没有吹哨。", "target_word": "合法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "按照比赛规则，这样换人是合法的。", "target_word": "合法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下棋时这样走是合法的，你不能说他作弊。", "target_word": "合法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个动作不合法，所以裁判给了他黄牌。", "target_word": "合法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "游戏里这样升级是合法的，不会封号。", "target_word": "合法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的每一步棋都合法，对手没法抗议。", "target_word": "合法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请先看规则，再决定这样做合法不合法。", "target_word": "合法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在这个游戏里，用两张牌一起出是合法的。", "target_word": "合法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种打法在规则里是合法的，裁判不会罚你。", "target_word": "合法", "complexity_tier": "T3", "furigana": "hé fǎ", "sentence_source": "generated"}, {"text": "足球比赛中，用手碰球不合法，要罚球。", "target_word": "合法", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "合法性", "label": "复合"}], "register": "中性", "sense_fingerprint": "合法：做事符合规则", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T1: 3 words above tier T1 (max 2): 足球比赛 (Zipf 3.12), 用手 (Zipf 3.56), 罚球 (Zipf 3.1)']::text[], '33088bf9-1fe7-4ce5-b719-265e37e48a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27394, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "合法", "is_correct": true, "explanation": "正确。“这样拿球是合法的”说明这种做法符合比赛规则，与“裁判没有吹哨”一致。"}, {"text": "圆", "is_correct": false, "explanation": "语义：“圆”说形状，不能用来评价拿球的做法是否合规。"}, {"text": "轻", "is_correct": false, "explanation": "搭配：“轻”说重量，不能用来描述拿球这一动作的规则状态。"}, {"text": "响", "is_correct": false, "explanation": "语义：“响”说声音，与拿球是否符合规则无关。"}], "explanations": {"合法": "正确。“这样拿球是合法的”说明这种做法符合比赛规则，与“裁判没有吹哨”一致。", "圆": "语义：“圆”说形状，不能用来评价拿球的做法是否合规。", "轻": "搭配：“轻”说重量，不能用来描述拿球这一动作的规则状态。", "响": "语义：“响”说声音，与拿球是否符合规则无关。"}, "sentence_index": 0, "correct_answer": "合法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜的味道很合法，我每次都要吃两碗。", "explanation": "这里应该用〈合口〉。味道合胃口要用合口，合法说的是做事符合规则。"}, {"text": "这批零件的质量合法了，可以装在车上了。", "explanation": "这里应该用〈合格〉。质量达到标准要用合格，合法说的是做事符合规则。"}, {"text": "这首诗的韵脚很合法，读起来很顺。", "explanation": "这里应该用〈合辙〉。押韵相合要用合辙，合法不能用来形容韵脚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5620aa9b-086b-46b2-96a5-0da3736dc0a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27394, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "合法", "is_correct": true, "explanation": "正确。“这样做合法不合法”是正反问句，要求判断做法是否符合规则。"}, {"text": "方便", "is_correct": false, "explanation": "语义：“方便”说便利，“方便不合法”无法构成“正反问”，与规则判断无关。"}, {"text": "对", "is_correct": false, "explanation": "搭配：“对不合法”不能组成正反问，句子不通。"}, {"text": "安全", "is_correct": false, "explanation": "语义：“安全”说风险大小，与“不合法”组成的问句不成立。"}], "explanations": {"合法": "正确。“这样做合法不合法”是正反问句，要求判断做法是否符合规则。", "方便": "语义：“方便”说便利，“方便不合法”无法构成“正反问”，与规则判断无关。", "对": "搭配：“对不合法”不能组成正反问，句子不通。", "安全": "语义：“安全”说风险大小，与“不合法”组成的问句不成立。"}, "sentence_index": 6, "correct_answer": "合法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们两个的性格很合法，常常一起出去玩。", "explanation": "这里应该用〈合拍〉。性情相投要用合拍，合法不能用来形容人的性格。"}, {"text": "这件外套很合法，穿在身上很舒服。", "explanation": "这里应该用〈合身〉。衣服大小和款式适合身体要用合身，合法不能用来形容衣服。"}, {"text": "这把剪刀很合法，用起来很顺手。", "explanation": "这里应该用〈合用〉。用起来顺手、适宜要用合用，合法只说符合法律或规则。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5620aa9b-086b-46b2-96a5-0da3736dc0a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27394, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "队员合法的拦住了对手，裁判没有吹哨。", "corrected_sentence": "队员合法地拦住了对手，裁判没有吹哨。", "error_description": "错误：“合法”修饰动词“拦住”时要用“地”，不能用“的”。正确应为“合法地拦住”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5620aa9b-086b-46b2-96a5-0da3736dc0a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27394, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次抢断没合法，裁判判了犯规。", "corrected_sentence": "这次抢断不合法，裁判判了犯规。", "error_description": "错误：形容词“合法”的否定要用“不”，不用“没”。正确应为“不合法”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5620aa9b-086b-46b2-96a5-0da3736dc0a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27398, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11875eb6-5269-4e0d-a662-5715d3f338ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
