INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27400, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "号码是一串数字，用来找到一个人或一个东西。", "primary_collocate": null, "pronunciation": "hào mǎ", "ipa": "xɑʊ˥˩ ma˨˩˦", "syllable_count": 2, "sentences": [{"text": "你的号码是多少？我给你打电话。", "target_word": "号码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是我的新号码，请你记一下。", "target_word": "号码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "门上有号码，你看号码就能找到房间。", "target_word": "号码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我忘了他的号码，没法给他打电话。", "target_word": "号码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "快递单上有一个号码，用它能查到包裹。", "target_word": "号码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "停车场每个车位都有号码，记住号码就能找到车。", "target_word": "号码", "complexity_tier": "T3", "furigana": "hào mǎ", "sentence_source": "generated"}, {"text": "电话响了，可是屏幕上没有号码。", "target_word": "号码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每辆车都有自己的号码，警察靠它能找到车主。", "target_word": "号码", "complexity_tier": "T3", "furigana": "hào mǎ", "sentence_source": "generated"}, {"text": "他给了我一个号码，说有事可以找他。", "target_word": "号码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个号码打不通，你再试一下别的。", "target_word": "号码", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "手机号码", "label": "复合"}, {"form": "號碼", "label": "繁体"}], "register": "中性", "sense_fingerprint": "号码：用来找人或找东西的一串数字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33088bf9-1fe7-4ce5-b719-265e37e48a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27400, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "号码", "is_correct": true, "explanation": "正确。hào mǎ 指用来找人或找东西的一串数字。"}, {"text": "套马", "is_correct": false, "explanation": "tào（第四声）与 hào（第四声）只差声母，意思是“用绳索套住马”。"}, {"text": "报马", "is_correct": false, "explanation": "bào（第四声）与 hào（第四声）只差声母，意思是“旧时传递消息的人或马”。"}, {"text": "好马", "is_correct": false, "explanation": "hǎo（第三声）与 hào（第四声）声调不同，意思是“好马”。"}], "explanations": {"号码": "正确。hào mǎ 指用来找人或找东西的一串数字。", "套马": "tào（第四声）与 hào（第四声）只差声母，意思是“用绳索套住马”。", "报马": "bào（第四声）与 hào（第四声）只差声母，意思是“旧时传递消息的人或马”。", "好马": "hǎo（第三声）与 hào（第四声）声调不同，意思是“好马”。"}, "sentence_index": null, "correct_answer": "号码"}, "level_3": {"options": [{"text": "号码", "is_correct": true, "explanation": "正确。“你的号码是多少”问的是可以联系你的数字。"}, {"text": "体重", "is_correct": false, "explanation": "语义：问体重与“我给你打电话”不搭，句意说不通。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高与打电话无关，句子不成立。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能用“是多少”来问。"}], "explanations": {"号码": "正确。“你的号码是多少”问的是可以联系你的数字。", "体重": "语义：问体重与“我给你打电话”不搭，句意说不通。", "身高": "语义：身高与打电话无关，句子不成立。", "颜色": "搭配：“颜色”不能用“是多少”来问。"}, "sentence_index": 0, "correct_answer": "号码"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "全国的号码是十四亿。", "explanation": "这里应该用〈人口〉。一个地区的人数要用人口，号码是用来找到人或东西的数字。"}, {"text": "他的号码是一米八。", "explanation": "这里应该用〈身高〉。人的高矮要用身高，号码是用来找到人或东西的数字。"}, {"text": "我记下了他的一只号码，可是忘了带纸。", "explanation": "这里应该用〈个〉。号码用「个」计量；「只」常用于动物或成对物品中的一件，不适用于号码。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5620aa9b-086b-46b2-96a5-0da3736dc0a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27400, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "号码", "is_correct": true, "explanation": "正确。“屏幕上没有号码”指来电的号码没有显示。"}, {"text": "声音", "is_correct": false, "explanation": "语义：电话已经响了，不能说屏幕上没有声音，前后矛盾。"}, {"text": "铃声", "is_correct": false, "explanation": "搭配：屏幕不显示铃声，“屏幕上没有铃声”说不通。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：屏幕上显示的是文字或数字，不说温度。"}], "explanations": {"号码": "正确。“屏幕上没有号码”指来电的号码没有显示。", "声音": "语义：电话已经响了，不能说屏幕上没有声音，前后矛盾。", "铃声": "搭配：屏幕不显示铃声，“屏幕上没有铃声”说不通。", "温度": "搭配：屏幕上显示的是文字或数字，不说温度。"}, "sentence_index": 6, "correct_answer": "号码"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这批货的号码是一百箱。", "explanation": "这里应该用〈数量〉。货物多少用数量，号码是用来找人或找东西的数字。"}, {"text": "今天的号码是十月三十一日。", "explanation": "这里应该用〈日期〉。说哪一天要用日期，号码是用来找人或找东西的数字。"}, {"text": "他的号码是三十岁。", "explanation": "这里应该用〈年龄〉。说人几岁要用年龄，号码是用来找人或找东西的数字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5620aa9b-086b-46b2-96a5-0da3736dc0a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27400, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我找不到一只号码，急死了。", "corrected_sentence": "我找不到一个号码，急死了。", "error_description": "错误：“号码”的量词是“个”，“只”常用于动物或成对物品中的一件，不适用于号码。正确应为“一个号码”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5620aa9b-086b-46b2-96a5-0da3736dc0a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27400, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他给我写了三张号码，让我随时联系。", "corrected_sentence": "他给我写了三个号码，让我随时联系。", "error_description": "错误：号码的量词是「个」，不用「张」。正确应为「三个号码」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5620aa9b-086b-46b2-96a5-0da3736dc0a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
