INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27404, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "检查别人记的账有没有错。", "primary_collocate": null, "pronunciation": "shěn jì", "ipa": "ʂən˨˩˦ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "会计师来审计公司的账。", "target_word": "审计", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老板请人审计今年的账本。", "target_word": "审计", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们审计了商店的每一笔钱。", "target_word": "审计", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的账有错，所以要审计。", "target_word": "审计", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "银行每年都要审计一次。", "target_word": "审计", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小李正在审计学校的账目。", "target_word": "审计", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们想请专业的人审计这笔钱。", "target_word": "审计", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "审计这家公司的账很花时间。", "target_word": "审计", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理让他审计一下上个月的账。", "target_word": "审计", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他审计过很多小公司的账，从没出过错。", "target_word": "审计", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "审计了", "label": "体标"}, {"form": "审计过", "label": "体标"}, {"form": "审计师", "label": "复合"}, {"form": "審計", "label": "繁体"}], "register": "正式", "sense_fingerprint": "检查别人记的账有没有错", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '248f5714-59ca-4c41-94f7-b47c7a28fb77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27404, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "审计", "is_correct": true, "explanation": "正确：“审计”指检查别人记的账有没有错，句中“会计师来审计公司的账”符合这一用法。"}, {"text": "缝制", "is_correct": false, "explanation": "语义：“缝制”指用针线做衣物，与账目无关。"}, {"text": "播放", "is_correct": false, "explanation": "搭配：“播放”用于影音内容，不能用于账本。"}, {"text": "烘焙", "is_correct": false, "explanation": "语义：“烘焙”指做糕点，与账目毫不相关。"}], "explanations": {"审计": "正确：“审计”指检查别人记的账有没有错，句中“会计师来审计公司的账”符合这一用法。", "缝制": "语义：“缝制”指用针线做衣物，与账目无关。", "播放": "搭配：“播放”用于影音内容，不能用于账本。", "烘焙": "语义：“烘焙”指做糕点，与账目毫不相关。"}, "sentence_index": 0, "correct_answer": "审计"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈正在审计我的作业。", "explanation": "这里应该用〈检查〉。审计只针对别人记的账目，作业不是账，应说检查。"}, {"text": "作者正在审计这篇文章。", "explanation": "这里应该用〈修改〉。审计是检查账目的正误，改动文章应说修改。"}, {"text": "老师正在审计学生的试卷。", "explanation": "这里应该用〈批改〉。审计不用于评阅试卷，评阅试卷应说批改。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11875eb6-5269-4e0d-a662-5715d3f338ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27404, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "审计", "is_correct": true, "explanation": "正确：“审计”指检查账目是否有错，句中“请专业的人审计这笔钱”符合这一用法。"}, {"text": "鉴赏", "is_correct": false, "explanation": "搭配：“鉴赏”用于艺术品，不能说鉴赏“钱”。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”用于机器、器具，不能用于“钱”。"}, {"text": "演奏", "is_correct": false, "explanation": "语义：“演奏”指用乐器弹奏，与“这笔钱”无关。"}], "explanations": {"审计": "正确：“审计”指检查账目是否有错，句中“请专业的人审计这笔钱”符合这一用法。", "鉴赏": "搭配：“鉴赏”用于艺术品，不能说鉴赏“钱”。", "修理": "搭配：“修理”用于机器、器具，不能用于“钱”。", "演奏": "语义：“演奏”指用乐器弹奏，与“这笔钱”无关。"}, "sentence_index": 6, "correct_answer": "审计"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警察正在审计那个小偷。", "explanation": "这里应该用〈审讯〉。审讯是对人审问，审计只用于账目的核查。"}, {"text": "工人正在审计这块木板的长度。", "explanation": "这里应该用〈测量〉。审计用于账目核查，量取长度应说测量。"}, {"text": "海关正在审计护照的真伪。", "explanation": "这里应该用〈核实〉。审计指对账目的核查，护照真伪应说核实。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11875eb6-5269-4e0d-a662-5715d3f338ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27404, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们审计了过那家店的账。", "corrected_sentence": "他们审计过那家店的账。", "error_description": "错误：“了”与“过”不能同用。“审计过”表示曾经做过，后面不再加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11875eb6-5269-4e0d-a662-5715d3f338ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27404, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他不审计过那家店的账。", "corrected_sentence": "他没审计过那家店的账。", "error_description": "错误：否定已发生的经历要用“没”，“不”不能与“审计过”搭配。正确形式为“他没审计过那家店的账”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11875eb6-5269-4e0d-a662-5715d3f338ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
