INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27408, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "错误就是不对的事情。", "primary_collocate": null, "pronunciation": "cuò wù", "ipa": "tsʰwo˥˩ u˥˩", "syllable_count": 2, "sentences": [{"text": "这是我的错误。", "target_word": "错误", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个字有一个错误。", "target_word": "错误", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的作业里有很多错误。", "target_word": "错误", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师帮我找出了错误。", "target_word": "错误", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个人都会犯错误。", "target_word": "错误", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我不想再犯同样的错误。", "target_word": "错误", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考试时，我看到了自己的错误。", "target_word": "错误", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小孩子常常会犯错误，大人要有耐心。", "target_word": "错误", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说话时没有一点错误。", "target_word": "错误", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你要改正这个错误，不能再这样了。", "target_word": "错误", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "错误率", "label": "复合"}, {"form": "錯誤", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词：不对的事情，日常说的错、过失，常与犯、改正搭配", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33088bf9-1fe7-4ce5-b719-265e37e48a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27408, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "错误", "is_correct": true, "explanation": "错误：名词，指做得不对的事情，可以用“我的”领属。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不能被“我的”领属，不说“这是我的天气”。"}, {"text": "星期", "is_correct": false, "explanation": "搭配：“星期”是时间单位，不作领属对象，句子不通。"}, {"text": "秩序", "is_correct": false, "explanation": "语义：“秩序”不是“这是……”所指的具体事物，句意不成立。"}], "explanations": {"错误": "错误：名词，指做得不对的事情，可以用“我的”领属。", "天气": "搭配：“天气”不能被“我的”领属，不说“这是我的天气”。", "星期": "搭配：“星期”是时间单位，不作领属对象，句子不通。", "秩序": "语义：“秩序”不是“这是……”所指的具体事物，句意不成立。"}, "sentence_index": 0, "correct_answer": "错误"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他犯了一朵错误，老师很生气。", "explanation": "这里应该用〈个〉。〈朵〉用于花朵，不能用来计量错误。"}, {"text": "这份报告里有一枚错误，请你再看一遍。", "explanation": "这里应该用〈个〉。〈枚〉用于硬币、奖章等小件物品，不能用来计量错误。"}, {"text": "考试时我又出现了一座错误。", "explanation": "这里应该用〈个〉。〈座〉用于山、桥、建筑等大型固定物，不能用来计量错误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5620aa9b-086b-46b2-96a5-0da3736dc0a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27408, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "错误", "is_correct": true, "explanation": "错误：名词，是考试中自己做错的内容，可以“看到”。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道要用闻或尝来感知，不能用“看到”。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音要用听来感知，与“看到”的语境不符。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“温度”要用仪器测量，不说“看到了自己的温度”，句意不通。"}], "explanations": {"错误": "错误：名词，是考试中自己做错的内容，可以“看到”。", "味道": "语义：味道要用闻或尝来感知，不能用“看到”。", "声音": "语义：声音要用听来感知，与“看到”的语境不符。", "温度": "搭配：“温度”要用仪器测量，不说“看到了自己的温度”，句意不通。"}, "sentence_index": 6, "correct_answer": "错误"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他有个错误，爱迟到，大家都劝他改。", "explanation": "这里应该用〈毛病〉。毛病指习惯或性格上的缺点；错误指做错的事，不能说“有个错误，爱迟到”。"}, {"text": "这台机器的错误很好看。", "explanation": "这里应该用〈颜色〉。颜色指物体的色彩；错误指做错的事或不对的内容，不能用来形容外观。"}, {"text": "他送给我一个错误，我很高兴。", "explanation": "这里应该用〈礼物〉。礼物指赠送的东西；错误指做错的事或不对的内容，不能用来指送的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5620aa9b-086b-46b2-96a5-0da3736dc0a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27408, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把这枚错误改过来了，老师很满意。", "corrected_sentence": "他把这个错误改过来了，老师很满意。", "error_description": "错误形式：“这枚错误”，“枚”用于硬币、奖章等小件物品，不能用于错误。正确形式：“这个错误”，“个”是通用量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5620aa9b-086b-46b2-96a5-0da3736dc0a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27408, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你要改正这把小错误，不能再马虎了。", "corrected_sentence": "你要改正这个小错误，不能再马虎了。", "error_description": "错误形式：“这把小错误”，“把”是带柄器具的量词，不能用于错误。正确形式：“这个小错误”，“个”是通用量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5620aa9b-086b-46b2-96a5-0da3736dc0a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
