INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27422, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把原本别人不知道的事情说出来。", "primary_collocate": null, "pronunciation": "pī lù", "ipa": "pʰi˥ lu˥˩", "syllable_count": 2, "sentences": [{"text": "记者披露了这件事的真相。", "target_word": "披露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不愿意披露朋友的秘密。", "target_word": "披露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸披露了明星结婚的消息。", "target_word": "披露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在采访中披露了自己的病情。", "target_word": "披露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察没有披露案子的细节。", "target_word": "披露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他向媒体披露了内部的问题。", "target_word": "披露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个秘密一直没有人披露。", "target_word": "披露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要向别人披露我的地址。", "target_word": "披露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一位知情人披露了会议的内容。", "target_word": "披露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份文件披露了公司的丑闻。", "target_word": "披露", "complexity_tier": "T3", "furigana": "zhè fèn wén jiàn pī lù le gōng sī de chǒu wén.", "sentence_source": "generated"}], "morphological_forms": [{"form": "披露了", "label": "体标"}, {"form": "披露过", "label": "体标"}, {"form": "披露给", "label": "复合"}], "register": "书面语", "sense_fingerprint": "把秘密、内幕等别人不知道的事说出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32cca9b7-00be-47a2-8603-0c4deb9a2c2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27422, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "披露", "is_correct": true, "explanation": "披露：把别人不知道的真相说出来，与“真相”搭配，句意通顺。"}, {"text": "编造", "is_correct": false, "explanation": "语义：编造是假造，与“真相”相反，句意矛盾。"}, {"text": "同意", "is_correct": false, "explanation": "配价：“同意”接建议、要求，不接“真相”。"}, {"text": "收藏", "is_correct": false, "explanation": "搭配：“收藏”用于物品，不说收藏真相。"}], "explanations": {"披露": "披露：把别人不知道的真相说出来，与“真相”搭配，句意通顺。", "编造": "语义：编造是假造，与“真相”相反，句意矛盾。", "同意": "配价：“同意”接建议、要求，不接“真相”。", "收藏": "搭配：“收藏”用于物品，不说收藏真相。"}, "sentence_index": 0, "correct_answer": "披露"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把行李披露在床上。", "explanation": "这里应该用〈放〉。披露指把秘密公开，不指把东西摆放在某处；放行李应说“放在床上”。"}, {"text": "他的皮肤长时间披露在阳光下。", "explanation": "这里应该用〈暴露〉。披露指把秘密、内幕说出来，皮肤被晒在阳光下是身体的状态，应说“暴露”。"}, {"text": "她把外套披露在身上，走出了房间。", "explanation": "这里应该用〈披上〉。披露是公开秘密，不表示把衣服披在身上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75e2b6d-6326-4a0d-8575-9aa579d848ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27422, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "披露", "is_correct": true, "explanation": "披露：把秘密说出来，与“没有人”搭配，句意通顺。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃是进食，秘密不能被吃，句意荒谬。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”用于歌曲，不说唱秘密。"}, {"text": "穿", "is_correct": false, "explanation": "配价：“穿”的宾语是衣物，不接“秘密”。"}], "explanations": {"披露": "披露：把秘密说出来，与“没有人”搭配，句意通顺。", "吃": "语义：吃是进食，秘密不能被吃，句意荒谬。", "唱": "搭配：“唱”用于歌曲，不说唱秘密。", "穿": "配价：“穿”的宾语是衣物，不接“秘密”。"}, "sentence_index": 6, "correct_answer": "披露"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把窗户披露得很大，屋里一下子亮了。", "explanation": "这里应该用〈打开〉。披露指把信息公开，不表示打开窗户。"}, {"text": "她故意披露了这件事，不让任何人知道。", "explanation": "这里应该用〈隐瞒〉。披露是把事情公开，与“不让任何人知道”自相矛盾。"}, {"text": "他把被子披露在院子里晒太阳。", "explanation": "这里应该用〈晾〉。披露指把秘密公开，不指晾晒被子；被子应说“晾在院子里”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75e2b6d-6326-4a0d-8575-9aa579d848ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27422, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他已经把这件事的真相披露起来了。", "corrected_sentence": "他已经把这件事的真相披露出来了。", "error_description": "“披露”后应接趋向补语“出来”，表示把真相公开出来；“起来”不能这样用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75e2b6d-6326-4a0d-8575-9aa579d848ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27422, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位记者曾经披露过过这个秘密。", "corrected_sentence": "这位记者曾经披露过这个秘密。", "error_description": "“披露过”后已有“过”，不能再加“过”；应写作“曾经披露过这个秘密”，“过”只用一次。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75e2b6d-6326-4a0d-8575-9aa579d848ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
